module up_down_counter (
    input clk,
    input reset,
    input up_down,
    output reg [15:0] count
);

always @(posedge clk) begin
    if (reset)
        count <= 16'd0;
    else if (up_down)
        count <= count + 16'd1;
    else
        count <= count - 16'd1;
end

endmodule

