module fsm (
    input IN,
    input CLK,
    input RST,
    output MATCH
);

reg [2:0] state;
parameter S0 = 3'b000,
          S1 = 3'b001,
          S2 = 3'b010,
          S3 = 3'b011,
          S4 = 3'b100;

always @(posedge CLK) begin
    if (RST)
        state <= S0;
    else
        case (state)
            S0: state <= IN ? S1 : S0;
            S1: state <= (IN == 0) ? S2 : S1;
            S2: state <= (IN == 0) ? S3 : S1;
            S3: state <= (IN == 1) ? S4 : S0;
            S4: state <= (IN == 1) ? S1 : S0;
            default: state <= S0;
        endcase
end

assign MATCH = RST ? 1'b0 : ((state == S4) && (IN == 1));

endmodule

