module asyn_fifo #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wclk,
    input wrstn,
    input winc,
    input [WIDTH-1:0] wdata,
    output wfull,
    input rclk,
    input rrstn,
    input rinc,
    output rempty,
    output [WIDTH-1:0] rdata
);


reg [3:0] waddr_bin;
wire [3:0] waddr_bin_next = waddr_bin + (winc && !wfull);
wire wenc = (winc && !wfull);


reg [3:0] raddr_bin;
wire [3:0] raddr_bin_next = raddr_bin + (rinc && !rempty);
wire renc = (rinc && !rempty);


wire [3:0] wptr_gray_next = waddr_bin ^ (waddr_bin >> 1);
wire [3:0] rptr_gray_next = raddr_bin ^ (raddr_bin >> 1);

reg [3:0] wptr_gray, rptr_gray;

always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) wptr_gray <= 4'b0;
    else wptr_gray <= wptr_gray_next;
end

always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) rptr_gray <= 4'b0;
    else rptr_gray <= rptr_gray_next;
end


reg [3:0] rptr_gray_sync1, rptr_gray_sync2;
always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        rptr_gray_sync1 <= 4'b0;
        rptr_gray_sync2 <= 4'b0;
    end else begin
        rptr_gray_sync1 <= rptr_gray;
        rptr_gray_sync2 <= rptr_gray_sync1;
    end
end


reg [3:0] wptr_gray_sync1, wptr_gray_sync2;
always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        wptr_gray_sync1 <= 4'b0;
        wptr_gray_sync2 <= 4'b0;
    end else begin
        wptr_gray_sync1 <= wptr_gray;
        wptr_gray_sync2 <= wptr_gray_sync1;
    end
end


wire [3:0] rptr_bin_sync = rptr_gray_sync2 ^ (rptr_gray_sync2 >> 1);
wire [3:0] wptr_bin = waddr_bin;
assign wfull = (wptr_gray_next == {~rptr_bin_sync[3:2], rptr_bin_sync[1:0]});

wire [3:0] wptr_bin_sync = wptr_gray_sync2 ^ (wptr_gray_sync2 >> 1);
assign rempty = (rptr_gray_next == wptr_gray_sync2);


always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        waddr_bin <= 4'b0;
    end else if (wenc) begin
        waddr_bin <= waddr_bin_next;
    end
end

always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        raddr_bin <= 4'b0;
    end else if (renc) begin
        raddr_bin <= raddr_bin_next;
    end
end


