module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

reg [1:0] state;
localparam S0 = 2'b00,
           S1 = 2'b01,
           S2 = 2'b10;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        state <= S0;
        data_out <= 1'b0;
    end else begin
        case (state)
            S0: begin
                state <= data_in ? S1 : S0;
                data_out <= 1'b0;
            end
            S1: begin
                state <= data_in ? S1 : S2;
                data_out <= 1'b0;
            end
            S2: begin
                state <= S0;
                data_out <= 1'b1;
            end
            default: begin
                state <= S0;
                data_out <= 1'b0;
            end
        endcase
    end
end

endmodule

