module alu (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output reg [31:0] r,
    output zero,
    output reg carry,
    output negative,
    output reg overflow,
    output flag
);

    parameter ADD  = 6'b100000;
    parameter ADDU = 6'b100001;
    parameter SUB  = 6'b100010;
    parameter SUBU = 6'b100011;
    parameter AND  = 6'b100100;
    parameter OR   = 6'b100101;
    parameter XOR  = 6'b100110;
    parameter NOR  = 6'b100111;
    parameter SLT  = 6'b101010;
    parameter SLTU = 6'b101011;
    parameter SLL  = 6'b000000;
    parameter SRL  = 6'b000010;
    parameter SRA  = 6'b000011;
    parameter SLLV = 6'b000100;
    parameter SRLV = 6'b000110;
    parameter SRAV = 6'b000111;
    parameter LUI  = 6'b001111;

    reg [32:0] res;
    reg carry_temp;
    reg overflow_temp;

    always @(*) begin
        case (aluc)
            ADD: begin
                res = {1'b0, a} + {1'b0, b};
                overflow_temp = (a[31] == b[31]) && (res[31] != a[31]);
                carry_temp = res[32];
                r = res[31:0];
            end
            SUB: begin
                res = {1'b0, a} - {1'b0, b};
                overflow_temp = (a[31] != b[31]) && (res[31] != a[31]);
                carry_temp = res[32];
                r = res[31:0];
            end
            ADDU: begin
                res = {1'b0, a} + {1'b0, b};
                overflow_temp = 1'b0;
                carry_temp = res[32];
                r = res[31:0];
            end
            SUBU: begin
                res = {1'b0, a} - {1'b0, b};
                overflow_temp = 1'b0;
                carry_temp = res[32];
