module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

    reg [7:0] dividend_abs;
    reg [7:0] divisor_abs;
    reg dividend_sign, divisor_sign;
    reg [15:0] SR;
    reg [3:0] cnt;
    reg start_cnt;
    reg quotient_sign, remainder_sign;
    reg [7:0] quotient, remainder;

    wire [7:0] NEG_DIVISOR = ~divisor_abs + 1;


    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 1'b0;
            SR <= 16'b0;
            cnt <= 4'b0;
            start_cnt <= 1'b0;
            quotient <= 8'b0;
            remainder <= 8'b0;
            dividend_sign <= 1'b0;
            divisor_sign <= 1'b0;
            quotient_sign <= 1'b0;
            remainder_sign <= 1'b0;
        end else begin
            if (opn_valid && !res_valid) begin

                if (sign) begin
                    dividend_sign <= dividend[7];
                    divisor_sign <= divisor[7];
                    dividend_abs <= dividend[7] ? (~dividend + 1) : dividend;
                    divisor_abs <= divisor[7] ? (~divisor + 1) : divisor;
                end else begin
                    dividend_sign <= 1'b0;
                    divisor_sign <= 1'b0;
                    dividend_abs <= dividend;
                    divisor_abs <= divisor;
                end
                remainder_sign <= sign ? dividend[7] : 1'b0;
                quotient_sign <= (sign && (dividend[7] ^ divisor[7])) ? 1'b1 : 1'b0;

                SR <= {8'b0, dividend_abs} << 1;
                cnt <= 4'd1;
                start_cnt <= 1'b1;
                res_valid <= 1'b0;
                quotient <= 8'b0;
                remainder <= 8'b0;
            end else if (start_cnt) begin
                if (cnt == 4'd8) begin

                    start_cnt <= 1'b0;
                    cnt <= 4'd0;
                    res_valid <= 1'b1;
                    result[15:8] <= remainder_sign ? (~remainder + 1) : remainder;
                    result[7:0] <= quotient_sign ? (~quotient + 1) : quotient;
                end else begin

                    wire [8:0] sub_result = SR[15:8] - NEG_DIVISOR;
                    wire carry_out = sub_result[8];
                    if (carry_out) begin

                        quotient <= {quotient[6:0], 1'b1};
                        remainder <= sub_result[7:0];
                        SR <= {sub_result[7:0], quotient, 1'b1} << 1;
                    end else begin

                        quotient <= {quotient[6:0], 1'b0};
                        remainder <= SR[15:8];
                        SR <= {SR[15:8], quotient, 1'b0} << 1;
                    end
                    cnt <= cnt + 1;
                end
            end else begin
                res_valid <= 1'b0;
            end
        end
    end

endmodule

