module accu (
    input clk,
    input rst_n,
    input [7:0] data_in,
    input valid_in,
    output reg valid_out,
    output reg [9:0] data_out
);

reg [1:0] cnt;
reg [7:0] reg0, reg1, reg2, reg3;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        cnt <= 2'b0;
        reg0 <= 8'b0;
        reg1 <= 8'b0;
        reg2 <= 8'b0;
        reg3 <= 8'b0;
        valid_out <= 1'b0;
        data_out <= 10'b0;
    end else begin
        valid_out <= 1'b0;

        if (valid_in) begin
            case (cnt)
                2'b00: reg0 <= data_in;
                2'b01: reg1 <= data_in;
                2'b10: reg2 <= data_in;
                2'b11: reg3 <= data_in;
            endcase
            cnt <= cnt + 1;
        end


        if (valid_in && cnt == 2'b11) begin
            data_out <= reg0 + reg1 + reg2 + data_in;
            valid_out <= 1'b1;
        end
    end
end

endmodule

