module fixed_point_adder #(parameter Q=16, N=32) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output wire [N-1:0] c
);

wire a_sign = a[N-1];
wire b_sign = b[N-1];
wire same_sign = (a_sign == b_sign);

wire [N-1:0] abs_a = a_sign ? (~a + 1) : a;
wire [N-1:0] abs_b = b_sign ? (~b + 1) : b;

wire abs_compare = (abs_a > abs_b);

reg [N-1:0] res;

always @(*) begin
    if (same_sign) begin
        res = a + b;
    end else begin
        if (abs_compare) begin
            res = abs_a - abs_b;
            res[N-1] = a_sign;
        end else begin
            res = abs_b - abs_a;
            res[N-1] = b_sign;
        end
    end
end

assign c = res;

endmodule

