module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

    reg [2:0] counter;
    reg a_sign, b_sign, z_sign;
    reg [7:0] a_exponent, b_exponent, z_exponent;
    reg [22:0] a_mantissa, b_mantissa;
    reg [47:0] product;
    reg guard_bit, round_bit, sticky;
    reg [23:0] a_mantissa_full, b_mantissa_full;
    reg [23:0] product_mantissa;
    reg [9:0] exponent_sum;
    reg [22:0] mantissa_rounded;
    reg [9:0] exponent_rounded;
    reg [31:0] result_reg;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b0;
            z <= 32'b0;
        end else begin
            case (counter)

                3'b000: begin
                    a_sign <= a[31];
                    b_sign <= b[31];


                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];

                    a_mantissa_full <= (a[30:23] == 8'd0) ? {1'b0, a[22:0]} : {1'b1, a[22:0]};
                    b_mantissa_full <= (b[30:23] == 8'd0) ? {1'b0, b[22:0]} : {1'b1, b[22:0]};


                    if ((a[30:23] == 8'hff && |a[22:0]) || 
                        (b[30:23] == 8'hff && |b[22:0])) begin
                        z <= {a_sign ^ b_sign, 8'hff, 23'h000001};
                    end else if ((a[30:23] == 8'hff) || (b[30:23] == 8'hff)) begin
                        z <= {a_sign ^ b_sign, 8'hff, 23'b0};
                    end else if ((a[30:23] == 8'h00 && ~|a[22:0]) || 
                                (b[30:23] == 8'h00 && ~|b[22:0])) begin
                        z <= {a_sign ^ b_sign, 8'h00, 23'b0};
                    end else begin
                        counter <= 3'b001;
                    end
                end


                3'b001: begin
                    product <= a_mantissa_full * b_mantissa_full;
                    counter <= 3'b010;
                end


                3'b010: begin
                    if (product[47]) begin
                        product_mantissa <= product[47:24];
                        exponent_sum <= a_exponent + b_exponent + 1 + 9'd127;
                    end else begin
                        product_mantissa <= product[46:23];
                        exponent_sum <= a_exponent + b_exponent + 9'd127;
                    end

                    counter <= 3'b011;
                end


                3'b011: begin
                    guard_bit <= product[22];
                    round_bit <= product[21];
                    sticky <= |product[20:0];


                    if (guard_bit && (round_bit || sticky || product_mantissa[0])) begin
                        mantissa_rounded <= product_mantissa + 24'd1;
                        exponent_rounded <= exponent_sum + 10'd1;
                    end else begin
                        mantissa_rounded <= product_mantissa;
                        exponent_rounded <= exponent_sum;
                    end


                    if (exponent_rounded[9] || exponent_rounded >= 10'd255) begin
                        z <= {a_sign ^ b_sign, 8'hff, 23'b0};
                    end else if (exponent_rounded <= 10'd0) begin
                        z <= {a_sign ^ b_sign, 8'h0, 23'b0};
                    end else begin
                        z <= {a_sign ^ b_sign, exponent_rounded[7:0], mantissa_rounded[22:0]};
                    end

                    counter <= 3'b000;
                end

                default: counter <= 3'b000;
            endcase
        end
    end

endmodule

