module sub_64bit (
    input  [63:0] A,
    input  [63:0] B,
    output [63:0] result,
    output overflow
);

    assign result = A - B;

    wire A_sign = A[63];
    wire B_sign = B[63];
    wire result_sign = result[63];

    wire pos_overflow = (A_sign == 1'b0) && (B_sign == 1'b1) && (result_sign == 1'b1);
    wire neg_overflow = (A_sign == 1'b1) && (B_sign == 1'b0) && (result_sign == 1'b0);

    assign overflow = pos_overflow || neg_overflow;

endmodule

