    .raddr(raddr_bin),
    .rdata(rdata)
);

reg [3:0] waddr_bin;
wire wen;
always @(posedge wclk or negedge wrstn) begin
    if (!wrstn)
        waddr_bin <= 0;
    else if (wen)
        waddr_bin <= waddr_bin + 1;
end

reg [3:0] raddr_bin;
wire ren;
always @(posedge rclk or negedge rrstn) begin
    if (!rrstn)
        raddr_bin <= 0;
    else if (ren)
        raddr_bin <= raddr_bin + 1;
end

function [3:0] bin2gray;
    input [3:0] bin;
    begin
        bin2gray = bin ^ (bin >> 1);
    end
endfunction

reg [3:0] wptr, rptr;
assign wptr = bin2gray(waddr_bin);
assign rptr = bin2gray(raddr_bin);

reg [3:0] rptr_gray_sync_wclk_0, rptr_gray_sync_wclk_1;
always @(posedge wclk) begin
    rptr_gray_sync_wclk_0 <= rptr;
    rptr_gray_sync_wclk_1 <= rptr_gray_sync_wclk_0;
end
wire [3:0] rptr_gray_sync_wclk = rptr_gray_sync_wclk_1;

reg [3:0] wptr_gray_sync_rclk_0, wptr_gray_sync_rclk_1;
always @(posedge rclk) begin
    wptr_gray_sync_rclk_0 <= wptr;
    wptr_gray_sync_rclk_1 <= wptr_gray_sync_rclk_0;
end
wire [3:0] wptr_gray_sync_rclk = wptr_gray_sync_rclk_1;

function [3:0] gray2bin;
    input [3:0] gray;
    reg [3:0] bin;
    integer i;
    begin
        bin[3] = gray[3];
        for (i=2;
 i>=0;
 i=i-1)
            bin[i] = bin[i+1] ^ gray[i];
        gray2bin = bin;
    end
endfunction

wire [3:0] rptr_bin_sync = gray2bin(wptr_gray_sync_rclk);
wire [3:0] wptr_bin_sync = gray2bin(rptr_gray_sync_wclk);

assign rempty = (rptr == rptr_gray_sync_wclk);
assign wfull = (wptr[3] != rptr_bin_sync[3]) &&
               (wptr[2] != rptr_bin_sync[2]) &&
               (wptr[1:0] == rptr_bin_sync[1:0]);

assign wen = winc && ~wfull;
assign ren = rinc && ~rempty;

endmodule

