module LIFObuffer (
    input [3:0] dataIn,
    input RW,
    input EN,
    input Rst,
    input Clk,
    output EMPTY,
    output FULL,
    output reg [3:0] dataOut
);

reg [3:0] stack_mem [0:3];

reg [2:0] SP;

integer i;

assign EMPTY = (SP == 4);

assign FULL = (SP == 0);


always @(posedge Clk) begin
    if (EN) begin
        if (Rst) begin

            SP <= 4;
            for (i = 0;
 i < 4;
 i = i + 1)
                stack_mem[i] <= 4'b0;
        end else begin
            if (RW) begin 
                if (!EMPTY) begin
                    dataOut <= stack_mem[SP-1];

                    stack_mem[SP-1] <= 4'b0;

                    SP <= SP + 1;

                end
            end else begin 
                if (!FULL) begin
                    stack_mem[SP-1] <= dataIn;

                    SP <= SP - 1;

                end
            end
        end
    end
end

endmodule

