module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

reg [1:0] state, next_state;

parameter IDLE = 2'b00;
parameter S1 = 2'b01;
parameter S2 = 2'b10;


always @(*) begin
    case (state)
        IDLE: next_state = data_in ? IDLE : S1;
        S1: begin
            if (data_in == 1)
                next_state = S2;
            else if (data_in == 0)
                next_state = S1;
            else
                next_state = IDLE;
        end
        S2: next_state = (data_in == 0) ? IDLE : IDLE;
        default: next_state = IDLE;
    endcase
end


always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        state <= IDLE;
        data_out <= 0;
    end else begin
        state <= next_state;
        case (state)
            IDLE: data_out <= 0;
            S1: data_out <= 0;
            S2: data_out <= (data_in == 0) ? 1 : 0;
            default: data_out <= 0;
        endcase
    end
end

endmodule

