module alu (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output reg [31:0] r,
    output zero,
    output carry,
    output negative,
    output overflow,
    output flag
);

parameter ADD  = 6'b100000;
parameter ADDU = 6'b100001;
parameter SUB  = 6'b100010;
parameter SUBU = 6'b100011;
parameter AND  = 6'b100100;
parameter OR   = 6'b100101;
parameter XOR  = 6'b100110;
parameter NOR  = 6'b100111;
parameter SLT  = 6'b101010;
parameter SLTU = 6'b101011;
parameter SLL  = 6'b000000;
parameter SRL  = 6'b000010;
parameter SRA  = 6'b000011;
parameter SLLV = 6'b000100;
parameter SRLV = 6'b000110;
parameter SRAV = 6'b000111;
parameter LUI  = 6'b001111;

reg [32:0] add_sum, sub_sum;
reg add_carry, sub_carry, add_overflow, sub_overflow;

always @(*) begin
    case (aluc)
        ADD: begin
            add_sum = {1'b0, a} + {1'b0, b};
            r = add_sum[31:0];
            add_carry = add_sum[32];
            add_overflow = (a[31] == b[31]) && (add_sum[31] != a[31]);
        end
        ADDU: begin
            add_sum = {1'b0, a} + {1'b0, b};
            r = add_sum[31:0];
            add_carry = add_sum[32];
        end
        SUB: begin
            sub_sum = {1'b0, a} - {1'b0, b};
            r = sub_sum[31:0];
            sub_carry = sub_sum[32];
            sub_overflow = (a[31] != b[31]) && (sub_sum[31] == b[31]);
        end
        SUBU: begin
            sub_sum = {1'b0, a} - {1'b0, b};
            r = sub_sum[31:0];
            sub_carry = sub_sum[32];
        end
        AND:  r = a & b;
        OR:   r = a | b;
        XOR:  r = a ^ b;
        NOR:  r = ~(a | b);
        SLT:  r = ($signed(a) < $signed(b)) ? 32'b1 : 32'b0;
        SLTU: r = (a < b) ? 32'b1 : 32'b0;
        SLL:  r = a << b[4:0];
        SRL:  r = a >> b[4:0];
        SRA:  r = $signed(a) >>> b[4:0];
        SLLV: r = a << b[4:0];
        SRLV: r = a >> b[4:0];
        SRAV: r = $signed(a) >>> b[4:0];
        LUI:  r = {a[15:0], 16'b0};
        default: r = 32'bz;
    endcase
end

assign zero = (r == 32'b0) ? 1'b1 : 1'b0;
assign negative = r[31];
assign flag = (aluc == SLT || aluc == SLTU) ? r[0] : 1'bz;
assign carry = (aluc == ADD || aluc == ADDU) ? add_carry :
               (aluc == SUB || aluc == SUBU) ? sub_carry : 1'b0;
assign overflow = (aluc == ADD) ? add_overflow :
                  (aluc == SUB) ? sub_overflow : 1'b0;

endmodule

