module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

    reg [7:0] dividend_abs, divisor_abs;
    reg dividend_sign, divisor_sign;
    reg [15:0] SR;
    reg [3:0] cnt;
    reg start_cnt;
    reg [7:0] quotient, remainder;
    wire [7:0] NEG_DIVISOR;
    wire borrow;
    wire [7:0] sub_result;


    always @(*) begin
        dividend_sign = sign ? dividend[7] : 1'b0;
        divisor_sign = sign ? divisor[7] : 1'b0;
        dividend_abs = sign ? (dividend[7] ? -dividend : dividend) : dividend;
        divisor_abs = sign ? (divisor[7] ? -divisor : divisor) : divisor;
    end

    assign NEG_DIVISOR = -divisor_abs;


    assign {borrow, sub_result} = {1'b0, SR[15:8]} - {1'b0, NEG_DIVISOR};


    wire [15:0] next_SR;
    assign next_SR = (borrow) ? {sub_result, SR[7:1], 1'b0} : {sub_result, SR[7:1], 1'b1};

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 1'b0;
            result <= 16'b0;
            SR <= 16'b0;
            cnt <= 4'b0;
            start_cnt <= 1'b0;
            dividend_sign <= 1'b0;
            divisor_sign <= 1'b0;
            quotient <= 8'b0;
            remainder <= 8'b0;
        end else begin
            if (opn_valid && !res_valid) begin
                dividend_sign <= sign ? dividend[7] : 1'b0;
                divisor_sign <= sign ? divisor[7] : 1'b0;
                dividend_abs <= sign ? (dividend[7] ? -dividend : dividend) : dividend;
                divisor_abs <= sign ? (divisor[7] ? -divisor : divisor) : divisor;
                SR <= {dividend_abs, 8'b0} << 1;
                cnt <= 4'd1;
                start_cnt <= 1'b1;
                res_valid <= 1'b0;
            end else if (start_cnt) begin
                if (cnt < 8) begin
                    SR <= next_SR;
                    cnt <= cnt + 1;
                end else begin
                    start_cnt <= 1'b0;
                    cnt <= 4'd0;
                    remainder <= SR[15:8];
                    quotient <= SR[7:0];

                    if (sign) begin
                        quotient <= (dividend_sign ^ divisor_sign) ? -quotient : quotient;
                        remainder <= dividend_sign ? -remainder : remainder;
                    end
                    result <= {remainder, quotient};
                    res_valid <= 1'b1;
                end
            end else if (res_valid) begin
                res_valid <= 1'b0;
            end
        end
    end

endmodule

