module div_16bit (
    input [15:0] A,
    input [7:0] B,
    output reg [15:0] result,
    output reg [15:0] odd
);

reg [15:0] a_reg;
reg [7:0] b_reg;

always @* begin
    a_reg = A;
    b_reg = B;
end

always @* begin
    integer i;
    reg [15:0] dividend;
    reg [15:0] remainder;
    reg [15:0] quotient;

    dividend = a_reg;
    remainder = 16'd0;
    quotient = 16'd0;

    for (i = 15;
 i >= 0;
 i = i - 1) begin
        remainder = {remainder[14:0], dividend[i]};
        if (remainder[15:8] >= b_reg) begin
            quotient[i] = 1'b1;
            remainder = {8'd0, remainder[15:8]} - {8'd0, b_reg};
        end else begin
            quotient[i] = 1'b0;
        end
    end

    result = quotient;
    odd = remainder;
end

endmodule

