module fixed_point_adder #(
    parameter Q = 4,
    parameter N = 8
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c
);

    reg [N-1:0] res;
    wire [N-1:0] a_abs = a[N-1] ? (-a) : a;
    wire [N-1:0] b_abs = b[N-1] ? (-b) : b;
    wire a_sign = a[N-1];
    wire b_sign = b[N-1];

    always @(*) begin
        if (a_sign == b_sign) begin

            res = a_abs + b_abs;
            res = {a_sign, res[N-1:1]};
        end else begin

            if (a_abs > b_abs) begin
                res = a_abs - b_abs;
            end else if (b_abs > a_abs) begin
                res = b_abs - a_abs;
            end else begin
                res = 0;
            end
            res = {1'b0, res[N-1:1]};

        end
    end

    assign c = res;

endmodule

