module fixed_point_subtractor #(
    parameter Q = 8,
    parameter N = 16
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);

reg [N-1:0] res;
wire sign_a = a[N-1];
wire sign_b = b[N-1];
wire same_sign = (sign_a == sign_b);


wire [N-1:0] abs_a = sign_a ? (-a) : a;
wire [N-1:0] abs_b = sign_b ? (-b) : b;

always @* begin
    if (same_sign) begin
        res = a - b;

        res[N-1] = sign_a;
    end else begin

        res = abs_a + abs_b;

        res[N-1] = (abs_a >= abs_b) ? sign_a : ~sign_a;
    end


    if (res == 0) begin
        res = {1'b0, {N-1{1'b0}}};
    end
end

assign c = res;

endmodule

