reg a_sign, b_sign, z_sign;
reg [8:0] a_exponent, b_exponent, z_exponent;
reg [23:0] a_mantissa, b_mantissa, z_mantissa;
reg [49:0] product;
reg guard_bit, round_bit, sticky;


wire a_is_nan = (a[30:23] == 8'hff) && (a[22:0] != 0);
wire b_is_nan = (b[30:23] == 8'hff) && (b[22:0] != 0);
wire result_nan = a_is_nan || b_is_nan;

wire a_is_inf = (a[30:23] == 8'hff) && (a[22:0] == 0);
wire b_is_inf = (b[30:23] == 8'hff) && (b[22:0] == 0);
wire result_inf = (a_is_inf || b_is_inf) && !(a_is_nan || b_is_nan || a_is_zero || b_is_zero);

wire a_is_zero = (a[30:23] == 0) && (a[22:0] == 0);
wire b_is_zero = (b[30:23] == 0) && (b[22:0] == 0);
wire result_zero = (a_is_zero || b_is_zero) && !(a_is_nan || b_is_nan || a_is_inf || b_is_inf);

always @(posedge clk) begin
    if (rst) begin
        counter <= 0;
        z <= 0;
        {a_sign, b_sign, z_sign} <= 0;
        {a_exponent, b_exponent, z_exponent} <= 0;
        {a_mantissa, b_mantissa, z_mantissa} <= 0;
        product <= 0;
        {guard_bit, round_bit, sticky} <= 0;
    end else begin
        case (counter)

            0: begin
                a_sign <= a[31];
                b_sign <= b[31];
                a_exponent <= {1'b0, a[30:23]};
                b_exponent <= {1'b0, b[30:23]};
                a_mantissa <= (a[30:23] != 0) ? {1'b1, a[22:0]} : {1'b0, a[22:0]};
                b_mantissa <= (b[30:23] != 0) ? {1'b1, b[22:0]} : {1'b0, b[22:0]};
                z <= result_nan ? {1'b0, 8'hff, 23'h1} :
                     result_inf ? {a_sign ^ b_sign, 8'hff, 23'd0} :
                     result_zero ? {a_sign ^ b_sign, 31'd0} : z;
                counter <= 1;
            end

            1: begin
                product <= a_mantissa * b_mantissa;
                counter <= 2;
            end

            2: begin
                if (product[47]) begin
                    z_mantissa <= product[46:23];
                    z_exponent <= a_exponent + b_exponent - 9'd127 + 1;
                end else begin
                    z_mantissa <= product[47:24];
                    z_exponent <= a_exponent + b_exponent - 9'd127;
                end

                guard_bit <= product[22];
                round_bit <= product[21];
                sticky <= |product[20:0];
                counter <= 3;
            end

            3: begin
                if (guard_bit || round_bit || sticky) begin
                    if (z_mantissa[0]) begin
                        z_mantissa <= z_mantissa + 1;
                        if (z_mantissa == 24'hffffff) begin
                            z_mantissa <= 24'd0;
                            z_exponent <= z_exponent + 1;
                        end
                    end else begin
                        z_mantissa <= z_mantissa + 1;
                    end
                end

                if (z_exponent > 9'd254)
                    z <= {a_sign ^ b_sign, 8'hff, 23'd0};
                else if (z_exponent[8] || z_mantissa[23])
                    z <= {a_sign ^ b_sign, 31'd0};
                else
                    z <= {a_sign ^ b_sign, z_exponent[7:0], z_mantissa[22:0]};
                counter <= 0;
            end
            default: counter <= 0;
        endcase
    end
end

endmodule

