    if (Rst) begin 
        SP <= 3'd4;

        stack_mem[0] <= 4'b0;
        stack_mem[1] <= 4'b0;
        stack_mem[2] <= 4'b0;
        stack_mem[3] <= 4'b0;
    end
    else if (EN) begin 
        if (RW) begin 
            if (!FULL) begin
                dataOut <= stack_mem[SP];

                stack_mem[SP] <= 4'b0;

                SP <= SP + 3'd1;

            end
        end
        else begin 
            if (!EMPTY) begin
                stack_mem[SP - 3'd1] <= dataIn;

                SP <= SP - 3'd1;

            end
        end
    end
end

