module alu (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output reg [31:0] r,
    output zero,
    output reg carry,
    output reg negative,
    output reg overflow,
    output flag
);

localparam ADD  = 6'b100000;
localparam ADDU = 6'b100001;
localparam SUB  = 6'b100010;
localparam SUBU = 6'b100011;
localparam AND  = 6'b100100;
localparam OR   = 6'b100101;
localparam XOR  = 6'b100110;
localparam NOR  = 6'b100111;
localparam SLT  = 6'b101010;
localparam SLTU = 6'b101011;
localparam SLL  = 6'b000000;
localparam SRL  = 6'b000010;
localparam SRA  = 6'b000011;
localparam SLLV = 6'b000100;
localparam SRLV = 6'b000110;
localparam SRAV = 6'b000111;
localparam LUI  = 6'b001111;

reg [32:0] res;

always @(*) begin
    case (aluc)
        ADD: begin
            res = {a[31], a} + {b[31], b};
            {carry, overflow} = {(res[32]), (a[31] == b[31]) && (res[31] != a[31])};
        end
        ADDU: begin
            res = {1'b0, a} + {1'b0, b};
            {carry, overflow} = {(res[32]), 1'b0};
        end
        SUB: begin
            res = {a[31], a} - {b[31], b};
            {carry, overflow} = {(res[32]), (a[31] != b[31]) && (res[31] != a[31])};
        end
        SUBU: begin
            res = {1'b0, a} - {1'b0, b};
            {carry, overflow} = {(res[32]), 1'b0};
        end
        AND:  res = {1'b0, a & b};
        OR:   res = {1'b0, a | b};
        XOR:  res = {1'b0, a ^ b};
        NOR:  res = {1'b0, ~ (a | b)};
        SLT:  res = ($signed(a) < $signed(b)) ? 33'd1 : 33'd0;
        SLTU: res = (a < b) ? 33'd1 : 33'd0;
        SLL:  res = b << a[4:0];
        SRL:  res = b >> a[4:0];
        SRA:  res = $signed(b) >>> a[4:0];
        SLLV: res = a << b[4:0];
        SRLV: res = a >> b[4:0];
        SRAV: res = $signed(a) >>> b[4:0];
        LUI:  res = {a[31:16], 16'b0};
        default: res = 33'bz;
    endcase
end

assign r = res[31:0];
assign zero = (r == 32'b0);
assign negative = r[31];
assign flag = (aluc == SLT || aluc == SLTU) ? 1'b1 : 1'bz;

endmodule

