module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

    reg [16:0] SR;

    reg [3:0] cnt;
    reg start_cnt;
    reg in_progress;
    reg [7:0] quotient;
    reg [7:0] remainder;
    reg sign_dividend;
    reg sign_divisor;
    reg [8:0] NEG_DIVISOR;


    always @(posedge clk) begin
        if (rst) begin
            SR <= 17'b0;
            cnt <= 4'b0;
            start_cnt <= 1'b0;
            in_progress <= 1'b0;
            res_valid <= 1'b0;
            quotient <= 8'b0;
            remainder <= 8'b0;
            sign_dividend <= 1'b0;
            sign_divisor <= 1'b0;
            NEG_DIVISOR <= 9'b0;
        end else begin
            if (opn_valid && !res_valid) begin

                sign_dividend <= sign ? dividend[7] : 1'b0;
                sign_divisor <= sign ? divisor[7] : 1'b0;


                if (sign) begin
                    remainder <= dividend[7] ? (~dividend + 1) : dividend;
                    quotient <= divisor[7] ? (~divisor + 1) : divisor;
                    NEG_DIVISOR <= ~{(divisor[7], divisor)} + 1;

                end else begin
                    remainder <= dividend;
                    quotient <= divisor;
                    NEG_DIVISOR <= ~{1'b0, divisor} + 1;
                end


                SR <= {8'b0, remainder} << 1;
                cnt <= 4'd1;
                start_cnt <= 1'b1;
                in_progress <= 1'b1;
                res_valid <= 1'b0;
            end else if (in_progress) begin
                if (start_cnt) begin

                    wire [8:0] sub_result = SR[16:8] - NEG_DIVISOR;
                    wire carry_out = ~sub_result[8];



                    if (carry_out) begin
                        SR <= {sub_result, SR[7:1], 1'b1};
                    end else begin
                        SR <= {SR[16:8], SR[7:1], 1'b0};
                    end

                    cnt <= cnt + 4'd1;
                    start_cnt <= 1'b0;

                    if (cnt == 4'd8) begin

                        quotient <= SR[8:1];
                        remainder <= SR[16:9];
                        in_progress <= 1'b0;
                        res_valid <= 1'b1;
                    end
                end
            end


            if (res_valid) begin
                if (sign) begin
                    quotient <= (sign_dividend ^ sign_divisor) ? -quotient : quotient;
                    remainder <= sign_dividend ? -remainder : remainder;
                end
                result <= {remainder, quotient};
            end
        end
    end

endmodule

