module div_16bit (
    input [15:0] A,
    input [7:0] B,
    output reg [15:0] result,
    output reg [15:0] odd
);

reg [15:0] a_reg;
reg [7:0] b_reg;

always @(*) begin
    a_reg = A;
    b_reg = B;
end

always @(*) begin
    reg [15:0] quotient = 16'b0;
    reg [8:0] remainder = a_reg[15:8];


    for (integer i = 15;
 i >= 0;
 i = i - 1) begin
        reg [8:0] combined = {remainder, a_reg[i]};

        if (combined >= {1'b0, b_reg}) begin
            quotient[i] = 1'b1;
            remainder = combined - {1'b0, b_reg};
        end else begin
            quotient[i] = 1'b0;
            remainder = combined;
        end
    end

    result = quotient;
    odd = {remainder[7:0], 8'b0};

end

endmodule

