    input rst_n,
    input start,
    input [15:0] ain,
    input [15:0] bin,
    output reg [31:0] yout,
    output reg done
);

reg [15:0] areg;
reg [15:0] breg;
reg [4:0] i;
reg [31:0] yout_r;
reg done_r;


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        i <= 5'b0;
    end else begin
        if (start) begin
            if (i < 17) begin
                i <= i + 1;
            end
        end else begin
            i <= 5'b0;
        end
    end
end


