module fixed_point_adder #(
    parameter Q = 4,
    parameter N = 8
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);

reg [N-1:0] res;

always @(*) begin
    if (a[N-1] == b[N-1]) begin
        res = a + b;
    end else begin
        wire [N-1:0] a_abs = a[N-1] ? (~a + 1) : a;
        wire [N-1:0] b_abs = b[N-1] ? (~b + 1) : b;

        if (a_abs > b_abs) begin
            res = a_abs - b_abs;
            res[N-1] = a[N-1];
        end else if (b_abs > a_abs) begin
            res = b_abs - a_abs;
            res[N-1] = b[N-1];
        end else begin
            res = 0;
            res[N-1] = 0;
        end
    end
end

assign c = res;

endmodule

