module fixed_point_subtractor #(
    parameter Q = 2,
    parameter N = 4
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c
);

    reg [N-1:0] res;

    wire sign_a = a[N-1];
    wire sign_b = b[N-1];
    wire same_sign = (sign_a == sign_b);

    wire [N-1:0] magnitude_a = sign_a ? (~a + 1) : a;
    wire [N-1:0] magnitude_b = sign_b ? (~b + 1) : b;

    wire [N:0] sum_mag_full = magnitude_a + magnitude_b;
    wire [N-1:0] sum_mag = sum_mag_full[N-1:0];
    wire magnitude_a_gt = magnitude_a > magnitude_b;

    wire result_sign = (same_sign) ? sign_a : (magnitude_a_gt ? 1'b0 : 1'b1);

    always @(*) begin
        if (same_sign) begin
            res = a - b;
            if (res == 0)
                res[N-1] = 1'b0;
        end else begin
            res = {result_sign, sum_mag[N-2:0]};
        end
    end

    assign c = res;

endmodule

