module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);

parameter idle = 2'd0;
parameter s1_red = 2'd1;
parameter s3_green = 2'd2;
parameter s2_yellow = 2'd3;

reg [1:0] state;
reg [7:0] cnt;
reg p_red, p_yellow, p_green;

assign clock = cnt;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= idle;
    end else begin
        case (state)
            idle: state <= s1_red;
            s1_red: if (cnt == 0) state <= s3_green;
            s3_green: if (cnt == 0) state <= s2_yellow;
            s2_yellow: if (cnt == 0) state <= s1_red;
            default: state <= idle;
        endcase
    end
end

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        cnt <= 10;

    end else begin
        if (pass_request && green) begin
            cnt <= 10;
        end else if (!green && p_green) begin
            cnt <= 60;

        end else if (!yellow && p_yellow) begin
            cnt <= 5;

        end else if (!red && p_red) begin
            cnt <= 10;

        end else begin
            cnt <= cnt - 1;
        end
    end
end

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        p_red <= 0;
        p_yellow <= 0;
        p_green <= 0;
    end else begin
        p_red <= red;
        p_yellow <= yellow;
        p_green <= green;
    end
end

always @(*) begin
    red = p_red;
    yellow = p_yellow;
    green = p_green;
end

endmodule

