module alu (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output reg [31:0] r,
    output zero,
    output carry,
    output negative,
    output overflow,
    output flag
);

    parameter ADD  = 6'b100000;
    parameter ADDU = 6'b100001;
    parameter SUB  = 6'b100010;
    parameter SUBU = 6'b100011;
    parameter AND  = 6'b100100;
    parameter OR   = 6'b100101;
    parameter XOR  = 6'b100110;
    parameter NOR  = 6'b100111;
    parameter SLT  = 6'b101010;
    parameter SLTU = 6'b101011;
    parameter SLL  = 6'b000000;
    parameter SRL  = 6'b000010;
    parameter SRA  = 6'b000011;
    parameter SLLV = 6'b000100;
    parameter SRLV = 6'b000110;
    parameter SRAV = 6'b000111;
    parameter LUI  = 6'b001111;

    assign zero = (r == 32'b0);
    assign negative = r[31];

    wire signed_less_than = $signed(a) < $signed(b);
    wire unsigned_less_than = a < b;

    assign flag = (aluc == SLT) ? signed_less_than :
                  (aluc == SLTU) ? unsigned_less_than :
                  1'bz;

    wire [32:0] sum_add = {1'b0, a} + {1'b0, b};
    wire [32:0] sum_addu = {1'b0, a} + {1'b0, b};
    wire [32:0] diff_sub = {1'b0, a} - {1'b0, b};
    wire [32:0] diff_subu = {1'b0, a} - {1'b0, b};

    assign carry = (aluc == ADD) ? sum_add[32] :
                   (aluc == ADDU) ? sum_addu[32] :
                   (aluc == SUB) ? ~diff_sub[32] :
                   (aluc == SUBU) ? ~diff_subu[32] :
                   1'b0;

    wire signed_overflow_add = (a[31] == b[31]) && (r[31] != a[31]);
    wire signed_overflow_sub = (a[31] != b[31]) && (r[31] != a[31]);

    assign overflow = (aluc == ADD) ? signed_overflow_add :
                      (aluc == SUB) ? signed_overflow_sub :
                      1'b0;

    always @(*) begin
        case (aluc)
            ADD:  r = a + b;
            ADDU: r = a + b;
            SUB:  r = a - b;
            SUBU: r = a - b;
            AND:  r = a & b;
            OR:   r = a | b;
            XOR:  r = a ^ b;
            NOR:  r = ~(a | b);
            SLT:  r = signed_less_than ? 32'd1 : 32'd0;
            SLTU: r = unsigned_less_than ? 32'd1 : 32'd0;
            SLL:  r = b << a[4:0];
            SRL:  r = b >> a[4:0];
            SRA:  r = $signed(b) >>> a[4:0];
            SLLV: r = b << a[4:0];
            SRLV: r = b >> a[4:0];
            SRAV: r = $signed(b) >>> a[4:0];
            LUI:  r = {a[15:0], 16'b0};
            default: r = 32'bz;
        endcase
    end

endmodule

