module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

    reg [7:0] absolute_dividend;
    reg [7:0] absolute_divisor;
    reg [7:0] NEG_DIVISOR;
    reg [15:0] SR;

    reg [3:0] cnt;
    reg start_cnt;

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            SR <= 16'b0;
            cnt <= 0;
            start_cnt <= 0;
            absolute_dividend <= 0;
            absolute_divisor <= 0;
            NEG_DIVISOR <= 0;
        end else begin
            if (opn_valid && !res_valid) begin

                if (sign) begin
                    absolute_dividend <= dividend[7] ? -dividend : dividend;
                    absolute_divisor <= divisor[7] ? -divisor : divisor;
                end else begin
                    absolute_dividend <= dividend;
                    absolute_divisor <= divisor;
                end
                NEG_DIVISOR <= -(absolute_divisor);

                SR <= {8'b0, absolute_dividend} << 1;
                cnt <= 1;
                start_cnt <= 1;
                res_valid <= 0;
            end else if (start_cnt) begin
                if (cnt == 8) begin
                    res_valid <= 1;
                    start_cnt <= 0;
                    cnt <= 0;
                end else begin

                    reg [8:0] remainder_sub = {1'b0, SR[15:8]} - NEG_DIVISOR;
                    reg carry_out = remainder_sub[8] ? 1'b1 : 1'b0;
                    reg new_remainder = remainder_sub[7:0];
                    reg [15:0] next_SR = {new_remainder, SR[7:1], carry_out};
                    SR <= next_SR;
                    cnt <= cnt + 1;
                end
            end
        end


        if (res_valid) res_valid <= 0;
    end


    always @(*) begin
        if (res_valid)
            result = {SR[15:8], SR[7:0]};
    end

endmodule

