    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            sum[0] <= 8'b0;
            carry[0] <= 1'b0;
            en_stage[0] <= 1'b0;
        end else begin
            sum[0] <= sum_temp0[7:0];
            carry[0] <= sum_temp0[8];
            en_stage[0] <= i_en;
