module fixed_point_adder #(
    parameter Q = 4,
    parameter N = 8
)(
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);

wire [N-1:0] a_abs = a[N-1] ? (~a + 1) : a;
wire [N-1:0] b_abs = b[N-1] ? (~b + 1) : b;

wire sign_a = a[N-1];
wire sign_b = b[N-1];

wire a_gt_b = (a_abs > b_abs);
wire b_gt_a = (b_abs > a_abs);
wire equal = (a_abs == b_abs);

always @(*) begin
    if (sign_a == sign_b) begin

        c = {sign_a, a_abs + b_abs};
    end else begin

        if (a_gt_b) begin
            c = {1'b0, a_abs - b_abs};
        end else if (b_gt_a) begin
            c = {1'b1, b_abs - a_abs};
        end else begin
            c = {1'b0, 0};
        end
    end
end

endmodule

