module fixed_point_subtractor #(
    parameter Q = 8,
    parameter N = 16
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);

    reg [N-1:0] res;
    wire sign_a = a[N-1];
    wire sign_b = b[N-1];
    wire [N-2:0] a_mag = a[N-2:0];
    wire [N-2:0] b_mag = b[N-2:0];

    always @(*) begin
        if (sign_a == sign_b) begin
            res = a - b;
        end else begin
            if (sign_a == 1'b0 && sign_b == 1'b1) begin

                wire [N-2:0] sum_mag = a_mag + b_mag;
                res = {~(a_mag > b_mag), sum_mag};
            end else begin

                wire [N-2:0] sum_mag = a_mag + b_mag;
                res = {~(a_mag > b_mag), sum_mag};
            end
        end

        if (res == 0) begin
            res[N-1] = 1'b0;
        end
    end

    assign c = res;

endmodule

