module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

reg [2:0] counter;
reg [7:0] a_exponent, b_exponent;
reg [22:0] a_mantissa, b_mantissa;
reg a_sign, b_sign;
reg [49:0] product;
reg guard, round, sticky;
reg [23:0] normalized_mantissa;
reg [9:0] z_exponent;
reg z_sign;

always @(posedge clk) begin
    if (rst) begin
        counter <= 3'b0;
        a_sign <= 0;
        b_sign <= 0;
        a_exponent <= 0;
        b_exponent <= 0;
        a_mantissa <= 0;
        b_mantissa <= 0;
        product <= 0;
        guard <= 0;
        round <= 0;
        sticky <= 0;
        normalized_mantissa <= 0;
        z_exponent <= 0;
        z_sign <= 0;
        z <= 0;
    end else begin
        case (counter)
            3'b000: begin

                a_sign <= a[31];
                b_sign <= b[31];
                a_exponent <= a[30:23];
                b_exponent <= b[30:23];
                a_mantissa <= a[22:0];
                b_mantissa <= b[22:0];
                counter <= counter + 1;
            end
            3'b001: begin

                if (a_exponent == 8'hff || b_exponent == 8'hff) begin
                    if (a_exponent == 8'hff && b_exponent == 8'hff) begin

                        z <= {a_sign ^ b_sign, 8'hff, 23'b0};
                    end else if (a_exponent == 8'hff) begin

                        z <= {a_sign, 8'hff, 23'b0};
                    end else if (b_exponent == 8'hff) begin

                        z <= {b_sign, 8'hff, 23'b0};
                    end else begin

                    end
                end else if (a_mantissa == 0 && b_mantissa == 0) begin

                    z <= {a_sign ^ b_sign, 31'b0};
                end else begin
                    product <= {1'b1, a_mantissa} * {1'b1, b_mantissa};
                    counter <= counter + 1;
                end
            end
            3'b010: begin

                if (product[47]) begin
                    normalized_mantissa <= product[46:23];
                    z_exponent <= a_exponent + b_exponent - 9'd127 + 10'd1;
                end else begin
                    normalized_mantissa <= product[47:24];
                    z_exponent <= a_exponent + b_exponent - 9'd127;
                end
                guard <= product[22];
                round <= product[21];
                sticky <= |product[20:0];
                counter <= counter + 1;
            end
            3'b011: begin

                reg increment;
                increment = guard & (round | sticky) | (guard & ~round & ~sticky & normalized_mantissa[23]);
                if (increment) begin
                    normalized_mantissa <= normalized_mantissa + 1;
                    if (normalized_mantissa[23:0] == 24'h1000000) begin
                        normalized_mantissa <= 24'b100000000000000000000000;
                        z_exponent <= z_exponent + 1;
                    end
                end
                counter <= counter + 1;
            end
            3'b100: begin

                if (z_exponent > 10'hfe) begin
                    z <= {z_sign, 8'hff, 23'b0};
                end else if (z_exponent == 0) begin
                    z <= {z_sign, 31'b0};
                end else begin
                    z <= {z_sign, z_exponent[7:0], normalized_mantissa[22:0]};
                end
                counter <= 3'b0;
            end
            default: counter <= 3'b0;
        endcase
    end
end

endmodule

