module asyn_fifo #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wire wclk,
    input wire wrstn,
    input wire winc,
    input wire [WIDTH-1:0] wdata,
    input wire rclk,
    input wire rrstn,
    input wire rinc,
    output wire wfull,
    output wire rempty,
    output wire [WIDTH-1:0] rdata
);

    reg [3:0] waddr_bin, raddr_bin;
    wire [3:0] wgray = (waddr_bin >> 1) ^ waddr_bin;
    wire [3:0] rgray = (raddr_bin >> 1) ^ raddr_bin;

    reg [3:0] rptr_sync1, rptr_sync2;
    reg [3:0] wptr_sync1, wptr_sync2;

    assign rempty = (rgray == wptr_sync2);
    wire [3:0] wptr_full_gray = {~rgray[3], ~rgray[2], rgray[1:0]};
    assign wfull = (wgray == wptr_full_gray) && !rempty;

    wire wen = winc && !wfull;
    wire ren = rinc && !rempty;

    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) waddr_bin <= 4'b0;
        else if (wen) waddr_bin <= waddr_bin + 1;
    end

    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) raddr_bin <= 4'b0;
        else if (ren) raddr_bin <= raddr_bin + 1;
    end

    always @(posedge rclk) begin
        rptr_sync1 <= rgray;
        rptr_sync2 <= rptr_sync1;
    end

    always @(posedge wclk) begin
        wptr_sync1 <= wgray;
        wptr_sync2 <= wptr_sync1;
    end

    dual_port_RAM #(
        .DEPTH = DEPTH,
        .WIDTH = WIDTH
    ) ram_inst (
        .wclk(wclk),
        .wenc(wen),
        .waddr(waddr_bin[$clog2(DEPTH)-1:0]),
        .wdata(wdata),
        .rclk(rclk),
        .renc(ren),
        .raddr(raddr_bin[$clog2(DEPTH)-1:0]),
        .rdata(rdata)
    );

