module alu (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output reg [31:0] r,
    output zero,
    output carry,
    output negative,
    output overflow,
    output flag
);

parameter ADD  = 6'b100000;
parameter ADDU = 6'b100001;
parameter SUB  = 6'b100010;
parameter SUBU = 6'b100011;
parameter AND  = 6'b100100;
parameter OR   = 6'b100101;
parameter XOR  = 6'b100110;
parameter NOR  = 6'b100111;
parameter SLT  = 6'b101010;
parameter SLTU = 6'b101011;
parameter SLL  = 6'b000000;
parameter SRL  = 6'b000010;
parameter SRA  = 6'b000011;
parameter SLLV = 6'b000100;
parameter SRLV = 6'b000110;
parameter SRAV = 6'b000111;
parameter LUI  = 6'b001111;

reg [31:0] res;
wire signed [31:0] a_signed = a;
wire signed [31:0] b_signed = b;

assign zero = (res == 32'b0);
assign negative = res[31];

wire [32:0] add_sum = {1'b0, a} + {1'b0, b};
wire [32:0] sub_diff = {1'b0, a} - {1'b0, b};
wire add_overflow = (a[31] == b[31]) && (add_sum[31] != a[31]);
wire sub_overflow = (a[31] != b[31]) && (sub_diff[31] != a[31]);

assign carry = (aluc == ADD || aluc == ADDU || aluc == SUB || aluc == SUBU) ? 
               (aluc == ADD || aluc == SUB) ? add_sum[32] : 
               (aluc == ADDU || aluc == SUBU) ? (a + b) >> 31 : 1'b0 : 1'b0;
assign overflow = (aluc == ADD) ? add_overflow : 
                  (aluc == SUB) ? sub_overflow : 1'b0;

always @(*) begin
    case (aluc)
        ADD:  res = add_sum[31:0];
        ADDU: res = a + b;
        SUB:  res = sub_diff[31:0];
        SUBU: res = a - b;
        AND:  res = a & b;
        OR:   res = a | b;
        XOR:  res = a ^ b;
        NOR:  res = ~(a | b);
        SLT:  res = (a_signed < b_signed) ? 32'b1 : 32'b0;
        SLTU: res = (a < b) ? 32'b1 : 32'b0;
        SLL:  res = b << a[4:0];
        SRL:  res = b >> a[4:0];
        SRA:  res = $signed(b) >>> a[4:0];
        SLLV: res = a << b[4:0];
        SRLV: res = a >> b[4:0];
        SRAV: res = $signed(a) >>> b[4:0];
        LUI:  res = {a[15:0], 16'b0};
        default: res = 32'bz;
    endcase
end

reg flag_reg;
always @(*) begin
    if (aluc == SLT) flag_reg = (a_signed < b_signed);
    else if (aluc == SLTU) flag_reg = (a < b);
    else flag_reg = 1'bz;
end

assign flag = flag_reg;
assign r = res;

endmodule

