module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

reg [7:0] abs_dividend, abs_divisor;
reg [7:0] NEG_DIVISOR;
reg [15:0] SR;
reg [3:0] cnt;
reg start_cnt;

always @(posedge clk) begin
    if (rst) begin
        res_valid <= 0;
        start_cnt <= 0;
        cnt <= 0;
        SR <= 0;
        abs_dividend <= 0;
        abs_divisor <= 0;
        NEG_DIVISOR <= 0;
        result <= 0;
    end else begin
        if (opn_valid && !res_valid) begin

            abs_dividend <= sign ? (dividend[7] ? (~dividend + 1) : dividend) : dividend;
            abs_divisor <= sign ? (divisor[7] ? (~divisor + 1) : divisor) : divisor;
            NEG_DIVISOR <= ~abs_divisor + 1;



            SR <= {7'b0, abs_dividend, 1'b0} << 1;

            cnt <= 4'd1;
            start_cnt <= 1;
            res_valid <= 0;
        end else if (start_cnt) begin
            if (cnt == 4'd8) begin

                result <= {SR[15:8], SR[7:0]};
                res_valid <= 1;
                start_cnt <= 0;
                cnt <= 0;
            end else begin

                wire [8:0] remainder = SR[15:8];

                wire [8:0] sub_result = remainder - {1'b0, NEG_DIVISOR};
                wire carry_out = ~sub_result[8];


                reg [8:0] new_remainder = remainder;
                if (carry_out) begin
                    new_remainder = sub_result;
                end


                SR <= {new_remainder[7:0], SR[7:1], carry_out};
                cnt <= cnt + 1;
            end
        end else begin
            res_valid <= 0;
        end
    end
end

endmodule

