module accu (
    input clk,
    input rst_n,
    input [7:0] data_in,
    input valid_in,
    output valid_out,
    output [9:0] data_out
);

reg [1:0] cnt;
reg [9:0] sum_reg;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        cnt <= 2'b0;
        sum_reg <= 10'b0;
    end else if (valid_in) begin
        cnt <= cnt + 1;
        if (cnt == 2'b11) begin
            sum_reg <= 10'b0;
        end else begin
            sum_reg <= sum_reg + data_in;
        end
    end
end

assign valid_out = (cnt == 2'b11) && valid_in;
assign data_out = (valid_out) ? (sum_reg + data_in) : 10'b0;

endmodule

