module fixed_point_adder #(
    parameter Q = 8,   
    parameter N = 16    
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c
);

reg [N-1:0] res;

wire sign_a = a[N-1];
wire sign_b = b[N-1];
wire same_sign = (sign_a == sign_b);


wire [N-2:0] a_abs_same = sign_a ? (~a[N-2:0] + 1) : a[N-2:0];
wire [N-2:0] b_abs_same = sign_b ? (~b[N-2:0] + 1) : b[N-2:0];
wire [N-1:0] sum_same = {1'b0, a_abs_same} + {1'b0, b_abs_same};


wire [N-2:0] a_abs_diff = sign_a ? (~a[N-2:0] + 1) : a[N-2:0];
wire [N-2:0] b_abs_diff = sign_b ? (~b[N-2:0] + 1) : b[N-2:0];

wire a_abs_gt_b_abs = (a_abs_diff > b_abs_diff);
wire b_abs_gt_a_abs = (b_abs_diff > a_abs_diff);

wire [N-2:0] result_abs_diff = a_abs_gt_b_abs ? (a_abs_diff - b_abs_diff) :
                               b_abs_gt_a_abs ? (b_abs_diff - a_abs_diff) :
                               0;

wire result_sign_diff = a_abs_gt_b_abs ? sign_a :
                        b_abs_gt_a_abs ? sign_b :
                        1'b0;

always @(*) begin
    if (same_sign) begin
        res = {sign_a, sum_same[N-2:0]};
    end else begin
        res = {result_sign_diff, result_abs_diff};
    end
end

assign c = res;

endmodule

