module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

    reg [2:0] counter;
    reg a_sign, b_sign, z_sign;
    reg [7:0] a_exponent, b_exponent, z_exponent;
    reg [23:0] a_mantissa, b_mantissa, z_mantissa;
    reg [48:0] product;

    reg guard_bit, round_bit, sticky;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b0;
            z <= 32'b0;
            a_sign <= 1'b0;
            b_sign <= 1'b0;
            a_exponent <= 8'b0;
            b_exponent <= 8'b0;
            a_mantissa <= 24'b0;
            b_mantissa <= 24'b0;
        end else begin
            case (counter)
                3'b000: begin 
                    a_sign <= a[31];
                    a_exponent <= a[30:23];
                    a_mantissa <= (a[30:23] != 8'b0) ? {1'b1, a[22:0]} : {1'b0, a[22:0]};
                    b_sign <= b[31];
                    b_exponent <= b[30:23];
                    b_mantissa <= (b[30:23] != 8'b0) ? {1'b1, b[22:0]} : {1'b0, b[22:0]};


                    if ((a_exponent == 8'hff && a_mantissa[22:0] != 0) || 
                        (b_exponent == 8'hff && b_mantissa[22:0] != 0)) begin
                        z <= {1'b0, 8'hff, 23'h000001};
                        counter <= 3'b001;
                    end else if ((a_exponent == 8'hff) || (b_exponent == 8'hff)) begin
                        if ((a_exponent == 8'hff && b_exponent == 8'hff) || 
                            (a_exponent != 8'hff && b_exponent == 8'hff) || 
                            (a_exponent == 8'hff && b_exponent != 8'hff)) begin
                            z <= {a_sign ^ b_sign, 8'hff, 23'b0};
                            counter <= 3'b001;
                        end else if (a_exponent == 8'hff || b_exponent == 8'hff) begin
                            z <= {a_sign ^ b_sign, 8'hff, 23'b0};
                            counter <= 3'b001;
                        end
                    end else if ((a_exponent == 0 && a_mantissa == 0) || 
                               (b_exponent == 0 && b_mantissa == 0)) begin
                        z <= {a_sign ^ b_sign, 8'b0, 23'b0};
                        counter <= 3'b001;
                    end else begin
                        product <= a_mantissa * b_mantissa;
                        z_exponent <= a_exponent + b_exponent - 8'd127;

                        counter <= 3'b001;
                    end
                end
                3'b001: begin 
                    if (product == 0) begin 
                        z <= {a_sign ^ b_sign, 8'b0, 23'b0};
                    end else begin

                        reg [48:0] norm_product = product;
                        reg [7:0] leading_zeros;
                        leading_zeros = 49 - $clog2(norm_product);
                        norm_product = norm_product << leading_zeros;
                        z_exponent <= z_exponent + leading_zeros;
                        product <= norm_product;
                        counter <= 3'b010;
                    end
                end
                3'b010: begin 
                    product = product << 1;

                    guard_bit <= product[47];
                    round_bit <= product[46];
                    sticky <= |product[45:0];
                    z_mantissa <= product[46:24];
                    counter <= 3'b011;
                end
                3'b011: begin 
                    if (guard_bit && (round_bit || sticky)) begin
                        if (z_mantissa[0]) begin
                            z_mantissa <= z_mantissa + 1;
                            if (z_mantissa == 24'hffffff) begin
                                z_exponent <= z_exponent + 1;
                            end
                        end else begin
                            z_mantissa <= z_mantissa + 1;
                        end
                    end
                    counter <= 3'b100;
                end
