module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output data_out
);

    reg [1:0] current_state, next_state;

    localparam IDLE = 2'b00;
    localparam S1 = 2'b01;
    localparam S2 = 2'b10;


    always @(posedge clk or negedge rst_n) begin
        if (~rst_n)
            current_state <= IDLE;
        else
            current_state <= next_state;
    end


    always @(*) begin
        case (current_state)
            IDLE: next_state = (data_in == 1'b0) ? S1 : IDLE;
            S1: next_state = (data_in == 1'b1) ? S2 : IDLE;
            S2: next_state = IDLE;
            default: next_state = IDLE;
        endcase
    end


    assign data_out = (current_state == S2) && (data_in == 1'b0);

endmodule

