module alu (
    input  [31:0] a,
    input  [31:0] b,
    input  [5:0]  aluc,
    output [31:0] r,
    output        zero,
    output        carry,
    output        negative,
    output        overflow,
    output        flag
);

    parameter ADD  = 6'b100000;
    parameter ADDU = 6'b100001;
    parameter SUB  = 6'b100010;
    parameter SUBU = 6'b100011;
    parameter AND  = 6'b100100;
    parameter OR   = 6'b100101;
    parameter XOR  = 6'b100110;
    parameter NOR  = 6'b100111;
    parameter SLT  = 6'b101010;
    parameter SLTU = 6'b101011;
    parameter SLL  = 6'b000000;
    parameter SRL  = 6'b000010;
    parameter SRA  = 6'b000011;
    parameter SLLV = 6'b000100;
    parameter SRLV = 6'b000110;
    parameter SRAV = 6'b000111;
    parameter LUI  = 6'b001111;

    reg [32:0] res;
    reg [31:0] r_reg;
    reg        zero_reg, carry_reg, negative_reg, overflow_reg;
    reg        flag_reg;

    always @* begin

        res = 33'd0;
        r_reg = 32'd0;
        zero_reg = 1'b0;
        carry_reg = 1'b0;
        negative_reg = 1'b0;
        overflow_reg = 1'b0;
        flag_reg = 1'bz;

        case (aluc)
            ADD: begin
                res = {1'b0, a} + {1'b0, b};
                r_reg = res[31:0];
                overflow_reg = (a[31] == b[31]) && (res[31] != a[31]);
                carry_reg = res[32];
            end
            ADDU: begin
                res = {1'b0, a} + {1'b0, b};
                r_reg = res[31:0];
                carry_reg = res[32];
            end
            SUB: begin
                res = {1'b0, a} - {1'b0, b};
                r_reg = res[31:0];
                overflow_reg = (a[31] != b[31]) && (res[31] != a[31]);
                carry_reg = res[32];
            end
            SUBU: begin
                res = {1'b0, a} - {1'b0, b};
                r_reg = res[31:0];
                carry_reg = res[32];
            end
            AND: r_reg = a & b;
            OR:  r_reg = a | b;
            XOR: r_reg = a ^ b;
            NOR: r_reg = ~(a | b);
            SLT: r_reg = ($signed(a) < $signed(b)) ? 32'd1 : 32'd0;
            SLTU: r_reg = (a < b) ? 32'd1 : 32'd0;
            SLL: r_reg = a << b[4:0];
            SRL: r_reg = a >> b[4:0];
            SRA: r_reg = $signed(a) >>> b[4:0];
            SLLV: r_reg = a << b[4:0];
            SRLV: r_reg = a >> b[4:0];
            SRAV: r_reg = $signed(a) >>> b[4:0];
            LUI: r_reg = {b[15:0], 16'd0};
            default: r_reg = 32'bz;
        endcase


        zero_reg = (r_reg == 32'd0);
        negative_reg = r_reg[31];


        if (aluc == SLT || aluc == SLTU)
            flag_reg = 1'b1;
        else
            flag_reg = 1'bz;
    end

    assign r = r_reg;
    assign zero = zero_reg;
    assign carry = carry_reg;
    assign negative = negative_reg;
    assign overflow = overflow_reg;
    assign flag = flag_reg;

endmodule

