module div_16bit (
    input [15:0] A,
    input [7:0] B,
    output reg [15:0] result,
    output reg [15:0] odd
);

reg [15:0] a_reg, b_reg;

always @(*) begin
    a_reg = A;
    b_reg = B;
end

always @(*) begin
    reg [15:0] q;
    reg [15:0] r;
    integer i, j;
    reg [7:0] current_remainder;
    reg [7:0] next_remainder;
    reg [7:0] divisor;
    reg [7:0] dividend_lower;
    reg found;

    r = a_reg;
    q = 16'b0;

    for (i = 15;
 i >= 0;
 i = i - 1) begin
        current_remainder = r[15:8];
        dividend_lower = a_reg[7:0];
        divisor = b_reg;


        found = 0;
        next_remainder = 8'b0;
        for (j = 7;
 j >= 0;
 j = j - 1) begin
            if (dividend_lower[j]) begin
                next_remainder = 8'b1 << j;
                found = 1;
                break;
            end
        end

        if (!found) next_remainder = 8'b0;


        if ({current_remainder, next_remainder} >= {8'b0, divisor}) begin
            next_remainder = {current_remainder, next_remainder} - {8'b0, divisor};
            q[i] = 1'b1;
        end else begin
            q[i] = 1'b0;
        end


        r = {next_remainder, dividend_lower & ~next_remainder};
    end

    odd = r;
    result = q;
end

endmodule

