module cla_8bit (
    input [8:1] A,
    input [8:1] B,
    input C_in,
    output [8:1] S,
    output G_block,
    output P_block
);
    wire [8:1] G, P;
    wire [8:1] CG, CP;
    wire [8:1] C_in_bits;


    assign G[1] = A[1] & B[1];
    assign P[1] = A[1] ^ B[1];
    assign CG[1] = G[1];
    assign CP[1] = P[1];

    genvar i;
    generate
        for (i = 2;
 i <= 8;
 i = i + 1) begin : prefix
            assign G[i] = A[i] & B[i];
            assign P[i] = A[i] ^ B[i];
            assign CG[i] = G[i] | (P[i] & CG[i-1]);
            assign CP[i] = P[i] & CP[i-1];
        end
    endgenerate


    assign C_in_bits[1] = C_in;
    genvar j;
    for (j = 2;
 j <= 8;
 j = j + 1) begin : carry_in
        assign C_in_bits[j] = CG[j-1] | (CP[j-1] & C_in);
    end


    generate
        for (j = 1;
 j <= 8;
 j = j + 1) begin : sum
            cla_1bit bit (
                .A(A[j]),
                .B(B[j]),
                .C_in(C_in_bits[j]),
                .S(S[j]),
                .G(),
                .P()
            );
        end
    endgenerate


    assign G_block = CG[8] | (CP[8] & C_in);
    assign P_block = CP[8];
endmodule

