module fixed_point_adder #(parameter Q=4, N=8) (
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);

wire sign_a = a[N-1];
wire sign_b = b[N-1];
wire [N-2:0] mag_a = a[N-2:0];
wire [N-2:0] mag_b = b[N-2:0];
reg [N-1:0] res;

always @* begin
    if (sign_a == sign_b) begin

        res = {sign_a, mag_a + mag_b};
    end else begin

        if (mag_a > mag_b) begin
            res = {sign_a, mag_a - mag_b};
        end else if (mag_b > mag_a) begin
            res = {sign_b, mag_b - mag_a};
        end else begin

            res = 0;
        end
    end
end

assign c = res;

endmodule

