module fixed_point_subtractor #(
    parameter Q = 2,
    parameter N = 8
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);

    reg [N-1:0] res;

    always @* begin
        reg a_sign, b_sign;
        reg [N-1:0] a_abs, b_abs;
        reg [N-1:0] sum, diff;

        a_sign = a[N-1];
        b_sign = b[N-1];

        if (a_sign == b_sign) begin

            res = a - b;
        end else begin

            a_abs = a_sign ? (~a + 1) : a;
            b_abs = b_sign ? (~b + 1) : b;
            sum = a_abs + b_abs;
            diff = a_abs - b_abs;

            if (a_sign == 0 && b_sign == 1) begin

                if (a_abs > b_abs) begin
                    res = sum;
                    res[N-1] = 0;
                end else begin
                    res = -sum;
                    res[N-1] = 1;
                end
            end else if (a_sign == 1 && b_sign == 0) begin

                if (a_abs > b_abs) begin
                    res = -sum;
                    res[N-1] = 1;
                end else begin
                    res = sum;
                    res[N-1] = 0;
                end
            end else begin
                res = 0;
            end
        end


        if (res == 0) begin
            res = 0;
        end
    end

    assign c = res;

endmodule

