module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

reg [2:0] counter;
reg a_sign, b_sign, z_sign;
reg [7:0] a_exponent, b_exponent, z_exponent;
reg [22:0] a_mantissa, b_mantissa;
reg a_is_nan, a_is_inf, a_is_zero;
reg b_is_nan, b_is_inf, b_is_zero;
reg [23:0] a_mantissa_full, b_mantissa_full;
reg [47:0] product;
reg guard, round, sticky;
reg [23:0] z_mantissa;
reg product_overflow;

always @(posedge clk) begin
    if (rst) begin
        counter <= 3'b0;
        z <= 32'b0;
        a_sign <= 0;
        b_sign <= 0;
        a_exponent <= 0;
        b_exponent <= 0;
        a_mantissa <= 0;
        b_mantissa <= 0;
        a_is_nan <= 0;
        a_is_inf <= 0;
        a_is_zero <= 0;
        b_is_nan <= 0;
        b_is_inf <= 0;
        b_is_zero <= 0;
        product_overflow <= 0;
        guard <= 0;
        round <= 0;
        sticky <= 0;
        z_mantissa <= 0;
        z_exponent <= 0;
        z_sign <= 0;
    end else begin
        case (counter)
            3'b000: begin

                a_sign <= a[31];
                b_sign <= b[31];
                a_exponent <= a[30:23];
                b_exponent <= b[30:23];
                a_mantissa <= a[22:0];
                b_mantissa <= b[22:0];


                a_is_nan <= (a[30:23] == 8'hff) && (a[22:0] != 0);
                a_is_inf <= (a[30:23] == 8'hff) && (a[22:0] == 0);
                a_is_zero <= (a[30:23] == 0) && (a[22:0] == 0);

                b_is_nan <= (b[30:23] == 8'hff) && (b[22:0] != 0);
                b_is_inf <= (b[30:23] == 8'hff) && (b[22:0] == 0);
                b_is_zero <= (b[30:23] == 0) && (b[22:0] == 0);

                counter <= 3'b001;
            end

            3'b001: begin

                if (a_is_nan || b_is_nan) begin
                    z <= {a_sign ^ b_sign, 8'hff, 23'h000001};
                    counter <= 3'b0;
                end else if ((a_is_inf || b_is_inf) && (a_is_zero || b_is_zero)) begin
                    z <= {1'b0, 8'hff, 23'h000001};
                    counter <= 3'b0;
                end else if (a_is_inf || b_is_inf) begin
                    z <= {a_sign ^ b_sign, 8'hff, 23'h000001};
                    counter <= 3'b0;
                end else if (a_is_zero || b_is_zero) begin
                    z <= {a_sign ^ b_sign, 8'b0, 23'b0};
                    counter <= 3'b0;
                end else begin
                    counter <= 3'b010;
                end
            end

            3'b010: begin

                a_mantissa_full <= (a_exponent != 0) ? {1'b1, a_mantissa} : {1'b0, a_mantissa};
                b_mantissa_full <= (b_exponent != 0) ? {1'b1, b_mantissa} : {1'b0, b_mantissa};
                product <= a_mantissa_full * b_mantissa_full;
                counter <= 3'b011;
            end

            3'b011: begin

                guard <= product[46];
                round <= product[45];
                sticky <= |product[44:0];

                if (product[47]) begin
                    z_mantissa <= {1'b1, product[46:24]};
                    product_overflow <= 1'b1;
                    z_exponent <= a_exponent + b_exponent - 8'd127 + 1;
                end else begin
                    z_mantissa <= {1'b0, product[47:25]};
                    product_overflow <= 1'b0;
                    z_exponent <= a_exponent + b_exponent - 8'd127;
                end


                if (guard && (round || sticky || (z_mantissa[0]))) begin
                    z_mantissa <= z_mantissa + 1;
                    if (z_mantissa == 24'h1800000) begin 
                        z_exponent <= z_exponent + 1;
                        z_mantissa <= 24'h0000000;
                    end
                end

                counter <= 3'b100;
            end

            3'b100: begin

                z_sign <= a_sign ^ b_sign;

                if (z_exponent >= 255) begin
                    z <= {z_sign, 8'hff, 23'h0};
                end else if (z_exponent <= 0) begin
                    z <= {z_sign, 8'h0, 23'h0};
                end else begin
                    z <= {z_sign, z_exponent[7:0], z_mantissa[22:0]};
                end

                counter <= 3'b0;
            end

            default: counter <= 3'b0;
        endcase
    end
end

endmodule

