module LIFObuffer (
    input Clk,
    input EN,
    input Rst,
    input RW,
    input [3:0] dataIn,
    output reg EMPTY,
    output reg FULL,
    output reg [3:0] dataOut
);

reg [3:0] stack_mem [0:3];
reg [2:0] SP;


always @(posedge Clk) begin
    if (EN) begin
        if (Rst) begin
            SP <= 3'd0;
            stack_mem[0] <= 4'b0;
            stack_mem[1] <= 4'b0;
            stack_mem[2] <= 4'b0;
            stack_mem[3] <= 4'b0;
        end else begin
            if (RW == 1'b0) begin 
                if (!FULL) begin
                    stack_mem[SP] <= dataIn;
                    SP <= SP + 1;
                end
            end else begin 
                if (!EMPTY) begin
                    dataOut <= stack_mem[SP - 1];
                    stack_mem[SP - 1] <= 4'b0;
                    SP <= SP - 1;
                end
            end
        end
    end

    EMPTY <= (SP == 3'd0);
    FULL <= (SP == 3'd4);
end

endmodule

