module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

reg [7:0] saved_dividend, saved_divisor;
reg [7:0] abs_dividend, abs_divisor;
reg [7:0] NEG_DIVISOR;
reg [15:0] SR;
reg [3:0] cnt;
reg start;
reg sign_quotient, sign_remainder;

always @(*) begin
    if (sign) begin
        abs_dividend = dividend[7] ? (-dividend) : dividend;
        abs_divisor = divisor[7] ? (-divisor) : divisor;
        sign_quotient = (saved_dividend[7] ^ saved_divisor[7]) ? 1'b1 : 1'b0;
        sign_remainder = saved_dividend[7] ? 1'b1 : 1'b0;
    end else begin
        abs_dividend = dividend;
        abs_divisor = divisor;
        sign_quotient = 1'b0;
        sign_remainder = 1'b0;
    end
end

always @(posedge clk) begin
    if (rst) begin
        res_valid <= 1'b0;
        cnt <= 4'd0;
        start <= 1'b0;
        SR <= 16'd0;
        saved_dividend <= 8'd0;
        saved_divisor <= 8'd0;
    end else begin
        if (opn_valid && !res_valid) begin
            saved_dividend <= abs_dividend;
            saved_divisor <= abs_divisor;
            NEG_DIVISOR <= ~abs_divisor + 1;
            SR <= {8'b0, abs_dividend << 1};
            start <= 1'b1;
            cnt <= 4'd1;
            res_valid <= 1'b0;
        end else if (start) begin
            if (cnt < 4'd8) begin
                reg [7:0] remainder_shifted = {SR[15:9], SR[8]};
                reg [7:0] quotient_shifted = {SR[7:1], 1'b0};
                reg [7:0] subtract_result = remainder_shifted - abs_divisor;
                if (subtract_result[7] == 1'b0) begin
                    SR <= {subtract_result, quotient_shifted[6:0], 1'b1};
                end else begin
                    SR <= {remainder_shifted, quotient_shifted[6:0], 1'b0};
                end
                cnt <= cnt + 1;
            end else begin
                start <= 1'b0;
                res_valid <= 1'b1;
                result <= { 
                    sign_remainder ? -SR[15:8] : SR[15:8],
                    sign_quotient ? -SR[7:0] : SR[7:0]
                };
            end
        end else if (res_valid && !opn_valid) begin
            res_valid <= 1'b0;
        end
    end
end

endmodule

