            i <= i + 1;
        else
            i <= 5'b0;


        if (i == 5'b0) begin
            areg <= ain;
            breg <= bin;
        end


        if (i >= 1 && i <= 16) begin
            if (areg[i-1])
                yout_r <= yout_r + ({16'b0, breg} << (i-1));
        end


        done_r <= (i == 5'b16);
    end
end

