module fixed_point_adder #(
    parameter Q = 2,
    parameter N = 4
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);

reg [N-1:0] res;

always @* begin
    wire sign_a = a[N-1];
    wire sign_b = b[N-1];
    wire same_sign = (sign_a == sign_b);

    wire [N-1:0] a_abs = sign_a ? (~a + 1) : a;
    wire [N-1:0] b_abs = sign_b ? (~b + 1) : b;

    if (same_sign) begin
        res = a + b;
    end else begin
        if (a_abs > b_abs) begin
            res = a_abs - b_abs;
        end else if (a_abs < b_abs) begin
            res = b_abs - a_abs;
        end else begin
            res = 0;
        end
    end

    if (same_sign) begin
        res[N-1] = sign_a;
    end else begin
        if (a_abs > b_abs) begin
            res[N-1] = 0;
        end else if (a_abs < b_abs) begin
            res[N-1] = 1;
        end else begin
            res[N-1] = 0;
        end
    end

    c = res;
end

endmodule

