module fixed_point_subtractor #(
    parameter Q = 4, 
    parameter N = 8  
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);

reg [N-1:0] res;
reg sign_a, sign_b;
reg [N-2:0] a_mag, b_mag;
reg [N-1:0] sum;
reg [N-2:0] magnitude;
reg res_sign;

always @(*) begin
    sign_a = a[N-1];
    sign_b = b[N-1];

    if (sign_a == sign_b) begin

        sum = a - b;
        if (sum == 0)
            res = 0;
        else
            res = {sign_a, sum[N-2:0]};
    end else begin

        a_mag = a[N-2:0];
        b_mag = b[N-2:0];

        if (sign_a == 1'b0 && sign_b == 1'b1) begin

            if (a_mag >= b_mag) begin
                magnitude = a_mag - b_mag;
                res_sign = 1'b0;
            end else begin
                magnitude = b_mag - a_mag;
                res_sign = 1'b1;
            end
        end else begin

            if (a_mag >= b_mag) begin
                magnitude = a_mag - b_mag;
                res_sign = 1'b1;
            end else begin
                magnitude = b_mag - a_mag;
                res_sign = 1'b0;
            end
        end

        res = {res_sign, magnitude};
    end

    c = res;
end

endmodule

