module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

    reg [2:0] counter;
    reg a_sign, b_sign, z_sign;
    reg [7:0] a_exponent, b_exponent, z_exponent;
    reg [22:0] a_mantissa, b_mantissa;
    reg [22:0] z_mantissa;
    reg [47:0] product;
    reg guard_bit, round_bit, sticky;

    reg is_nan, is_inf_a, is_inf_b, is_zero_a, is_zero_b;
    reg [23:0] a_man, b_man;
    reg [23:0] product_shifted;
    reg [47:0] temp_product;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b0;
            z <= 32'b0;
        end else begin
            counter <= counter + 1;
            case (counter)
                0: begin

                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= a[22:0];
                    b_mantissa <= b[22:0];
                end
                1: begin

                    is_nan <= (a_exponent == 8'hff && a_mantissa != 0) || (b_exponent == 8'hff && b_mantissa != 0);
                    is_inf_a <= (a_exponent == 8'hff && a_mantissa == 0);
                    is_inf_b <= (b_exponent == 8'hff && b_mantissa == 0);
                    is_zero_a <= (a_exponent == 0 && a_mantissa == 0);
                    is_zero_b <= (b_exponent == 0 && b_mantissa == 0);

                    if (is_nan || (is_inf_a && is_zero_b) || (is_inf_b && is_zero_a)) begin
                        z <= {a_sign ^ b_sign, 8'hff, 23'h1};
                    end else if (is_inf_a || is_inf_b) begin
                        z <= {a_sign ^ b_sign, 8'hff, 23'b0};
                    end else if (is_zero_a || is_zero_b) begin
                        z <= {a_sign ^ b_sign, 23'b0, 8'b0};
                    end else begin
                        counter <= counter + 1;

                    end
                end
                2: begin

                    a_man <= (a_exponent != 0) ? {1'b1, a_mantissa} : {1'b0, a_mantissa};
                    b_man <= (b_exponent != 0) ? {1'b1, b_mantissa} : {1'b0, b_mantissa};
                    product <= a_man * b_man;
                end
                3: begin

                    if (product[47]) begin
                        product_shifted <= product >> 1;
                        z_exponent <= a_exponent + b_exponent - 8'd254 + 1;
                    end else begin
                        product_shifted <= product;
                        z_exponent <= a_exponent + b_exponent - 8'd254;
                    end
                end
                4: begin

                    guard_bit <= product_shifted[23];
                    round_bit <= product_shifted[22];
                    sticky <= |product_shifted[21:0];

                    if (guard_bit && (round_bit || sticky)) begin
                        if (product_shifted[23:0] + 1 == 24'h1_000000) begin
                            z_mantissa <= 24'h1_000000;
                            z_exponent <= z_exponent + 1;
                        end else begin
                            z_mantissa <= product_shifted[23:0] + 1;
                        end
                    end else begin
                        z_mantissa <= product_shifted[23:0];
                    end
                end
                5: begin

                    if (z_exponent > 8'hfe) begin
                        z <= {z_sign, 8'hff, 23'b0};
                    end else if (z_exponent == 8'h00) begin
                        z <= {z_sign, 8'b0, 23'b0};
                    end else begin
                        z <= {z_sign, z_exponent, z_mantissa[22:0]};
                    end
                    counter <= 3'b0;

                end
            endcase
        end
    end

endmodule

