module sequence_detector (
    input clk,
    input reset_n,
    input data_in,
    output sequence_detected
);

    parameter IDLE = 3'b000;
    parameter S1 = 3'b001;
    parameter S2 = 3'b010;
    parameter S3 = 3'b011;
    parameter S4 = 3'b100;

    reg [2:0] current_state, next_state;

