module alu (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output [31:0] r,
    output zero,
    output carry,
    output negative,
    output overflow,
    output flag
);

    parameter ADD  = 6'b100000;
    parameter ADDU = 6'b100001;
    parameter SUB  = 6'b100010;
    parameter SUBU = 6'b100011;
    parameter AND  = 6'b100100;
    parameter OR   = 6'b100101;
    parameter XOR  = 6'b100110;
    parameter NOR  = 6'b100111;
    parameter SLT  = 6'b101010;
    parameter SLTU = 6'b101011;
    parameter SLL  = 6'b000000;
    parameter SRL  = 6'b000010;
    parameter SRA  = 6'b000011;
    parameter SLLV = 6'b000100;
    parameter SRLV = 6'b000110;
    parameter SRAV = 6'b000111;
    parameter LUI  = 6'b001111;

    reg [32:0] res;
    reg overflow_reg;

    assign r = res[31:0];
    assign zero = (r == 32'b0);
    assign negative = res[31];
    assign carry = res[32];
    assign overflow = overflow_reg;
    assign flag = (aluc == SLT) ? ($signed(a) < $signed(b)) :
                  (aluc == SLTU) ? (a < b) : 1'bz;

    always @(*) begin
        case (aluc)
            ADD: begin
                res = {1'b0, a} + {1'b0, b};
                overflow_reg = (a[31] == b[31]) && (res[31] != a[31]);
            end
            ADDU: begin
                res = {1'b0, a} + {1'b0, b};
                overflow_reg = 1'b0;
            end
            SUB: begin
                res = {1'b0, a} - {1'b0, b};
                overflow_reg = (a[31] != b[31]) && (res[31] != a[31]);
            end
            SUBU: begin
                res = {1'b0, a} - {1'b0, b};
                overflow_reg = 1'b0;
            end
            AND: res = {1'b0, a & b};
            OR: res = {1'b0, a | b};
            XOR: res = {1'b0, a ^ b};
            NOR: res = {1'b0, ~(a | b)};
            SLT: res = {32'b0, ($signed(a) < $signed(b))};
            SLTU: res = {32'b0, (a < b)};
            SLL: res = {1'b0, a << a[4:0]};
            SRL: res = {1'b0, a >> a[4:0]};
            SRA: res = {1'b0, $signed(a) >>> a[4:0]};
            SLLV: res = {1'b0, a << b[4:0]};
            SRLV: res = {1'b0, a >> b[4:0]};
            SRAV: res = {1'b0, $signed(a) >>> b[4:0]};
            LUI: res = {a[31:16], 16'b0};
            default: res = 33'bz;
        endcase
    end

endmodule

