module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

    reg [7:0] dividend_abs, divisor_abs;
    reg [7:0] NEG_DIVISOR;
    reg [3:0] cnt;
    reg processing;
    reg [15:0] SR;
    reg [7:0] quotient;
    reg [7:0] remainder;
    reg [1:0] res_sign;

    wire [8:0] sum = SR[15:7] + divisor_abs;
    wire carry = sum[8];

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            processing <= 0;
            cnt <= 0;
            SR <= 0;
            quotient <= 0;
            remainder <= 0;
            res_sign <= 0;
            result <= 0;
        end else begin
            if (opn_valid && !res_valid && !processing) begin

                if (sign) begin
                    res_sign[1] <= dividend[7];

                    res_sign[0] <= divisor[7];

                    dividend_abs <= dividend[7] ? -dividend : dividend;
                    divisor_abs <= divisor[7] ? -divisor : divisor;
                end else begin
                    res_sign <= 2'b00;
                    dividend_abs <= dividend;
                    divisor_abs <= divisor;
                end

                NEG_DIVISOR <= -divisor_abs;


                SR <= {dividend_abs, 1'b0} << 7;


                processing <= 1;
                cnt <= 4'd1;
                quotient <= 8'b0;
            end else if (processing) begin
                if (cnt < 8) begin

                    if (carry) begin

                        SR <= {sum, SR[6:0], carry};
                        quotient <= (quotient << 1) | carry;
                    end else begin

                        SR <= {SR[15:1], 1'b0};
                        quotient <= quotient << 1;
                    end
                    cnt <= cnt + 1;
                end else begin

                    processing <= 0;
                    cnt <= 0;
                    remainder <= SR[15:8];



                    if (sign) begin
                        if (res_sign[1] ^ res_sign[0]) begin
                            quotient <= -quotient;
                        end
                        if (res_sign[1]) begin
                            remainder <= -remainder;
                        end
                    end

                    result <= {remainder, quotient};
                    res_valid <= 1;
                end
            end else if (res_valid && opn_valid) begin
                res_valid <= 0;
            end
        end
    end

endmodule

