module accu (
    input clk,
    input rst_n,
    input [7:0] data_in,
    input valid_in,
    output reg valid_out,
    output reg [9:0] data_out
);

reg [1:0] counter;
reg [9:0] acc;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        counter <= 2'd0;
        acc <= 10'd0;
        data_out <= 10'd0;
        valid_out <= 1'b0;
    end else begin
        valid_out <= 1'b0;
        if (valid_in) begin
            acc <= acc + data_in;
            counter <= counter + 1;
            if (counter == 2'd3) begin
                data_out <= acc + data_in;
                valid_out <= 1'b1;
                acc <= 10'd0;
                counter <= 2'd0;
            end
        end
    end
end

endmodule

