module fixed_point_adder #(parameter Q=4, N=8) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c
);

reg [N-1:0] res;
wire same_sign;
wire [N-2:0] a_mag, b_mag;
wire [N-1:0] sum_abs;
wire [N-1:0] diff;
wire a_gt_b, b_gt_a, mag_eq;

assign same_sign = (a[N-1] == b[N-1]);
assign a_mag = a[N-2:0];
assign b_mag = b[N-2:0];


assign sum_abs = {1'b0, a_mag} + {1'b0, b_mag};

assign a_gt_b = (a_mag > b_mag);
assign b_gt_a = (b_mag > a_mag);
assign mag_eq = (a_mag == b_mag);

always @(*) begin
    if (same_sign) begin

        res = {a[N-1], sum_abs[N-1:0]};
    end else begin

        if (a_gt_b) begin
            diff = a_mag - b_mag;
            res = {1'b0, diff};
        end else if (b_gt_a) begin
            diff = b_mag - a_mag;
            res = {1'b1, diff};
        end else begin
            res = {1'b0, {N-1{1'b0}}};
        end
    end
    c = res;
end

endmodule

