module fixed_point_subtractor #(parameter Q=3, N=8) (
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);

reg [N-1:0] res;
assign c = res;

wire sign_a = a[N-1];
wire sign_b = b[N-1];
wire same_sign = (sign_a == sign_b);

wire [N-1:0] abs_b = sign_b ? (~b + 1) : b;
wire [N-1:0] same_sign_diff = a - b;
wire [N-1:0] sum = a + abs_b;

always @(*) begin
    if (same_sign) begin
        if (same_sign_diff == 0) begin
            res = 0;
        end else if (sign_a) begin
            res = ~same_sign_diff + 1;
        end else begin
            res = ~same_sign_diff + 1;
        end
    end else begin
        if (a > abs_b) begin
            res = sum;
        end else begin
            res = ~sum + 1;
        end
    end
end

endmodule

