module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

reg [2:0] counter;
reg a_sign, b_sign, z_sign;
reg [7:0] a_exponent, b_exponent, sum_exp;
reg [22:0] a_mantissa, b_mantissa;
reg [47:0] product;
reg guard_bit, round_bit, sticky;
reg [22:0] z_mantissa;
reg [7:0] z_exponent;

wire a_is_zero = (a == 32'd0);
wire b_is_zero = (b == 32'd0);
wire a_is_inf = (a_exponent == 8'hff) && (a_mantissa == 23'd0);
wire b_is_inf = (b_exponent == 8'hff) && (b_mantissa == 23'd0);
wire either_nan = (a_exponent == 8'hff && a_mantissa != 0) || (b_exponent == 8'hff && b_mantissa != 0);
wire either_inf = a_is_inf || b_is_inf;

always @(posedge clk) begin
    if (rst) begin
        counter <= 3'b0;
        z <= 32'b0;
    end else begin
        case (counter)
            3'd0: begin

                a_sign <= a[31];
                b_sign <= b[31];
                a_exponent <= a[30:23];
                b_exponent <= b[30:23];
                a_mantissa <= a[22:0];
                b_mantissa <= b[22:0];

                if (either_nan) begin
                    z <= 32'h7FC00000;

                    counter <= 3'd0;
                end else if (either_inf) begin
                    if ((a_is_inf && b_is_zero) || (b_is_inf && a_is_zero)) begin
                        z <= 32'h7FC00000;

                    end else begin
                        z <= {a_sign ^ b_sign, 8'hff, 23'd0};

                    end
                    counter <= 3'd0;
                end else begin
                    counter <= 3'd1;
                end
            end

            3'd1: begin

                reg [23:0] a_mant = (a_exponent != 0) ? {1'b1, a_mantissa} : {1'b0, a_mantissa};
                reg [23:0] b_mant = (b_exponent != 0) ? {1'b1, b_mantissa} : {1'b0, b_mantissa};

                product <= a_mant * b_mant;
                sum_exp <= (a_exponent == 0 ? 8'd1 : a_exponent) + (b_exponent == 0 ? 8'd1 : b_exponent) - 8'd127;
                counter <= 3'd2;
            end

            3'd2: begin

                reg [47:0] p = product;
                integer leading_one;
                leading_one = 47;
                while (p[leading_one] == 0) leading_one = leading_one - 1;

                if (leading_one == 47) begin
                    p = p >> 1;
                    sum_exp = sum_exp + 1;
                end
                product <= p;
                counter <= 3'd3;
            end

            3'd3: begin

                guard_bit = product[22];
                round_bit = product[21];
                sticky = |product[20:0];

                if ((guard_bit && round_bit) || (guard_bit && sticky)) begin
                    if (product[23]) begin
                        z_mantissa = product[23:1] + 1;

                        if (z_mantissa[23]) begin
                            z_mantissa = z_mantissa + 1;
                            sum_exp = sum_exp + 1;
                        end
                    end else begin
                        z_mantissa = product[23:1] + 1;
                    end
                end else begin
                    z_mantissa = product[23:1];
                end
                counter <= 3'd4;
            end

            3'd4: begin

                if (sum_exp > 254) begin
                    z <= {z_sign, 8'hff, 23'd0};

                end else if (sum_exp < 1) begin
                    z <= {z_sign, 8'd0, z_mantissa[23:1]};

                end else begin
                    z <= {z_sign, sum_exp, z_mantissa[22:0]};

                end
                counter <= 3'd0;
            end

            default: counter <= 3'd0;
        endcase
    end
end

endmodule

