    input wire wclk,
    input wire rclk,
    input wire wrstn,
    input wire rrstn,
    input wire winc,
    input wire rinc,
    input wire [WIDTH-1:0] wdata,
    output wire wfull,
    output wire rempty,
    output wire [WIDTH-1:0] rdata
);

    reg [3:0] waddr_bin, raddr_bin;
    wire [3:0] wptr_gray, rptr_gray;


    assign wptr_gray = (waddr_bin >> 1) ^ waddr_bin;
    assign rptr_gray = (raddr_bin >> 1) ^ raddr_bin;


    reg [3:0] rptr_buff1, rptr_buff2;
    reg [3:0] wptr_buff1, wptr_buff2;


    always @(posedge wclk or negedge wrstn) begin
        if (~wrstn) begin
            rptr_buff1 <= 4'b0;
            rptr_buff2 <= 4'b0;
        end else begin
            rptr_buff1 <= rptr_gray;
            rptr_buff2 <= rptr_buff1;
        end
    end


    always @(posedge rclk or negedge rrstn) begin
        if (~rrstn) begin
            wptr_buff1 <= 4'b0;
            wptr_buff2 <= 4'b0;
        end else begin
            wptr_buff1 <= wptr_gray;
            wptr_buff2 <= wptr_buff1;
        end
    end


    assign wfull = (wptr_gray == {~rptr_buff2[3:2], rptr_buff2[1:0]});
    assign rempty = (rptr_gray == wptr_buff2);


    always @(posedge wclk or negedge wrstn) begin
        if (~wrstn) begin
            waddr_bin <= 4'b0;
        end else if (winc && ~wfull) begin
            waddr_bin <= waddr_bin + 1;
        end
    end


    always @(posedge rclk or negedge rrstn) begin
        if (~rrstn) begin
            raddr_bin <= 4'b0;
        end else if (rinc && ~rempty) begin
            raddr_bin <= raddr_bin + 1;
        end
    end


    dual_port_RAM #(
        .WIDTH(WIDTH),
        .DEPTH(DEPTH)
    ) ram (
        .wclk(wclk),
        .wenc(winc && ~wfull),
        .waddr(waddr_bin),
        .wdata(wdata),
        .rclk(rclk),
        .renc(rinc && ~rempty),
        .raddr(raddr_bin),
        .rdata(rdata)
    );

