module LIFObuffer (
    input [3:0] dataIn,
    input RW,
    input EN,
    input Rst,
    input Clk,
    output EMPTY,
    output FULL,
    output reg [3:0] dataOut
);

reg [2:0] SP;

reg [3:0] stack_mem [0:3];


assign EMPTY = (SP == 3'b100);
assign FULL = (SP == 3'b000);

always @(posedge Clk) begin
    if (Rst) begin
        SP <= 3'b100;
        stack_mem[0] <= 4'b0;
        stack_mem[1] <= 4'b0;
        stack_mem[2] <= 4'b0;
        stack_mem[3] <= 4'b0;
        dataOut <= 4'b0;
    end
    else if (EN) begin

        if (!FULL && !RW) begin
            stack_mem[SP - 1] <= dataIn;
            SP <= SP - 1;
        end

        else if (!EMPTY && RW) begin
            dataOut <= stack_mem[SP - 1];
            stack_mem[SP - 1] <= 4'b0;
            SP <= SP + 1;
        end
    end
end

endmodule

