module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output [7:0] clock,
    output red,
    output yellow,
    output green
);

    parameter idle = 2'b00;
    parameter s1_red = 2'b01;
    parameter s2_yellow = 2'b10;
    parameter s3_green = 2'b11;

    reg [7:0] cnt;
    reg [1:0] state;
    reg p_red, p_yellow, p_green;
    reg red_reg, yellow_reg, green_reg;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
        end else begin
            case (state)
                idle: state <= s1_red;
                s1_red: if (cnt == 3) state <= s3_green;
                s3_green: if (cnt == 3) state <= s2_yellow;
                s2_yellow: if (cnt == 3) state <= s1_red;
                default: state <= idle;
            endcase
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 10;
        end else begin
            if (pass_request && green_reg) begin
                cnt <= 10;
            end else if (!green_reg && p_green) begin
                cnt <= 60;
            end else if (!yellow_reg && p_yellow) begin
                cnt <= 5;
            end else if (!red_reg && p_red) begin
                cnt <= 10;
            end else begin
                cnt <= cnt - 1;
            end
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            red_reg <= 0;
            yellow_reg <= 0;
            green_reg <= 0;
        end else begin
            red_reg <= p_red;
            yellow_reg <= p_yellow;
            green_reg <= p_green;
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            p_red <= 0;
            p_yellow <= 0;
            p_green <= 0;
        end else begin
            p_red <= (state == s1_red);
            p_yellow <= (state == s2_yellow);
            p_green <= (state == s3_green);
        end
    end

    assign red = red_reg;
    assign yellow = yellow_reg;
    assign green = green_reg;
    assign clock = cnt;

endmodule

