            SUBU: begin
                res = a - b;
                carry_reg = (a >= b) ? 1'b1 : 1'b0;
                overflow_reg = 1'b0;
            end
            AND: begin
                res = a & b;
                {carry_reg, overflow_reg} = 2'b00;
            end
            OR: begin
                res = a | b;
                {carry_reg, overflow_reg} = 2'b00;
            end
            XOR: begin
                res = a ^ b;
                {carry_reg, overflow_reg} = 2'b00;
            end
            NOR: begin
                res = ~(a | b);
                {carry_reg, overflow_reg} = 2'b00;
            end
            SLT: begin
                res = ($signed(a) < $signed(b)) ? 32'd1 : 32'd0;
                {carry_reg, overflow_reg} = 2'b00;
            end
            SLTU: begin
                res = (a < b) ? 32'd1 : 32'd0;
                {carry_reg, overflow_reg} = 2'b00;
            end
            SLL: begin
                res = b << a[4:0];
                {carry_reg, overflow_reg} = 2'b00;
            end
            SRL: begin
                res = b >> a[4:0];
                {carry_reg, overflow_reg} = 2'b00;
            end
            SRA: begin
                res = $signed(b) >>> a[4:0];
                {carry_reg, overflow_reg} = 2'b00;
            end
            SLLV: begin
                res = b << a[4:0];
                {carry_reg, overflow_reg} = 2'b00;
            end
            SRLV: begin
                res = b >> a[4:0];
                {carry_reg, overflow_reg} = 2'b00;
            end
            SRAV: begin
                res = $signed(b) >>> a[4:0];
                {carry_reg, overflow_reg} = 2'b00;
            end
            LUI: begin
                res = {a[31:16], 16'b0};
                {carry_reg, overflow_reg} = 2'b00;
            end
            default: begin
                res = 32'bz;
                {carry_reg, overflow_reg} = 2'b00;
