module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

reg [15:0] SR;
reg [3:0] cnt;
reg start_cnt;
reg [7:0] abs_dividend, abs_divisor;
reg sign_dividend, sign_divisor;
reg [7:0] quotient;
reg [7:0] remainder;
reg [7:0] neg_divisor;

always @(posedge clk) begin
    if (rst) begin
        res_valid <= 1'b0;
        cnt <= 4'd0;
        start_cnt <= 1'b0;
        SR <= 16'b0;
        quotient <= 8'b0;
        remainder <= 8'b0;
        result <= 16'b0;
        sign_dividend <= 1'b0;
        sign_divisor <= 1'b0;
        abs_dividend <= 8'b0;
        abs_divisor <= 8'b0;
        neg_divisor <= 8'b0;
    end else begin
        if (opn_valid && !res_valid) begin

            if (sign) begin
                sign_dividend <= dividend[7];
                abs_dividend <= dividend[7] ? -dividend : dividend;
                sign_divisor <= divisor[7];
                abs_divisor <= divisor[7] ? -divisor : divisor;
            end else begin
                sign_dividend <= 1'b0;
                abs_dividend <= dividend;
                sign_divisor <= 1'b0;
                abs_divisor <= divisor;
            end


            SR <= { (abs_dividend << 1)[7:0], 8'b0 };
            neg_divisor <= -abs_divisor;
            cnt <= 4'd1;
            start_cnt <= 1'b1;
            res_valid <= 1'b0;
        end else if (start_cnt) begin
            if (cnt == 4'd8) begin

                start_cnt <= 1'b0;
                cnt <= 4'd0;
                remainder <= SR[15:8];
                quotient <= SR[7:0];


                if (sign) begin
                    if (sign_dividend ^ sign_divisor) begin
                        quotient <= -quotient;
                    end
                    if (sign_divisor) begin
                        remainder <= -remainder;
                    end
                end

                result <= {remainder, quotient};
                res_valid <= 1'b1;
            end else begin

                reg [8:0] sub_res;
                sub_res = SR[15:8] - neg_divisor;

                if (!sub_res[8]) begin
                    SR <= { sub_res[7:0], 1'b1, SR[7:1] };
                end else begin
                    SR <= { SR[15:8], 1'b0, SR[7:1] };
                end

                cnt <= cnt + 1;
            end
        end else if (res_valid) begin
            res_valid <= 1'b0;
        end
    end
end

endmodule

