    always @(*) begin
        a_reg = A;
        b_reg = B;
    end


    always @(*) begin
        reg [15:0] rem;
        reg [15:0] quo;
        integer i;

        rem = 16'b0;
        quo = 16'b0;

        for (i = 15;
 i >= 0;
 i = i - 1) begin
            reg [15:0] temp_rem;
            temp_rem = {rem[14:0], a_reg[i]};

            if (temp_rem >= b_reg) begin
                rem = temp_rem - b_reg;
                quo[i] = 1'b1;
            end else begin
                rem = temp_rem;
                quo[i] = 1'b0;
            end
        end

        result = quo;
        odd = rem;
    end

endmodule

