                    i <= i + 1;
            end else
                i <= 5'd0;


            if (i == 5'd16)
                done_r <= 1'b1;
            else if (i == 5'd17)
                done_r <= 1'b0;


            if (start) begin
                if (i == 5'd0) begin
                    areg <= ain;
                    breg <= bin;
                    yout_r <= 32'd0;
                end else if (i > 5'd0 && i < 5'd17) begin
                    if (areg[i-1])
                        yout_r <= yout_r + (breg << (i-1));
                end
            end
        end
    end

    assign yout = yout_r;
    assign done = done_r;

