always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        count <= 0;
        buffer[0] <= 0;
        buffer[1] <= 0;
        buffer[2] <= 0;
        buffer[3] <= 0;
        data_out <= 0;
        valid_out <= 0;
    end else begin
        valid_out <= 0;

        if (valid_in) begin
            buffer[count] <= data_in;

            if (count == 3) begin       
                data_out <= buffer[0] + buffer[1] + buffer[2] + data_in;

                valid_out <= 1;

                count <= 0;

            end else begin
                count <= count + 1;

            end
        end
    end
end

endmodule

