    wire [N-1:0] a_abs = a_sign ? (~a + 1) : a;
    wire [N-1:0] b_abs = b_sign ? (~b + 1) : b;
    wire a_abs_gt_b_abs = (a_abs > b_abs);
    wire [N-1:0] sub_result = a_abs_gt_b_abs ? (a_abs - b_abs) : (b_abs - a_abs);
    wire result_sign = a_abs_gt_b_abs ? a_sign : b_sign;

    always @* begin
        if (same_sign)
            res = sum_same_trunc;
        else
            res = {result_sign, sub_result};
    end

    assign c = res;

endmodule

