module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

    reg [2:0] counter;
    reg a_sign, b_sign, z_sign;
    reg [7:0] a_exponent, b_exponent, z_exponent;
    reg [22:0] a_mantissa, b_mantissa;
    reg [47:0] product;
    reg guard_bit, round_bit, sticky;
    reg [23:0] z_mantissa;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b0;
            z <= 32'd0;
            a_sign <= 0;
            b_sign <= 0;
            z_sign <= 0;
            a_exponent <= 0;
            b_exponent <= 0;
            z_exponent <= 0;
            a_mantissa <= 0;
            b_mantissa <= 0;
            product <= 0;
            guard_bit <= 0;
            round_bit <= 0;
            sticky <= 0;
            z_mantissa <= 0;
        end else begin
            case (counter)
                3'b000: begin

                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= {1'b1, a[22:0]};
                    b_mantissa <= {1'b1, b[22:0]};
                    counter <= counter + 1;
                end
                3'b001: begin

                    if ((a_exponent == 8'hff) && (a_mantissa != 0)) begin

                        z <= {1'b0, 8'hff, 23'h000001};
                        counter <= 3'b000;
                    end else if ((a_exponent == 8'hff) && (a_mantissa == 0)) begin

                        if ((b_exponent == 8'hff) && (b_mantissa != 0)) begin

                            z <= {1'b0, 8'hff, 23'h000001};
                        end else if ((b_exponent == 0) && (b_mantissa == 0)) begin

                            z <= {1'b0, 8'hff, 23'h000001};
                        end else begin

                            z_sign <= a_sign ^ b_sign;
                            z_exponent <= a_exponent;
                            z_mantissa <= 0;
                            counter <= 3'b000;
                        end
                    end else if ((b_exponent == 8'hff) && (b_mantissa != 0)) begin

                        z <= {1'b0, 8'hff, 23'h000001};
                        counter <= 3'b000;
                    end else if ((b_exponent == 8'hff) && (b_mantissa == 0)) begin

                        if ((a_exponent == 8'hff) && (a_mantissa != 0)) begin

                            z <= {1'b0, 8'hff, 23'h000001};
                        end else if ((a_exponent == 0) && (a_mantissa == 0)) begin

                            z <= {1'b0, 8'hff, 23'h000001};
                        end else begin

                            z_sign <= a_sign ^ b_sign;
                            z_exponent <= b_exponent;
                            z_mantissa <= 0;
                            counter <= 3'b000;
                        end
                    end else if ((a_exponent == 0) && (a_mantissa == 0) && (b_exponent == 0) && (b_mantissa == 0)) begin

                        z_sign <= a_sign ^ b_sign;
                        z_exponent <= 0;
                        z_mantissa <= 0;
                        counter <= 3'b000;
                    end else begin

                        product <= a_mantissa * b_mantissa;
                        counter <= counter + 1;
                    end
                end
                3'b010: begin

                    if (product[47]) begin
                        z_mantissa <= product[46:23];
                        guard_bit <= product[22];
                        round_bit <= product[21];
                        sticky <= |product[20:0];
                        z_exponent <= a_exponent + b_exponent - 127 + 1;
                    end else begin
                        z_mantissa <= product[45:22];
                        guard_bit <= product[21];
                        round_bit <= product[20];
                        sticky <= |product[19:0];
                        z_exponent <= a_exponent + b_exponent - 127;
                    end
                    counter <= counter + 1;
                end
                3'b011: begin

                    reg round_up;
                    round_up = (guard_bit & (round_bit | sticky)) | (guard_bit & ~z_mantissa[0] & (round_bit | sticky));
                    if (round_up) begin
                        if (z_mantissa == 24'hffffff) begin
                            z_mantissa <= 24'd0;
                            z_exponent <= z_exponent + 1;
                        end else begin
                            z_mantissa <= z_mantissa + 1;
                        end
                    end

                    if (z_exponent > 254) begin
                        z <= {z_sign, 8'hff, 23'd0};
                    end else if (z_exponent < 1) begin
                        z <= {z_sign, 23'd0};
                    end else begin
                        z <= {z_sign, z_exponent[7:0], z_mantissa[22:0]};
                    end
                    counter <= 3'b000;
                end
                default: counter <= 3'b000;
            endcase
        end
    end

endmodule

