module asyn_fifo #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wclk,
    input winc,
    input rclk,
    input rinc,
    input [WIDTH-1:0] wdata,
    output rempty,
    output wfull,
    output [WIDTH-1:0] rdata
);


    wire wen = winc && !wfull;
    wire ren = rinc && !rempty;
    reg [3:0] waddr_bin, raddr_bin;


    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn)
            waddr_bin <= 0;
        else if (wen)
            waddr_bin <= waddr_bin + 1;
    end


    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn)
            raddr_bin <= 0;
        else if (ren)
            raddr_bin <= raddr_bin + 1;
    end


    wire [3:0] wptr = waddr_bin ^ (waddr_bin >> 1);
    wire [3:0] rptr = raddr_bin ^ (raddr_bin >> 1);


    reg [3:0] rptr_sync1, rptr_sync2;
    reg [3:0] wptr_sync1, wptr_sync2;


    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            rptr_sync1 <= 0;
            rptr_sync2 <= 0;
        end
        else begin
            rptr_sync1 <= rptr;
            rptr_sync2 <= rptr_sync1;
        end
    end


    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            wptr_sync1 <= 0;
            wptr_sync2 <= 0;
        end
        else begin
            wptr_sync1 <= wptr;
            wptr_sync2 <= wptr_sync1;
        end
    end


    assign rempty = (rptr == rptr_sync2);
    assign wfull = (wptr[3] != rptr_sync2[3]) && 
                   (wptr[2] != rptr_sync2[2]) && 
                   (wptr[1:0] == rptr_sync2[1:0]);


    dual_port_RAM #(
        .DEPTH(DEPTH),
        .WIDTH(WIDTH)
    ) ram (
        .wclk(wclk),
        .wenc(wen),
        .waddr(waddr_bin),
        .wdata(wdata),
        .rclk(rclk),
        .renc(ren),
        .raddr(raddr_bin),
        .rdata(rdata)
    );

endmodule

