module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

    reg [7:0] saved_dividend_abs, saved_divisor_abs;
    reg [7:0] neg_divisor_reg;
    reg [15:0] sr_reg;
    reg [3:0] cnt_reg;
    reg start_cnt_reg;
    reg [7:0] quotient;
    reg [7:0] remainder;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            res_valid <= 0;
            result <= 0;
            saved_dividend_abs <= 0;
            saved_divisor_abs <= 0;
            neg_divisor_reg <= 0;
            sr_reg <= 0;
            cnt_reg <= 0;
            start_cnt_reg <= 0;
            quotient <= 0;
            remainder <= 0;
        end else begin
            if (opn_valid && !res_valid) begin

                if (sign) begin
                    saved_dividend_abs <= dividend[7] ? -dividend : dividend;
                    saved_divisor_abs <= divisor[7] ? -divisor : divisor;
                end else begin
                    saved_dividend_abs <= dividend;
                    saved_divisor_abs <= divisor;
                end
                neg_divisor_reg <= ~saved_divisor_abs + 1;


                sr_reg <= {saved_dividend_abs, 8'b0} << 1;
                cnt_reg <= 1;
                start_cnt_reg <= 1;
                res_valid <= 0;
            end else if (start_cnt_reg) begin
                if (cnt_reg == 8) begin

                    remainder <= sr_reg[15:8];
                    quotient <= sr_reg[7:0];

                    if (sign) begin
                        reg [7:0] quotient_signed = (saved_dividend_abs[7] ^ saved_divisor_abs[7]) ? -quotient : quotient;
                        reg [7:0] remainder_signed = saved_dividend_abs[7] ? -remainder : remainder;
                        result <= {remainder_signed, quotient_signed};
                    end else begin
                        result <= {remainder, quotient};
                    end
                    res_valid <= 1;
                    start_cnt_reg <= 0;
                    cnt_reg <= 0;
                end else begin

                    wire [8:0] sub_result = {1'b0, sr_reg[15:8]} - {1'b0, neg_divisor_reg};
                    wire carry_out = sub_result[8];
                    wire [7:0] new_remainder = carry_out ? sr_reg[15:8] : sub_result[7:0];
                    wire new_quotient_bit = ~carry_out;

                    sr_reg <= {new_remainder, sr_reg[7:1], new_quotient_bit};
                    cnt_reg <= cnt_reg + 1;
                end
            end else begin
                res_valid <= res_valid && !opn_valid;
            end
        end
    end

endmodule

