    if (!rst_n) begin
        i <= 5'd0;
        areg <= 16'd0;
        breg <= 16'd0;
        yout_r <= 32'd0;
        done_r <= 1'b0;
        yout <= 32'd0;
        done <= 1'b0;
    end else begin

        if (start) begin
            i <= (i < 5'd17) ? i + 1 : i;
        end else begin
            i <= 5'd0;
