        if (start && (i == 5'd0)) begin
            areg <= ain;
            breg <= bin;
        end else if (!start) begin
            areg <= 16'd0;
            breg <= 16'd0;
        end


        if (start) begin
            if (i > 5'd0 && i < 5'd17) begin
                if (areg[i-1]) begin
                    yout_r <= yout_r + (breg << (i-1));
                end
            end
        end else begin
            yout_r <= 32'd0;
        end


        done_r <= (i == 5'd16);


        yout <= yout_r;
        done <= done_r;
    end
end

