module cla_16bit (
    input [15:0] A,
    input [15:0] B,
    input C_in,
    output [15:0] S,
    output C_out,
    output G,
    output P
);

    wire [4:0] carry;
    wire [3:0] G_group, P_group;
    assign carry[0] = C_in;

    generate
        genvar i;
        for (i = 0;
 i < 4;
 i = i + 1) begin : group
            wire [3:0] a = A[4*i +3 : 4*i];
            wire [3:0] b = B[4*i +3 : 4*i];
            wire [3:0] p = a ^ b;
            wire [3:0] g = a & b;

            wire group_p = &p;
            wire group_g = g[3] | (p[3] & g[2]) | (p[3] & p[2] & g[1]) | (p[3] & p[2] & p[1] & g[0]);

            assign G_group[i] = group_g;
            assign P_group[i] = group_p;
            assign carry[i+1] = group_g | (group_p & carry[i]);

            wire [3:0] c_in = carry[i];
            assign S[4*i +3 : 4*i] = a ^ b ^ c_in;
        end
    endgenerate

    assign C_out = carry[4];
    assign G = G_group[3] | (P_group[3] & G_group[2]) | (P_group[3] & P_group[2] & G_group[1]) | (P_group[3] & P_group[2] & P_group[1] & G_group[0]);
    assign P = &P_group;

endmodule

