        .S(S[15:0]),
        .C_out(),
        .G(g0),
        .P(p0)
    );

    cla_16bit cla1 (
        .A(A[31:16]),
        .B(B[31:16]),
        .C_in(g0),
        .S(S[31:16]),
        .C_out(),
        .G(g1),
        .P(p1)
    );

