module fixed_point_adder #(
    parameter Q = 4,
    parameter N = 8
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);

    wire a_sign = a[N-1];
    wire [N-1:0] a_abs = a_sign ? (~a + 1) : a;

    wire b_sign = b[N-1];
    wire [N-1:0] b_abs = b_sign ? (~b + 1) : b;

    wire same_sign = (a_sign == b_sign);

    wire [N-1:0] sum_abs = a_abs + b_abs;
    wire a_larger = (a_abs > b_abs);
    wire b_larger = (b_abs > a_abs);

    wire [N-1:0] sub_abs = a_larger ? a_abs - b_abs : (b_larger ? b_abs - a_abs : 0);
    wire sub_sign = a_larger ? a_sign : (b_larger ? b_sign : 0);

    wire [N-1:0] result_abs = same_sign ? sum_abs : sub_abs;
    wire result_sign = same_sign ? a_sign : sub_sign;

    always @(*) begin
        c = {result_sign, result_abs[N-2:0]};
    end

endmodule

