module fixed_point_subtractor #(parameter Q=2, N=4) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c
);

reg [N-1:0] res;
reg sign_a, sign_b;
reg [N-2:0] magnitude_a, magnitude_b;
reg [N-1:0] abs_a, abs_b;
reg [N-1:0] sum;

always @* begin
    sign_a = a[N-1];
    sign_b = b[N-1];
    magnitude_a = a[N-2:0];
    magnitude_b = b[N-2:0];


    abs_a = sign_a ? (~a + 1) : a;
    abs_b = sign_b ? (~b + 1) : b;

    if (sign_a == sign_b) begin

        res = a - b;
        res[N-1] = sign_a;

    end else begin

        sum = abs_a + abs_b;
        if (abs_a > abs_b) begin
            res = {1'b0, sum[N-2:0]};

        end else begin
            res = {1'b1, sum[N-2:0]};

        end
    end


    if (res == 0) begin
        res[N-1] = 1'b0;
    end

    c = res;
end

endmodule

