module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

reg [2:0] counter;
reg [23:0] a_mantissa, b_mantissa;
reg [9:0] a_exponent, b_exponent;
reg a_sign, b_sign;
reg [49:0] product;
reg guard_bit, round_bit, sticky;
reg z_sign;
reg [9:0] z_exponent;
reg [22:0] z_mantissa;
reg [47:0] product_shifted;
reg [3:0] shift_amount;

wire a_is_nan, a_is_inf, a_is_zero;
wire b_is_nan, b_is_inf, b_is_zero;

assign a_is_nan = (a_exponent == 9'hff) && (a_mantissa != 24'd0);
assign a_is_inf = (a_exponent == 9'hff) && (a_mantissa == 24'd0);
assign a_is_zero = (a_exponent == 9'd0) && (a_mantissa == 24'd0);

assign b_is_nan = (b_exponent == 9'hff) && (b_mantissa != 24'd0);
assign b_is_inf = (b_exponent == 9'hff) && (b_mantissa == 24'd0);
assign b_is_zero = (b_exponent == 9'd0) && (b_mantissa == 24'd0);

always @(posedge clk) begin
    if (rst) begin
        counter <= 3'd0;
        z <= 32'd0;
        a_sign <= 1'b0;
        b_sign <= 1'b0;
        z_sign <= 1'b0;
        z_exponent <= 9'd0;
        z_mantissa <= 23'd0;
        product <= 49'd0;
        guard_bit <= 1'b0;
        round_bit <= 1'b0;
        sticky <= 1'b0;
        a_mantissa <= 24'd0;
        b_mantissa <= 24'd0;
        a_exponent <= 9'd0;
        b_exponent <= 9'd0;
        shift_amount <= 4'd0;
        product_shifted <= 48'd0;
    end else begin
        case (counter)
            3'd0: begin

                a_sign <= a[31];
                a_exponent <= a[30:23];
                a_mantissa <= (a[30:23] == 9'd0) ? {1'b0, a[22:0]} : {1'b1, a[22:0]};
                b_sign <= b[31];
                b_exponent <= b[30:23];
                b_mantissa <= (b[30:23] == 9'd0) ? {1'b0, b[22:0]} : {1'b1, b[22:0]};
                counter <= counter + 1;
            end
            3'd1: begin

                if (a_is_nan || b_is_nan || 
                    (a_is_inf && b_is_zero) || (b_is_inf && a_is_zero) ||
                    a_is_inf || b_is_inf || a_is_zero || b_is_zero) begin
                    z_sign <= a_sign ^ b_sign;
                    z_exponent <= 9'hff;
                    z_mantissa <= 23'h1;
                    counter <= 3'd2;
                end else begin

                    product <= {1'b0, a_mantissa} * {1'b0, b_mantissa};
                    counter <= counter + 1;
                end
            end
            3'd2: begin

                if (a_is_nan || b_is_nan || 
                    (a_is_inf && b_is_zero) || (b_is_inf && a_is_zero) ||
                    a_is_inf || b_is_inf || a_is_zero || b_is_zero) begin
                    z <= {z_sign, z_exponent, z_mantissa};
                    counter <= 3'd0;
                end else begin

                    integer i;
                    reg found;
                    found = 1'b0;
                    shift_amount = 4'd0;
                    for (i = 49;
 i >= 0;
 i = i - 1) begin
                        if (product[i] && !found) begin
                            shift_amount = 47 - i;
                            found = 1'b1;
                        end
                    end
                    product_shifted <= product >> shift_amount;
                    guard_bit <= product[47 - shift_amount];
                    round_bit <= product[46 - shift_amount];
                    sticky <= |product[45 - shift_amount : 0];
                    z_exponent <= a_exponent + b_exponent - 9'd127 + shift_amount;
                    counter <= counter + 1;
                end
            end
            3'd3: begin

                if (guard_bit && (round_bit || sticky)) begin
                    z_mantissa <= product_shifted[23:1] + 1'b1;
                    if (z_mantissa == 24'd0) begin
                        z_exponent <= z_exponent + 1'd1;
                    end
                end else begin
                    z_mantissa <= product_shifted[23:1];
                end

                if (z_exponent >= 9'hff) begin
                    z_exponent <= 9'hff;
                    z_mantissa <= 23'd0;
                end else if (z_exponent == 9'd0) begin
                    z_mantissa <= 23'd0;
                end
                z <= {z_sign, z_exponent, z_mantissa};
                counter <= 3'd0;
            end
            default: counter <= 3'd0;
        endcase
    end
end

endmodule

