) (
    input wclk,
    input rclk,
    input wrstn,
    input rrstn,
    input winc,
    input rinc,
    input [WIDTH-1:0] wdata,
    output wfull,
    output rempty,
    output [WIDTH-1:0] rdata
);

    localparam PTR_WIDTH = $clog2(DEPTH);

    reg [PTR_WIDTH-1:0] waddr_bin, raddr_bin;
    wire wenc = winc && ~wfull;
    wire renc = rinc && ~rempty;

    wire [PTR_WIDTH-1:0] waddr_gray = (waddr_bin >> 1) ^ waddr_bin;
    wire [PTR_WIDTH-1:0] raddr_gray = (raddr_bin >> 1) ^ raddr_bin;


    reg [PTR_WIDTH-1:0] raddr_gray_sync1, raddr_gray_sync2;
    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) {raddr_gray_sync1, raddr_gray_sync2} <= 0;
        else {raddr_gray_sync1, raddr_gray_sync2} <= {raddr_gray, raddr_gray_sync1};
    end


    reg [PTR_WIDTH-1:0] waddr_gray_sync1, waddr_gray_sync2;
    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) {waddr_gray_sync1, waddr_gray_sync2} <= 0;
        else {waddr_gray_sync1, waddr_gray_sync2} <= {waddr_gray, waddr_gray_sync1};
    end

    assign wfull = (waddr_gray == {~raddr_gray_sync2[PTR_WIDTH-1:PTR_WIDTH-2], raddr_gray_sync2[PTR_WIDTH-3:0]});
    assign rempty = (raddr_gray == waddr_gray_sync2);


    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) waddr_bin <= 0;
        else if (wenc) waddr_bin <= waddr_bin + 1;
    end

    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) raddr_bin <= 0;
        else if (renc) raddr_bin <= raddr_bin + 1;
    end


    dual_port_RAM #(
        .WIDTH(WIDTH),
        .DEPTH(DEPTH)
    ) ram (
        .wclk(wclk),
        .wenc(wenc),
        .waddr(waddr_bin),
        .wdata(wdata),
