module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

    reg [1:0] state, next_state;
    localparam IDLE   = 2'b00;
    localparam STATE1 = 2'b01;
    localparam STATE2 = 2'b10;

    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            state <= IDLE;
            data_out <= 1'b0;
        end else begin
            state <= next_state;
            data_out <= (state == STATE2) && (data_in == 1'b0);
        end
    end

    always @(*) begin
        case (state)
            IDLE:   next_state = data_in ? IDLE : STATE1;
            STATE1: next_state = data_in ? STATE2 : IDLE;
            STATE2: next_state = IDLE;
            default: next_state = IDLE;
        endcase
    end

endmodule

