module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output [7:0] clock,
    output red,
    output yellow,
    output green
);


parameter idle    = 2'b00,
          s1_red  = 2'b01,
          s2_yellow = 2'b10,
          s3_green  = 2'b11;


reg [7:0] cnt;
reg [1:0] state;
reg p_red, p_yellow, p_green;


