module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

reg [7:0] current_dividend, current_divisor;
reg [8:0] abs_dividend, abs_divisor;
reg [8:0] NEG_DIVISOR;
reg [16:0] SR;

reg [3:0] cnt;
reg start_cnt;
reg quotient_sign, remainder_sign;

always @(posedge clk) begin
    if (rst) begin
        res_valid <= 0;
        SR <= 0;
        cnt <= 0;
        start_cnt <= 0;
        current_dividend <= 0;
        current_divisor <= 0;
        quotient_sign <= 0;
        remainder_sign <= 0;
    end else begin
        if (opn_valid && !res_valid && !start_cnt) begin
            current_dividend <= dividend;
            current_divisor <= divisor;
            quotient_sign <= sign ? (dividend[7] ^ divisor[7]) : 0;
            remainder_sign <= sign ? dividend[7] : 0;
            abs_dividend <= sign ? (dividend[7] ? -dividend : dividend) : dividend;
            abs_divisor <= sign ? (divisor[7] ? -divisor : divisor) : divisor;
            NEG_DIVISOR <= -{1'b0, (divisor[7] ? -divisor : divisor)};
            SR <= {abs_dividend, 1'b0};
            cnt <= 8;
            start_cnt <= 1;
            res_valid <= 0;
        end else if (start_cnt) begin
            if (cnt > 0) begin
                wire [8:0] temp_remainder = SR[16:8] - NEG_DIVISOR;
                wire carry = ~temp_remainder[8];
                SR <= {carry ? temp_remainder : SR[16:8], SR[15:0] << 1 | carry};
                cnt <= cnt - 1;
            end else begin
                wire [8:0] temp_remainder = SR[16:8] - NEG_DIVISOR;
                wire carry = ~temp_remainder[8];
                SR <= {carry ? temp_remainder : SR[16:8], SR[15:0] << 1 | carry};
                start_cnt <= 0;
                res_valid <= 1;
                cnt <= 0;
            end
        end else if (res_valid) begin
            res_valid <= 0;
        end
    end
end

always @(*) begin
    if (res_valid) begin
        reg [8:0] quotient = SR[7:0];
        reg [8:0] remainder = SR[16:8];
        if (sign) begin
            quotient = quotient_sign ? -quotient : quotient;
            remainder = remainder_sign ? -remainder : remainder;
        end
        result[15:8] = remainder[8] ? (~remainder[7:0] + 1) : remainder[7:0];
        result[7:0] = quotient[7:0];
    end else begin
        result = 16'b0;
    end
end

endmodule

