module fixed_point_adder #(
    parameter Q = 2,
    parameter N = 4
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);

    reg [N-1:0] res;
    wire same_sign = (a[N-1] == b[N-1]);
    wire [N-1:0] abs_a = a[N-1] ? (~a + 1) : a;
    wire [N-1:0] abs_b = b[N-1] ? (~b + 1) : b;
    wire [N-1:0] sum_abs = abs_a + abs_b;
    wire [N-1:0] diff_abs = (abs_a > abs_b) ? (abs_a - abs_b) : (abs_b - abs_a);
    wire diff_sign = (abs_a > abs_b) ? 1'b0 : 1'b1;

    always @(*) begin
        if (same_sign) begin
            res = {a[N-1], sum_abs[N-2:0]};
        end else begin
            res = {diff_sign, diff_abs[N-2:0]};
        end
    end

    assign c = res;

endmodule

