    input [N-1:0] b,
    output [N-1:0] c
);

reg [N-1:0] res;
wire sign_a = a[N-1];
wire sign_b = b[N-1];
wire [N-Q-1:0] int_a = a[N-2 : Q];
wire [Q-1:0] frac_a = a[Q-1 : 0];
wire [N-Q-1:0] int_b = b[N-2 : Q];
wire [Q-1:0] frac_b = b[Q-1 : 0];

always @(*) begin
    if (sign_a == sign_b) begin

        res = a - b;
        if (res == 0) res = 0;
    end else begin

        reg [N-1:0] a_abs = sign_a ? (~a + 1) : a;
        reg [N-1:0] b_abs = sign_b ? (~b + 1) : b;
        reg [N-1:0] sum_abs = a_abs + b_abs;
        reg sign = (a_abs > b_abs) ? 1'b0 : 1'b1;
        res = {sign, sum_abs[N-2:Q], sum_abs[Q-1:0]};
    end
end

assign c = res;

endmodule

