module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

reg [2:0] counter;
reg [23:0] a_mant, b_mant;
reg [8:0] a_exp, b_exp;
reg a_sign, b_sign;
reg [48:0] product;
reg [22:0] mantissa;
reg [8:0] exp_sum;
reg guard, round, sticky;
reg [47:0] norm_product;
reg z_sign;
reg [8:0] z_exp;
reg [22:0] z_man;

always @(posedge clk) begin
    if (rst) begin
        counter <= 3'b0;
        z <= 32'd0;
        a_sign <= 1'b0;
        b_sign <= 1'b0;
        a_exp <= 9'd0;
        b_exp <= 9'd0;
        a_mant <= 24'd0;
        b_mant <= 24'd0;
        product <= 49'd0;
        mantissa <= 23'd0;
        exp_sum <= 9'd0;
        guard <= 1'b0;
        round <= 1'b0;
        sticky <= 1'b0;
        norm_product <= 48'd0;
        z_sign <= 1'b0;
        z_exp <= 9'd0;
        z_man <= 23'd0;
    end else begin
        case (counter)
            3'b000: begin 
                a_sign <= a[31];
                b_sign <= b[31];
                a_exp <= {1'b0, a[30:23]};
                b_exp <= {1'b0, b[30:23]};
                a_mant <= {1'b1, a[22:0]};
                b_mant <= {1'b1, b[22:0]};

                if ((a_exp == 9'h1ff || b_exp == 9'h1ff) && a_mant != 0 && b_mant != 0) begin 
                    z <= {a_sign ^ b_sign, 8'hff, 23'h000001};
                end else if (a_exp == 9'h1ff) begin 
                    z <= {a_sign ^ b_sign, 8'hff, 23'd0};
                end else if (b_exp == 9'h1ff) begin 
                    z <= {a_sign ^ b_sign, 8'hff, 23'd0};
                end else if (a_mant == 0 && b_mant == 0) begin 
                    z <= {a_sign ^ b_sign, 31'd0};
                end else begin
                    product <= a_mant * b_mant;
                    exp_sum <= a_exp + b_exp - 9'd127;
                    counter <= counter + 1;
                end
            end
            3'b001: begin 
                guard <= product[47];
                round <= product[46];
                sticky <= |product[45:0];
                if (product[48]) begin
                    norm_product <= product >> 1;
                    exp_sum <= exp_sum + 1;
                end else begin
                    norm_product <= product;
                end
                counter <= counter + 1;
            end
            3'b010: begin 
                if (guard && (round || sticky)) begin
                    if (norm_product[47]) begin
                        mantissa <= norm_product[46:24] + 1;
                        if (norm_product[46:24] == 23'h7fffff) begin 
                            exp_sum <= exp_sum + 1;
                            mantissa <= 23'd0;
                        end
                    end
                end else begin
                    mantissa <= norm_product[46:24];
                end
                counter <= counter + 1;
            end
            3'b011: begin 
                if (exp_sum > 9'd254) begin 
                    z <= {a_sign ^ b_sign, 8'hff, 23'd0};
                end else if (exp_sum < 1) begin 
                    z <= {a_sign ^ b_sign, 31'd0};
                end else begin
                    z <= {a_sign ^ b_sign, exp_sum[7:0], mantissa};
                end
                counter <= 3'b000;
            end
            default: counter <= 3'b000;
        endcase
    end
end

endmodule

