module asyn_fifo #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wire wclk,
    input wire rclk,
    input wire wrstn,
    input wire rrstn,
    input wire winc,
    input wire rinc,
    input wire [WIDTH-1:0] wdata,
    output wire wfull,
    output wire rempty,
    output wire [WIDTH-1:0] rdata
);


    dual_port_RAM #(
        .DEPTH(DEPTH),
        .WIDTH(WIDTH)
    ) ram (
        .wclk(wclk),
        .wenc(wenc),
        .waddr(waddr_bin),
        .wdata(wdata),
        .rclk(rclk),
        .renc(renc),
        .raddr(raddr_bin),
        .rdata(rdata)
    );


    reg [3:0] waddr_bin;
    wire [3:0] wptr = (waddr_bin >> 1) ^ waddr_bin;

    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn)
            waddr_bin <= 4'b0;
        else if (winc && !wfull)
            waddr_bin <= waddr_bin + 1;
    end


    reg [3:0] raddr_bin;
    wire [3:0] rptr = (raddr_bin >> 1) ^ raddr_bin;

    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn)
            raddr_bin <= 4'b0;
        else if (rinc && !rempty)
            raddr_bin <= raddr_bin + 1;
    end


    reg [3:0] rptr_buf1, rptr_syn;
    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            rptr_buf1 <= 4'b0;
            rptr_syn <= 4'b0;
        end else begin
            rptr_buf1 <= rptr;
            rptr_syn <= rptr_buf1;
        end
    end


    reg [3:0] wptr_buf1, wptr_syn;
    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            wptr_buf1 <= 4'b0;
            wptr_syn <= 4'b0;
        end else begin
            wptr_buf1 <= wptr;
            wptr_syn <= wptr_buf1;
        end
    end


    assign rempty = (rptr_syn == wptr);
    assign wfull = (wptr[3] != rptr_syn[3]) && 
                   (wptr[2] != rptr_syn[2]) && 
                   (wptr[1:0] == rptr_syn[1:0]);


    wire wenc = winc && !wfull;
    wire renc = rinc && !rempty;

endmodule

module dual_port_RAM #(
    parameter DEPTH = 16,
    parameter WIDTH = 8
) (
    input wire wclk,
    input wire wenc,
    input wire [$clog2(DEPTH)-1:0] waddr,
    input wire [WIDTH-1:0] wdata,
    input wire rclk,
    input wire renc,
    input wire [$clog2(DEPTH)-1:0] raddr,
    output reg [WIDTH-1:0] rdata
);

    reg [WIDTH-1:0] RAM_MEM [0:DEPTH-1];


    always @(posedge wclk) begin
        if (wenc)
            RAM_MEM[waddr] <= wdata;
    end


    always @(posedge rclk) begin
        if (renc)
            rdata <= RAM_MEM[raddr];
    end

endmodule

