    input rst_n,
    input [3:0] d,
    output reg valid_out,
    output dout
);

reg [1:0] cnt;
reg [3:0] data_reg;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        cnt <= 2'b0;
        data_reg <= 4'b0;
        valid_out <= 1'b0;
    end else begin
        if (cnt == 2'b11) begin
            data_reg <= d;
            cnt <= 2'b00;
            valid_out <= 1'b1;
