module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

reg [1:0] state;

localparam STATE_IDLE = 2'b00,
           STATE_1    = 2'b01,
           STATE_2    = 2'b10;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        state <= STATE_IDLE;
        data_out <= 1'b0;
    end else begin
        case (state)
            STATE_IDLE: begin
                if (data_in == 1'b0) begin
                    state <= STATE_1;
                    data_out <= 1'b0;
                end else begin
                    state <= STATE_IDLE;
                    data_out <= 1'b0;
                end
            end
            STATE_1: begin
                if (data_in == 1'b1) begin
                    state <= STATE_2;
                    data_out <= 1'b0;
                end else begin
                    state <= STATE_IDLE;
                    data_out <= 1'b0;
                end
            end
            STATE_2: begin
                if (data_in == 1'b0) begin
                    state <= STATE_IDLE;
                    data_out <= 1'b1;
                end else begin
                    state <= STATE_IDLE;
                    data_out <= 1'b0;
                end
            end
            default: begin
                state <= STATE_IDLE;
                data_out <= 1'b0;
            end
        endcase
    end
end

endmodule

