module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output reg [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);

parameter idle = 2'b00;
parameter s3_green = 2'b01;
parameter s2_yellow = 2'b10;
parameter s1_red = 2'b11;

reg [1:0] state;
reg [7:0] cnt;
reg p_red, p_yellow, p_green;


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= idle;
    end else begin
        case (state)
            idle: state <= s3_green;
            s3_green: state <= (cnt == 0) ? s2_yellow : s3_green;
            s2_yellow: state <= (cnt == 0) ? s1_red : s2_yellow;
            s1_red: state <= (cnt == 0) ? s3_green : s1_red;
            default: state <= idle;
        endcase
    end
end


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        cnt <= 8'd10;
    end else begin
        if (pass_request && (state == s3_green)) begin
            cnt <= 8'd10;
        end else begin
            case (state)
                s3_green: cnt <= 8'd60;
                s2_yellow: cnt <= 8'd5;
                s1_red: cnt <= 8'd10;
                default: cnt <= (cnt == 0) ? 8'd0 : cnt - 1;
            endcase
        end
    end
end


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        p_red <= 0;
        p_yellow <= 0;
        p_green <= 0;
        red <= 0;
        yellow <= 0;
        green <= 0;
    end else begin
        p_red <= (state == s1_red);
        p_yellow <= (state == s2_yellow);
        p_green <= (state == s3_green);
        red <= p_red;
        yellow <= p_yellow;
        green <= p_green;
    end
end

assign clock = cnt;

endmodule

