module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output [15:0] result
);

reg [7:0] div_abs, divisor_abs;
reg [7:0] saved_dividend, saved_divisor;
reg [8:0] neg_divisor;

reg [16:0] SR;

reg [3:0] cnt;
reg start_cnt;

wire [8:0] remainder_quotient;


assign remainder_quotient = {SR[16:8], SR[7:0]};

always @(posedge clk) begin
    if (rst) begin
        res_valid <= 1'b0;
        cnt <= 4'b0;
        start_cnt <= 1'b0;
        SR <= 17'b0;
        div_abs <= 8'b0;
        divisor_abs <= 8'b0;
        neg_divisor <= 9'b0;
        saved_dividend <= 8'b0;
        saved_divisor <= 8'b0;
    end else begin
        if (opn_valid && !res_valid) begin

            saved_dividend <= dividend;
            saved_divisor <= divisor;

            if (sign) begin
                div_abs <= dividend[7] ? (~dividend + 1) : dividend;
                divisor_abs <= divisor[7] ? (~divisor + 1) : divisor;
            end else begin
                div_abs <= dividend;
                divisor_abs <= divisor;
            end


            SR <= {div_abs, 8'b0} << 1;
            neg_divisor <= -divisor_abs;

            cnt <= 4'd1;
            start_cnt <= 1'b1;
            res_valid <= 1'b0;
        end else if (start_cnt) begin
            if (cnt <= 8) begin
                if (cnt == 8) begin

                    res_valid <= 1'b1;
                    start_cnt <= 1'b0;
                end else begin

                    if (SR[16:9] >= neg_divisor[8:1]) begin

                        SR <= {1'b1, SR[15:8] - neg_divisor[8:1], SR[7:0], 1'b1};
                    end else begin
                        SR <= {1'b0, SR[15:8], SR[7:0], 1'b0};
                    end
                    cnt <= cnt + 1;
                end
            end else begin

                if (res_valid) begin
                    res_valid <= 1'b0;
                end
            end
        end
    end
end

assign result = {remainder_quotient[16:9], remainder_quotient[7:0]};
assign remainder_quotient = (div_abs >= divisor_abs) ? {div_abs - divisor_abs, saved_divisor} : {div_abs, saved_divisor};

endmodule

