    input [7:0] B,
    output reg [15:0] result,
    output reg [15:0] odd
);

    reg [15:0] a_reg, b_reg;


    always @(*) begin
        a_reg = A;
        b_reg = B;
    end


    always @(*) begin
        reg [7:0] remainder;
        reg [15:0] quotient;
        integer i;

        remainder = 8'b0;
        quotient = 16'b0;

        for (i = 15;
 i >= 0;
 i = i - 1) begin

            remainder = {remainder[6:0], a_reg[i]};

            if (remainder >= b_reg) begin
                quotient[i] = 1'b1;
                remainder = remainder - b_reg;
            end
        end


        result = quotient;
        odd = {remainder, 8'b0};
    end

endmodule

