module accu (
    input clk,
    input rst_n,
    input [7:0] data_in,
    input valid_in,
    output valid_out,
    output [9:0] data_out
);

reg [1:0] count;
reg [31:0] shift_reg;

wire [9:0] sum;


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        shift_reg <= 32'd0;
        count <= 2'd0;
    end else begin
        if (valid_in) begin
            shift_reg <= {shift_reg[23:0], data_in};
            count <= count + 1;
        end
    end
end


