module fixed_point_adder #(
    parameter Q = 4,
    parameter N = 8
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);

    reg [N-1:0] res;

    always @* begin
        reg a_sign, b_sign;
        reg a_larger;
        reg [N-1:0] a_abs, b_abs;

        a_sign = a[N-1];
        b_sign = b[N-1];

        if (a_sign == b_sign) begin

            res = a + b;
        end else begin

            a_abs = a_sign ? (~a + 1) : a;
            b_abs = b_sign ? (~b + 1) : b;

            a_larger = (a_abs > b_abs);
            if (a_larger) begin
                res = a_abs - b_abs;
                res[N-1] = 1'b0;

            end else begin
                res = b_abs - a_abs;
                res[N-1] = 1'b0;

            end
        end



        if (a_sign != b_sign) begin

            if (res == 0) begin
                res = 0;
            end else if (res[N-1] != (a_sign ? 1'b1 : 1'b0)) begin

                res = a_sign ? {1'b1, {(N-1){1'b0}}} : {1'b0, {(N-1){1'b1}}};
            end
        end
    end

    assign c = res;

endmodule

