module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

    reg [2:0] counter;
    reg a_sign, b_sign, z_sign;
    reg [7:0] a_exponent, b_exponent;
    reg [23:0] a_mantissa, b_mantissa;
    reg [9:0] a_exp_val, b_exp_val;
    reg [47:0] product;
    reg guard_bit, round_bit, sticky;
    reg [22:0] round_mantissa;
    reg [23:0] z_mantissa;
    reg [9:0] z_exp_val;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b0;
            z <= 32'b0;
            a_sign <= 0;
            b_sign <= 0;
            a_exponent <= 0;
            b_exponent <= 0;
            a_mantissa <= 0;
            b_mantissa <= 0;
            product <= 0;
            guard_bit <= 0;
            round_bit <= 0;
            sticky <= 0;
            z_mantissa <= 0;
            z_exp_val <= 0;
        end else begin
            case (counter)
                3'b000: begin 
                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= (a[30:23] == 8'b0) ? {1'b0, a[22:0]} : {1'b1, a[22:0]};
                    b_mantissa <= (b[30:23] == 8'b0) ? {1'b0, b[22:0]} : {1'b1, b[22:0]};
                    if (a_exponent == 8'hff || b_exponent == 8'hff) begin
                        z <= {a_sign ^ b_sign, 8'hff, 23'h0};
                        counter <= 3'b000;
                    end else begin
                        a_exp_val <= (a_exponent == 8'b0) ? -9'sd126 : (a_exponent - 9'sd127);
                        b_exp_val <= (b_exponent == 8'b0) ? -9'sd126 : (b_exponent - 9'sd127);
                        counter <= 3'b001;
                    end
                end
                3'b001: begin 
                    if (a_exponent == 8'h00 && b_exponent == 8'h00) begin
                        z <= {a_sign ^ b_sign, 31'h0};
                        counter <= 3'b000;
                    end else begin
                        product <= a_mantissa * b_mantissa;
                        counter <= 3'b010;
                    end
                end
                3'b010: begin 
                    integer i;
                    reg [47:0] norm_product;
                    reg [9:0] shift;
                    reg [4:0] leading;
                    leading = 47;
                    norm_product = product;
                    for (i = 47;
 i >= 0;
 i = i - 1) begin
                        if (norm_product[i]) begin
                            leading = i;
                            break;
                        end
                    end
                    shift = 47 - leading;
                    norm_product = product << shift;
                    z_exp_val <= a_exp_val + b_exp_val + shift;
                    z_mantissa <= norm_product[47:24];
                    guard_bit <= norm_product[23];
                    round_bit <= norm_product[22];
                    sticky <= |norm_product[21:0];
                    counter <= 3'b011;
                end
                3'b011: begin 
                    reg [23:0] incr_mantissa;
                    incr_mantissa = z_mantissa + 1;
                    if (guard_bit && (round_bit || sticky || z_mantissa[0])) begin
                        z_mantissa <= incr_mantissa;
                    end else if (guard_bit && !round_bit && !sticky && !z_mantissa[0]) begin
                        z_mantissa <= {z_mantissa[23], z_mantissa[22:1]};

                    end
                    if (incr_mantissa[23]) begin 
                        z_mantissa <= 24'h0;
                        z_exp_val <= z_exp_val + 1;
                    end
                    counter <= 3'b100;
                end
                3'b100: begin 
                    if (z_exp_val >= 255) begin 
                        z <= {z_sign, 8'hff, 23'h0};
                    end else if (z_exp_val < 0) begin 
                        z <= {z_sign, 31'h0};
                    end else begin
                        z <= {z_sign, z_exp_val[7:0], z_mantissa[22:0]};
                    end
                    counter <= 3'b000;
                end
                default: counter <= 3'b000;
            endcase
        end
    end

