        if (!RW) begin 
            if (SP != 3'b000) begin 
                stack_mem[SP-1] <= dataIn;
                SP <= SP - 1;
            end
        end
        else begin 
            if (SP != 3'b100) begin 
                dataOut <= stack_mem[SP-1];
                stack_mem[SP-1] <= 4'b0;

                SP <= SP + 1;
            end
        end
    end
end

assign EMPTY = (SP == 3'b100);
assign FULL = (SP == 3'b000);

endmodule

