module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

reg [1:0] state;
localparam IDLE = 2'b00;
localparam WAIT1 = 2'b01;
localparam WAIT0 = 2'b10;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        state <= IDLE;
        data_out <= 1'b0;
    end else begin
        case (state)
            IDLE: begin
                data_out <= 1'b0;
                if (data_in) begin
                    state <= WAIT1;
                end else begin
                    state <= IDLE;
                end
            end
            WAIT1: begin
                data_out <= 1'b0;
                if (data_in) begin
                    state <= WAIT1;
                end else begin
                    state <= WAIT0;
                end
            end
            WAIT0: begin
                data_out <= 1'b1;
                if (data_in) begin
                    state <= WAIT1;
                end else begin
                    state <= IDLE;
                end
            end
            default: begin
                state <= IDLE;
                data_out <= 1'b0;
            end
        endcase
    end
end

endmodule

