module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output reg [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);


parameter idle = 2'b00,
          s1_red = 2'b01,
          s2_yellow = 2'b10,
          s3_green = 2'b11;

reg [7:0] cnt;
reg [1:0] state, next_state;
reg p_red, p_yellow, p_green;


always @(*) begin
    case (state)
        idle: next_state = s1_red;
        s1_red: next_state = (cnt == 3) ? s3_green : s1_red;
        s2_yellow: next_state = (cnt == 3) ? s1_red : s2_yellow;
        s3_green: next_state = (cnt == 3) ? s2_yellow : s3_green;
        default: next_state = idle;
    endcase
end


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        cnt <= 8'd10;
    end else begin
        if (pass_request && green)
            cnt <= 8'd10;
        else if (!green && p_green)
            cnt <= 8'd60;
        else if (!yellow && p_yellow)
            cnt <= 8'd5;
        else if (!red && p_red)
            cnt <= 8'd10;
        else
            cnt <= cnt - 1;
    end
end


always @(posedge clk or negedge rst_n) begin
    if (!rst_n)
        state <= idle;
    else
        state <= next_state;
end


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        p_red <= 0;
        p_yellow <= 0;
        p_green <= 0;
    end else begin
        p_red <= red;
        p_yellow <= yellow;
        p_green <= green;
    end
end


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        red <= 0;
        yellow <= 0;
        green <= 0;
    end else begin
        red <= p_red;
        yellow <= p_yellow;
        green <= p_green;
    end
end

assign clock = cnt;

