module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

reg [7:0] saved_dividend_abs;
reg [7:0] saved_divisor_abs;
reg [7:0] NEG_DIVISOR;
reg [15:0] SR;
reg [3:0] cnt;
reg state;
reg [15:0] remainder_quotient;

localparam IDLE = 1'b0;
localparam DIVIDE = 1'b1;

always @(posedge clk) begin
    if (rst) begin
        state <= IDLE;
        res_valid <= 1'b0;
        result <= 16'b0;
        SR <= 16'b0;
        cnt <= 4'b0;
        saved_dividend_abs <= 8'b0;
        saved_divisor_abs <= 8'b0;
        NEG_DIVISOR <= 8'b0;
    end else begin
        case (state)
            IDLE: begin
                if (opn_valid && !res_valid) begin

                    saved_dividend_abs <= sign & dividend[7] ? -dividend : dividend;
                    saved_divisor_abs <= sign & divisor[7] ? -divisor : divisor;
                    NEG_DIVISOR <= -(sign & divisor[7] ? -divisor : divisor);

                    SR <= {saved_dividend_abs, 1'b0} << 1;

                    cnt <= 4'd1;
                    state <= DIVIDE;
                    res_valid <= 1'b0;
                end
            end
            DIVIDE: begin
                if (cnt == 4'd8) begin

                    if (sign) begin
                        reg [7:0] final_q = (saved_dividend_abs[7] ^ saved_divisor_abs[7]) ? -SR[7:0] : SR[7:0];
                        reg [7:0] final_r = saved_dividend_abs[7] ? -SR[15:8] : SR[15:8];
                        result <= {final_r, final_q};
                    end else begin
                        result <= {SR[15:8], SR[7:0]};
                    end
                    res_valid <= 1'b1;
                    state <= IDLE;
                end else begin

                    reg [8:0] sub_res;
                    sub_res = {1'b0, SR[15:8]} - NEG_DIVISOR;
                    if (sub_res[8] == 1'b0) begin 
                        SR <= {sub_res[7:0], SR[7:1], 1'b1};
                    end else begin
                        SR <= {SR[15:8], SR[7:1], 1'b0};
                    end
                    cnt <= cnt + 1;
                end
            end
        endcase
    end
end

endmodule

