 i <= 16;
 i = i + 1) begin : cla_loop
    assign P_bit[i] = A[i] ^ B[i];
    assign G_bit[i] = A[i] & B[i];
    assign C[i+1] = G_bit[i] | (P_bit[i] & C[i]);
