    reg a_sign, b_sign, z_sign;
    reg [7:0] a_exponent, b_exponent, z_exponent;
    reg [22:0] a_mantissa, b_mantissa;
    reg [47:0] product;
    reg [23:0] a_man, b_man, z_mantissa;
    reg guard, round, sticky;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b0;
            z <= 32'b0;
            a_sign <= 1'b0;
            b_sign <= 1'b0;
            a_exponent <= 8'b0;
            b_exponent <= 8'b0;
            a_mantissa <= 23'b0;
            b_mantissa <= 23'b0;
            product <= 48'b0;
            z_sign <= 1'b0;
            z_exponent <= 9'b0;
            a_man <= 24'b0;
            b_man <= 24'b0;
