            guard <= 1'b0;
            round <= 1'b0;
            sticky <= 1'b0;
        end else begin
            case (counter)
                3'b000: begin 
                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= a[22:0];
                    b_mantissa <= b[22:0];
                    a_man <= {1'b1, a_mantissa};
                    b_man <= {1'b1, b_mantissa};
                    counter <= 3'b001;
