                3'b001: begin 
                    if ((a_exponent == 8'hff && |a_mantissa) || 
                        (b_exponent == 8'hff && |b_mantissa)) begin
                        z <= 32'h7fc00000;

                        counter <= 3'b111;
                    end else if ((a_exponent == 8'hff) || (b_exponent == 8'hff)) begin 
                        z_sign <= a_sign ^ b_sign;
                        z_exponent <= (a_exponent == 8'hff) ? 9'h1ff : 9'h1fe;
                        z_mantissa <= 24'b0;
                        counter <= 3'b111;
                    end else if (a_exponent == 0 && b_exponent == 0 && a_mantissa == 0 && b_mantissa == 0) begin 
                        z_sign <= a_sign ^ b_sign;
                        z_exponent <= 9'b0;
                        z_mantissa <= 24'b0;
                        counter <= 3'b111;
                    end else begin
                        product <= a_man * b_man;
                        z_sign <= a_sign ^ b_sign;
                        z_exponent <= a_exponent + b_exponent - 8'd127;
                        counter <= 3'b010;
                    end
