                3'b010: begin 
                    if (product == 48'b0) begin 
                        z <= {z_sign, 8'b0, 23'b0};
                        counter <= 3'b111;
                    end else begin

                        integer i;
                        reg found;
                        found = 0;
                        for (i = 47;
 i >= 0;
 i = i - 1) begin
                            if (product[i] && !found) begin
                                found = 1;
                            end
                        end
                        if (i == 47) begin 
                            product <= product >> 1;
                            z_exponent <= z_exponent + 1;
                        end else begin
                            product <= product << (47 - i);
                        end
                        counter <= 3'b011;
                    end
                end

                3'b011: begin 

                    {guard, round, sticky} = {product[0], product[1], |product[48:2]};
                    z_mantissa = {1'b1, product[46:24]};

                    if (round && (guard ^ sticky)) begin
                        if (z_mantissa[0]) z_mantissa = z_mantissa + 1;
                    end
                    if (z_mantissa[23]) begin 
                        z_mantissa = z_mantissa >> 1;
                        z_exponent = z_exponent + 1;
                    end
                    counter <= 3'b100;
                end

                3'b100: begin 
                    if (z_exponent[8]) begin 
                        z <= 32'h7fc00000;

                    end else if (z_exponent == 0) begin 
                        z <= 32'h00000000;

                    end else begin
                        z <= {z_sign, z_exponent[7:0], z_mantissa[22:0]};
                    end
                    counter <= 3'b000;
                end

                default: counter <= 3'b000;
            endcase
        end
    end

