module asyn_fifo #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input  wire             wclk,
    input  wire             rclk,
    input  wire             wrstn,
    input  wire             rrstn,
    input  wire             winc,
    input  wire             rinc,
    input  wire [WIDTH-1:0] wdata,
    output wire             wfull,
    output wire             rempty,
    output wire [WIDTH-1:0] rdata
);

localparam ADDR_WIDTH = $clog2(DEPTH);
localparam PTR_WIDTH = ADDR_WIDTH + 1;


dual_port_RAM #(
    .WIDTH(WIDTH),
    .DEPTH(DEPTH)
) ram (
    .wclk(wclk),
    .wenc(winc && !wfull),
    .waddr(wptr_bin[ADDR_WIDTH-1:0]),
    .wdata(wdata),
    .rclk(rclk),
    .renc(rinc && !rempty),
    .raddr(rptr_bin[ADDR_WIDTH-1:0]),
    .rdata(rdata)
);


reg [PTR_WIDTH-1:0] wptr_bin = 0;
reg [PTR_WIDTH-1:0] wptr_gray;

function [PTR_WIDTH-1:0] bin2gray(input [PTR_WIDTH-1:0] bin);
    bin2gray = bin ^ (bin >> 1);
endfunction

always @(posedge wclk) begin
    if (!wrstn) begin
        wptr_bin <= 0;
        wptr_gray <= 0;
    end else begin
        if (winc && !wfull) begin
            wptr_bin <= wptr_bin + 1;
            wptr_gray <= bin2gray(wptr_bin + 1);
        end else begin
            wptr_gray <= bin2gray(wptr_bin);
        end
    end
end


reg [PTR_WIDTH-1:0] rptr_bin = 0;
reg [PTR_WIDTH-1:0] rptr_gray;

always @(posedge rclk) begin
    if (!rrstn) begin
        rptr_bin <= 0;
        rptr_gray <= 0;
    end else begin
        if (rinc && !rempty) begin
            rptr_bin <= rptr_bin + 1;
            rptr_gray <= bin2gray(rptr_bin + 1);
        end else begin
            rptr_gray <= bin2gray(rptr_bin);
        end
    end
end


reg [PTR_WIDTH-1:0] rptr_gray_sync1, rptr_gray_sync2;

always @(posedge wclk) begin
    if (!wrstn) begin
        rptr_gray_sync1 <= 0;
        rptr_gray_sync2 <= 0;
    end else begin
        rptr_gray_sync1 <= rptr_gray;
        rptr_gray_sync2 <= rptr_gray_sync1;
    end
end


reg [PTR_WIDTH-1:0] wptr_gray_sync1, wptr_gray_sync2;

always @(posedge rclk) begin
    if (!rrstn) begin
        wptr_gray_sync1 <= 0;
        wptr_gray_sync2 <= 0;
    end else begin
        wptr_gray_sync1 <= wptr_gray;
        wptr_gray_sync2 <= wptr_gray_sync1;
    end
end


function [PTR_WIDTH-1:0] gray2bin(input [PTR_WIDTH-1:0] gray);
    reg [PTR_WIDTH-1:0] bin;
    integer i;
    begin
        bin[PTR_WIDTH-1] = gray[PTR_WIDTH-1];
        for (i = PTR_WIDTH-2;
 i >= 0;
 i = i - 1)
            bin[i] = bin[i+1] ^ gray[i];
        gray2bin = bin;
    end
endfunction

wire [PTR_WIDTH-1:0] rptr_bin_sync = gray2bin(rptr_gray_sync2);
wire [PTR_WIDTH-1:0] wptr_bin_sync = gray2bin(wptr_gray_sync2);


wire [PTR_WIDTH-1:0] next_rptr_bin = rptr_bin_sync + DEPTH;
wire [PTR_WIDTH-1:0] next_rptr_gray = bin2gray(next_rptr_bin);

assign rempty = (rptr_gray_sync2 == wptr_gray);
assign wfull = (wptr_gray == next_rptr_gray);

endmodule

