module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output reg [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);

    localparam [1:0] idle = 2'b00;
    localparam [1:0] s1_red = 2'b01;
    localparam [1:0] s2_yellow = 2'b10;
    localparam [1:0] s3_green = 2'b11;

    reg [1:0] state;
    reg [7:0] cnt;
    reg p_red, p_yellow, p_green;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
        end else begin
            case (state)
                idle: state <= s1_red;
                s1_red: if (cnt == 0) state <= s3_green;
                s3_green: if (cnt == 0) state <= s2_yellow;
                s2_yellow: if (cnt == 0) state <= s1_red;
                default: state <= idle;
            endcase
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 10;
        end else begin

            if (state == s3_green && pass_request) begin
                if (cnt > 10)
                    cnt <= 10;
                else
                    cnt <= cnt;
            end

            case (state)
                s1_red: cnt <= (pass_request && cnt > 10) ? 10 : (cnt == 0) ? 10 : cnt - 1;
                s3_green: cnt <= (pass_request && cnt > 10) ? 10 : (cnt == 0) ? 60 : cnt - 1;
                s2_yellow: cnt <= (pass_request && cnt > 10) ? 10 : (cnt == 0) ? 5 : cnt - 1;
                default: cnt <= (cnt == 0) ? (state == s3_green ? 60 : 
                    (state == s2_yellow ? 5 : 10)) : cnt - 1;
            endcase
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            red <= 0;
            yellow <= 0;
            green <= 0;
            p_red <= 0;
            p_yellow <= 0;
            p_green <= 0;
        end else begin
            {p_red, p_yellow, p_green} <= {red, yellow, green};
            case (state)
                s1_red: {red, yellow, green} <= 3'b100;
                s2_yellow: {red, yellow, green} <= 3'b010;
                s3_green: {red, yellow, green} <= 3'b001;
                default: {red, yellow, green} <= 3'b000;
            endcase
        end
    end

    assign clock = cnt;

endmodule

