module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

reg [7:0] dividend_abs, divisor_abs;
reg sign_dividend, sign_divisor;
reg [16:0] sr_reg;
reg [3:0] cnt;
reg start_cnt;
reg [7:0] quotient;
reg [7:0] remainder;
reg [1:0] state;

localparam IDLE = 2'b00;
localparam DIVIDING = 2'b01;
localparam DONE = 2'b10;

always @(posedge clk) begin
    if (rst) begin
        res_valid <= 0;
        result <= 0;
        state <= IDLE;
        cnt <= 0;
        start_cnt <= 0;
        dividend_abs <= 0;
        divisor_abs <= 0;
        sign_dividend <= 0;
        sign_divisor <= 0;
        sr_reg <= 0;
        quotient <= 0;
        remainder <= 0;
    end else begin
        case (state)
            IDLE: begin
                if (opn_valid && !res_valid) begin

                    if (sign) begin
                        sign_dividend <= dividend[7];
                        sign_divisor <= divisor[7];
                        dividend_abs <= dividend[7] ? (~dividend + 1) : dividend;
                        divisor_abs <= divisor[7] ? (~divisor + 1) : divisor;
                    end else begin
                        sign_dividend <= 0;
                        sign_divisor <= 0;
                        dividend_abs <= dividend;
                        divisor_abs <= divisor;
                    end

                    sr_reg <= {9'b0, dividend_abs, 1'b0} << 1;
                    cnt <= 1;
                    start_cnt <= 1;
                    state <= DIVIDING;
                end
            end

            DIVIDING: begin
                if (start_cnt && cnt <= 8) begin

                    reg [8:0] sub_result;
                    reg [7:0] new_remainder;
                    reg [15:0] new_quotient;

                    sub_result = sr_reg[16:8] - divisor_abs;
                    new_remainder = sub_result[8:1];
                    new_quotient = {sr_reg[7:0], (sub_result[8] == 0) ? 1'b1 : 1'b0};

                    if (sub_result[8] == 0) begin
                        sr_reg <= {new_remainder, sr_reg[7:1] << 1};
                    end else begin
                        sr_reg <= sr_reg;
                    end

                    cnt <= cnt + 1;
                end

                if (cnt == 8) begin
                    state <= DONE;
                    start_cnt <= 0;
                end
            end

            DONE: begin

                quotient <= sr_reg[7:0];
                remainder <= sr_reg[16:9] >> 1;


                if (sign) begin
                    quotient <= (sign_dividend == sign_divisor) ? quotient : -quotient;
                    remainder <= sign_dividend ? -remainder : remainder;
                end

                result <= {remainder, quotient};
                res_valid <= 1;
                state <= IDLE;
            end
        endcase
    end
end

endmodule

