module div_16bit(
    input [15:0] A,
    input [7:0] B,
    output reg [15:0] result,
    output reg [15:0] odd
);

reg [15:0] a_reg;
reg [7:0] b_reg;

always @* begin
    a_reg = A;
    b_reg = B;
end

always @* begin
    reg [15:0] quo = 0;
    reg [7:0] rem = 0;
    integer i;

    for (i = 15;
 i >= 0;
 i = i - 1) begin
        rem = {rem[6:0], a_reg[i]};
        if (rem >= b_reg) begin
            quo[i] = 1'b1;
            rem = rem - b_reg;
        end else begin
            quo[i] = 1'b0;
        end
    end

    result = quo;
    odd = {8'b0, rem};
end

endmodule

