module cla_16bit (
    input [16:1] A,
    input [16:1] B,
    input C_in,
    output [16:1] S,
    output P,
    output G
);

wire [16:1] P_i = A ^ B;
wire [16:1] G_i = A & B;

wire [17:1] C;
assign C[1] = C_in;

genvar i;
generate
    for (i = 1;
 i <= 16;
 i = i + 1) begin : cla_loop
        assign C[i+1] = G_i[i] | (P_i[i] & C[i]);
    end
endgenerate

assign S = P_i ^ C[16:1];

wire [16:1] p_chain;
wire [16:1] g_chain;

assign p_chain[1] = P_i[1];
assign g_chain[1] = G_i[1];

generate
    for (i = 2;
 i <= 16;
 i = i + 1) begin : chain_loop
        assign p_chain[i] = P_i[i] & p_chain[i-1];
        assign g_chain[i] = G_i[i] | (P_i[i] & g_chain[i-1]);
    end
endgenerate

assign P = p_chain[16];
assign G = g_chain[16];

endmodule

