module accu (
    input clk,
    input rst_n,
    input [7:0] data_in,
    input valid_in,
    output reg valid_out,
    output [9:0] data_out
);

    reg [7:0] buffer [0:3];
    reg [1:0] counter;
    reg [9:0] sum;

    wire [9:0] sum_comb = buffer[0] + buffer[1] + buffer[2] + data_in;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            counter <= 2'b00;
            sum <= 10'b0;
            valid_out <= 1'b0;
            buffer[0] <= 8'b0;
            buffer[1] <= 8'b0;
            buffer[2] <= 8'b0;
            buffer[3] <= 8'b0;
        end else begin
            valid_out <= 1'b0;
            if (valid_in) begin
                buffer[counter] <= data_in;
                counter <= counter + 1;
            end
            if (valid_in && (counter == 2'b11)) begin
                sum <= sum_comb;
                valid_out <= 1'b1;
                counter <= 2'b00;
            end
        end
    end

    assign data_out = sum;

endmodule

