module fixed_point_adder #(parameter Q, N) (
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);

    reg [N-1:0] res;

    always @(*) begin
        reg sign_a, sign_b;
        reg [N-1:0] abs_a, abs_b;
        reg [N-1:0] sum_abs, sub_abs;
        reg [N-1:0] temp_res;
        reg res_sign;

        sign_a = a[N-1];
        sign_b = b[N-1];
        abs_a = sign_a ? (~a + 1) : a;
        abs_b = sign_b ? (~b + 1) : b;

        if (sign_a == sign_b) begin

            sum_abs = abs_a + abs_b;
            res_sign = sign_a;

            if (sum_abs > ((1 << (N-1)) - 1)) begin
                temp_res = res_sign ? ((1 << (N-1)) - 1) : ((1 << (N-1)) - 1);
            end else begin
                temp_res = res_sign ? (~sum_abs + 1) : sum_abs;
            end
        end else begin

            if (abs_a > abs_b) begin
                sub_abs = abs_a - abs_b;
                res_sign = sign_a;
            end else if (abs_b > abs_a) begin
                sub_abs = abs_b - abs_a;
                res_sign = sign_b;
            end else begin
                sub_abs = 0;
                res_sign = 0;
            end
            temp_res = res_sign ? (~sub_abs + 1) : sub_abs;
        end

        res = temp_res;
    end

    assign c = res;

endmodule

