module fixed_point_subtractor #(
    parameter Q = 2,
    parameter N = 4
) (
    input  [N-1:0] a,
    input  [N-1:0] b,
    output reg [N-1:0] c
);

always @(*) begin
    reg sign_a = a[N-1];
    reg sign_b = b[N-1];
    reg [N-2:0] mag_a = a[N-2:0];
    reg [N-2:0] mag_b = b[N-2:0];
    reg [N-2:0] mag_diff = mag_a - mag_b;
    reg [N-2:0] res_mag;
    reg res_sign;

    if (sign_a == sign_b) begin
        if (mag_diff[N-2]) begin 
            res_sign = ~sign_a;
            res_mag = mag_b - mag_a;
        end else begin
            res_sign = sign_a;
            res_mag = mag_diff;
        end
    end else begin
        if (mag_a > mag_b) begin
            res_sign = 1'b0;
            res_mag = mag_a - mag_b;
        end else begin
            res_sign = 1'b1;
            res_mag = mag_b - mag_a;
        end
    end

    if (res_mag == 0)
        res_sign = 1'b0;

    c = {res_sign, res_mag};
end

endmodule

