module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

    reg [2:0] counter;
    reg [23:0] a_mantissa, b_mantissa;
    reg [23:0] z_mantissa;
    reg [9:0] a_exponent, b_exponent, z_exponent;
    reg a_sign, b_sign, z_sign;
    reg [48:0] product;

    reg guard_bit, round_bit, sticky;
    reg special_case;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b0;
            z <= 32'b0;
            special_case <= 0;
        end else begin
            case (counter)
                3'b000: begin

                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= {1'b1, a[22:0]};
                    b_mantissa <= {1'b1, b[22:0]};


                    if (a[30:23] == 8'hFF) begin
                        if (a[22:0] != 0) begin

                            z <= {1'b0, 8'hFF, 23'h1};
                        end else begin

                            z <= {a_sign ^ b_sign, 8'hFF, 23'h0};
                        end
                        special_case <= 1;
                    end else if (b[30:23] == 8'hFF) begin
                        if (b[22:0] != 0) begin
                            z <= {1'b0, 8'hFF, 23'h1};
                        end else begin
                            z <= {a_sign ^ b_sign, 8'hFF, 23'h0};
                        end
                        special_case <= 1;
                    end else if (a_exponent == 0) begin
                        if (b_exponent == 0) begin

                            z <= {a_sign ^ b_sign, 31'b0};
                        end else begin

                            z <= 32'b0;

                        end
                        special_case <= 1;
                    end else if (b_exponent == 0) begin

                        z <= 32'b0;

                        special_case <= 1;
                    end else begin
                        special_case <= 0;
                        product <= {1'b0, a_mantissa} * {1'b0, b_mantissa};
                        z_exponent <= a_exponent + b_exponent - 9'd127;
                        counter <= 3'b001;
                    end
                end

                3'b001: begin

                    if (product[48]) begin
                        product <= product >> 1;
                        z_exponent <= z_exponent + 1;
                    end

                    z_mantissa <= product[46:24];

                    guard_bit <= product[23];
                    round_bit <= product[22];
                    sticky <= |product[21:0];
                    counter <= 3'b010;
                end

                3'b010: begin

                    if (guard_bit && (round_bit || sticky)) begin
                        z_mantissa <= z_mantissa + 1;
                    end

                    if (z_mantissa[23]) begin
                        z_mantissa <= 24'h0;
                        z_exponent <= z_exponent + 1;
                    end

                    if (z_exponent >= 9'h1FF) begin
                        z <= {a_sign ^ b_sign, 8'hFF, 23'h0};

                    end else if (z_exponent <= 9'h001) begin
                        z <= {a_sign ^ b_sign, 31'b0};

                    end else begin
                        z <= {a_sign ^ b_sign, z_exponent[7:0], z_mantissa[22:0]};
                    end
                    counter <= 3'b0;
                end

                default: counter <= 3'b0;
            endcase
        end
    end

