module alu (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output reg [31:0] r,
    output zero,
    output reg carry,
    output negative,
    output reg overflow,
    output reg flag
);

    parameter ADD = 6'b100000;
    parameter ADDU = 6'b100001;
    parameter SUB = 6'b100010;
    parameter SUBU = 6'b100011;
    parameter AND = 6'b100100;
    parameter OR = 6'b100101;
    parameter XOR = 6'b100110;
    parameter NOR = 6'b100111;
    parameter SLT = 6'b101010;
    parameter SLTU = 6'b101011;
    parameter SLL = 6'b000000;
    parameter SRL = 6'b000010;
    parameter SRA = 6'b000011;
    parameter SLLV = 6'b000100;
    parameter SRLV = 6'b000110;
    parameter SRAV = 6'b000111;
    parameter LUI = 6'b001111;

    wire [32:0] add_sum, sub_diff, addu_sum, subu_diff;
    wire slt_flag, sltu_flag;
    wire [31:0] sll_res, srl_res, sra_res, sllv_res, srlv_res, sraw_res;

    assign add_sum = {1'b0, a} + {1'b0, b};
    assign sub_diff = {1'b0, a} - {1'b0, b};
    assign addu_sum = a + b;
    assign subu_diff = a - b;

    assign slt_flag = ($signed(a) < $signed(b));
    assign sltu_flag = (a < b);

    assign sll_res = a << b[4:0];
    assign srl_res = a >> b[4:0];
    assign sra_res = $signed(a) >>> b[4:0];
    assign sllv_res = b << a[4:0];
    assign srlv_res = b >> a[4:0];
    assign sraw_res = $signed(b) >>> a[4:0];

    always @(*) begin
        case (aluc)
            ADD: begin
                r = add_sum[31:0];
                carry = add_sum[32];
                overflow = ($signed(a) + $signed(b)) !== r;
            end
            ADDU: begin
                r = addu_sum;
                carry = addu_sum[32];
                overflow = 1'b0;
            end
            SUB: begin
                r = sub_diff[31:0];
                carry = (a >= b);
                overflow = (a[31] != b[31]) && (r[31] != a[31]);
            end
            SUBU: begin
                r = subu_diff;
                carry = (a >= b);
                overflow = 1'b0;
            end
            AND: begin
                r = a & b;
                carry = 1'b0;
                overflow = 1'b0;
            end
            OR: begin
                r = a | b;
                carry = 1'b0;
                overflow = 1'b0;
            end
            XOR: begin
                r = a ^ b;
                carry = 1'b0;
                overflow = 1'b0;
            end
            NOR: begin
                r = ~(a | b);
                carry = 1'b0;
                overflow = 1'b0;
            end
            SLT: begin
                r = slt_flag ? 32'd1 : 32'd0;
                carry = 1'b0;
                overflow = 1'b0;
            end
            SLTU: begin
                r = sltu_flag ? 32'd1 : 32'd0;
                carry = 1'b0;
                overflow = 1'b0;
            end
            SLL: begin
                r = sll_res;
                carry = 1'b0;
                overflow = 1'b0;
            end
            SRL: begin
                r = srl_res;
                carry = 1'b0;
                overflow = 1'b0;
            end
            SRA: begin
                r = sra_res;
                carry = 1'b0;
                overflow = 1'b0;
            end
            SLLV: begin
                r = sllv_res;
                carry = 1'b0;
                overflow = 1'b0;
            end
            SRLV: begin
                r = srlv_res;
                carry = 1'b0;
                overflow = 1'b0;
            end
            SRAV: begin
                r = sraw_res;
                carry = 1'b0;
                overflow = 1'b0;
            end
            LUI: begin
                r = {a[31:16], 16'b0};
                carry = 1'b0;
                overflow = 1'b0;
            end
            default: begin
                r = 32'bz;
                carry = 1'b0;
                overflow = 1'b0;
            end
        endcase
    end

    assign zero = (r == 32'b0);
    assign negative = r[31];
    assign flag = (aluc == SLT || aluc == SLTU) ? r[0] : 1'bz;

endmodule

