module div_16bit (
    input [15:0] A,
    input [7:0] B,
    output reg [15:0] result,
    output reg [15:0] odd
);

    reg [15:0] a_reg;
    reg [7:0] b_reg;

    always @* begin
        a_reg = A;
        b_reg = B;
    end

    reg [15:0] remainder;
    reg [15:0] quotient;
    reg [15:0] temp_dividend;

    always @* begin
        remainder = 16'b0;
        quotient = 16'b0;
        temp_dividend = a_reg;

        for (int i = 15;
 i >= 0;
 i = i - 1) begin
            remainder = (remainder << 1) | ((temp_dividend >> i) & 1);
            if (remainder >= {8'b0, b_reg}) begin
                remainder = remainder - {8'b0, b_reg};
                quotient[i] = 1'b1;
            end else begin
                quotient[i] = 1'b0;
            end
        end

        result = quotient;
        odd = remainder;
    end

endmodule

