module cla_4bit (
    input [4:1] A,
    input [4:1] B,
    input c_in,
    output [4:1] S,
    output G,
    output P
);
    wire [4:1] G_i, P_i;

    assign G_i = A & B;
    assign P_i = A | B;

    assign G = G_i[4] | (P_i[4] & G_i[3]) | (P_i[4] & P_i[3] & G_i[2]) | (P_i[4] & P_i[3] & P_i[2] & G_i[1]);
    assign P = P_i[4] & P_i[3] & P_i[2] & P_i[1];

    assign S[1] = A[1] ^ B[1] ^ c_in;
    assign S[2] = A[2] ^ B[2] ^ (G_i[1] | (P_i[1] & c_in));
    assign S[3] = A[3] ^ B[3] ^ (G_i[2] | (P_i[2] & G_i[1]) | (P_i[2] & P_i[1] & c_in));
    assign S[4] = A[4] ^ B[4] ^ (G_i[3] | (P_i[3] & G_i[2]) | (P_i[3] & P_i[2] & G_i[1]) | (P_i[3] & P_i[2] & P_i[1] & c_in));

