module fixed_point_subtractor #(
    parameter Q = 2,
    parameter N = 8
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c
);

wire [N-1:0] magnitude_a = a[N-1] ? (~a + 1) : a;
wire [N-1:0] magnitude_b = b[N-1] ? (~b + 1) : b;
wire [N-1:0] sum_mag = magnitude_a + magnitude_b;
wire [N-1:0] a_minus_b = a - b;

always @(*) begin
    if (a[N-1] == b[N-1]) begin
        c = a_minus_b;
        if (c == 0)
            c[N-1] = 1'b0;
    end else begin
        if (sum_mag == 0)
            c = 0;
        else if (magnitude_a > magnitude_b)
            c = {1'b0, sum_mag[N-1:Q], sum_mag[Q-1:0]};
        else
            c = {1'b1, sum_mag[N-1:Q], sum_mag[Q-1:0]};
    end
end

endmodule

