module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

    reg [2:0] counter;
    reg a_sign, b_sign, z_sign;
    reg [7:0] a_exponent, b_exponent, z_exponent;
    reg [23:0] a_mantissa, b_mantissa, z_mantissa;
    reg [47:0] product;
    reg guard_bit, round_bit, sticky;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b0;
            z <= 32'd0;
        end else begin
            case (counter)
                3'b000: begin

                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= (a[30:23] == 8'd0) ? {1'b0, a[22:0]} : {1'b1, a[22:0]};
                    b_mantissa <= (b[30:23] == 8'd0) ? {1'b0, b[22:0]} : {1'b1, b[22:0]};
                    counter <= counter + 1;
                end
                3'b001: begin

                    product <= a_mantissa * b_mantissa;
                    counter <= counter + 1;
                end
                3'b010: begin

                    integer i;
                    reg [5:0] leading_one_pos;
                    leading_one_pos = 6'd47;
                    for (i = 47;
 i >= 0;
 i = i - 1) begin
                        if (product[i]) begin
                            leading_one_pos = i;
                            i = -1;

                        end
                    end

                    reg [5:0] shift_amount;
                    shift_amount = 6'd47 - leading_one_pos;

                    z_mantissa <= product >> (shift_amount + 1);
                    z_exponent <= a_exponent + b_exponent - 8'd127 + shift_amount;
                    counter <= counter + 1;
                end
                3'b011: begin


                    reg [22:0] rounded_mantissa;
                    reg rounding_increment;
                    reg [23:0] normalized_mantissa = z_mantissa;

                    guard_bit = (z_mantissa >> 23) & 1;
                    round_bit = (z_mantissa >> 22) & 1;
                    sticky = |(z_mantissa >> 21);

                    if (guard_bit) begin
                        if (round_bit || sticky || (normalized_mantissa[0])) begin
                            rounding_increment = 1;
                        end else begin
                            rounding_increment = 0;
                        end
                    end else begin
                        rounding_increment = 0;
                    end

                    rounded_mantissa = normalized_mantissa[22:0] + rounding_increment;
                    if (rounded_mantissa[23]) begin 
                        rounded_mantissa = 23'd0;
                        z_exponent <= z_exponent + 1;
                    end
                    z_mantissa <= rounded_mantissa;
                    counter <= counter + 1;
                end
                3'b100: begin

                    if (z_exponent >= 8'd255) begin 
                        z <= {a_sign ^ b_sign, 8'hFF, 23'd0};
                    end else if (z_exponent == 8'd0 && z_mantissa != 23'd0) begin 
                        z <= {a_sign ^ b_sign, 8'd0, z_mantissa};
                    end else begin 
                        z <= {a_sign ^ b_sign, z_exponent, z_mantissa};
                    end
                    counter <= 3'b000;
                end
                default: counter <= 3'b000;
            endcase
        end
    end

endmodule

