module fsm (
    input CLK,
    input RST,
    input IN,
    output reg MATCH
);

reg [2:0] state, next_state;

parameter S0 = 3'b000,
          S1 = 3'b001,
          S2 = 3'b010,
          S3 = 3'b011,
          S4 = 3'b100;

always @(posedge CLK or posedge RST) begin
    if (RST) begin
        state <= S0;
    end else begin
        state <= next_state;
    end
end

always @(*) begin
    case (state)
        S0: next_state = IN ? S1 : S0;
        S1: next_state = IN ? S0 : S2;
        S2: next_state = (IN == 0) ? S3 : S0;
        S3: next_state = (IN == 1) ? S4 : S0;
        S4: next_state = (IN == 1) ? S1 : S0;
        default: next_state = S0;
    endcase
end

always @(*) begin
    MATCH = 0;
    if (state == S4 && IN == 1)
        MATCH = 1;
end

endmodule

