    output wfull,
    output rempty,
    output [WIDTH-1:0] rdata
);

reg [$clog2(DEPTH)-1:0] waddr_bin, raddr_bin;
wire [3:0] wptr_gray = (waddr_bin >> 1) ^ waddr_bin;
wire [3:0] rptr_gray = (raddr_bin >> 1) ^ raddr_bin;

reg [3:0] rptr_gray_sync1, rptr_gray_sync2;
always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        rptr_gray_sync1 <= 4'b0;
        rptr_gray_sync2 <= 4'b0;
    end else begin
        rptr_gray_sync1 <= rptr_gray;
        rptr_gray_sync2 <= rptr_gray_sync1;
    end
end

reg [3:0] wptr_gray_sync1, wptr_gray_sync2;
always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        wptr_gray_sync1 <= 4'b0;
