module LIFObuffer (
    input wire [3:0] dataIn,
    input wire RW,
    input wire EN,
    input wire Rst,
    input wire Clk,
    output wire EMPTY,
    output wire FULL,
    output reg [3:0] dataOut
);

reg [2:0] SP;

reg [3:0] stack_mem [0:3];


assign EMPTY = (SP == 4);
assign FULL = (SP == 0);

always @(posedge Clk) begin
    if (EN) begin
        if (Rst) begin
            SP <= 3'b100;

            stack_mem[0] <= 4'b0;
            stack_mem[1] <= 4'b0;
            stack_mem[2] <= 4'b0;
            stack_mem[3] <= 4'b0;
        end else begin
            if (!FULL && RW == 0) begin 
                stack_mem[SP-1] <= dataIn;
                SP <= SP - 1;
            end else if (!EMPTY && RW == 1) begin 
                dataOut <= stack_mem[SP-1];
                SP <= SP + 1;
            end
        end
    end
end

endmodule

