module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

    localparam S0 = 2'b00;
    localparam S1 = 2'b01;
    localparam S2 = 2'b10;

    reg [1:0] state_reg, next_state;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state_reg <= S0;
        end else begin
            state_reg <= next_state;
        end
    end


    always @(*) begin
        case (state_reg)
            S0: next_state = data_in ? S1 : S0;
            S1: next_state = data_in ? S1 : S2;
            S2: next_state = S0;
            default: next_state = S0;
        endcase
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            data_out <= 1'b0;
        end else begin
            data_out <= (state_reg == S2) && (data_in == 1'b0);
        end
    end

endmodule

