module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

reg [15:0] SR;
reg [7:0] abs_dividend, abs_divisor;
reg sign_dividend, sign_divisor;
reg [3:0] cnt;
reg start_cnt;

wire [7:0] remainder = SR[15:8];
wire [7:0] quotient = SR[7:0];
wire [7:0] NEG_DIVISOR = sign_divisor ? (-abs_divisor) : abs_divisor;

always @(posedge clk) begin
    if (rst) begin
        res_valid <= 0;
        SR <= 16'b0;
        cnt <= 0;
        start_cnt <= 0;
        sign_dividend <= 0;
        sign_divisor <= 0;
    end else begin
        res_valid <= 0;
        if (opn_valid && !res_valid) begin
            sign_dividend <= sign ? dividend[7] : 1'b0;
            sign_divisor <= sign ? divisor[7] : 1'b0;
            abs_dividend <= sign ? (dividend[7] ? -dividend : dividend) : dividend;
            abs_divisor <= sign ? (divisor[7] ? -divisor : divisor) : divisor;
            SR <= {abs_dividend, 8'b0} << 1;
            cnt <= 0;
            start_cnt <= 1;
        end else if (start_cnt) begin
            if (cnt == 8) begin
                start_cnt <= 0;
                res_valid <= 1;
            end else begin
                wire [8:0] sub_result = SR[15:8] + NEG_DIVISOR;
                wire carry = sub_result[8];
                reg [15:0] new_SR = SR << 1;
                new_SR[0] = carry;
                SR <= new_SR;
                cnt <= cnt + 1;
            end
        end
    end
end


always @(posedge clk) begin
    if (start_cnt == 0 && cnt == 8) begin
        reg [7:0] final_remainder, final_quotient;
        final_remainder = sign_dividend ? -remainder : remainder;
        final_quotient = (sign_dividend ^ sign_divisor) ? -quotient : quotient;
        result <= {final_remainder, final_quotient};
    end
end

endmodule

