module div_16bit (
    input [15:0] A,
    input [7:0] B,
    output reg [15:0] result,
    output reg [15:0] odd
);

    reg [15:0] a_reg, b_reg;
    integer i;

    always @(*) begin
        a_reg = A;
        b_reg = B;
    end

    always @(*) begin
        reg [15:0] quotient;
        reg [15:0] remainder;
        quotient = 16'b0;
        remainder = 16'b0;
        for (i = 0;
 i < 16;
 i = i + 1) begin

            remainder = {remainder[14:0], a_reg[15 - i]};
            if (remainder[15:8] >= b_reg) begin
                quotient[15 - i] = 1'b1;
                remainder[15:8] = remainder[15:8] - b_reg;
            end else begin
                quotient[15 - i] = 1'b0;
            end
        end
        result = quotient;
        odd = remainder;
    end

endmodule

