module multi_8bit (
    input [7:0] A,
    input [7:0] B,
    output [15:0] product
);

    wire [15:0] A_extended = {8'b0, A};

    reg [15:0] sum;
    integer i;

    always @(*) begin
        sum = 16'b0;
        for (i = 0;
 i < 8;
 i = i + 1) begin
            sum = sum + (B[i] ? (A_extended << i) : 16'b0);
        end
    end

    assign product = sum;

