module fixed_point_adder #(
    parameter Q = 4,
    parameter N = 8
)(
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);

reg [N-1:0] res;
wire sign_a = a[N-1];
wire sign_b = b[N-1];
wire [N-2:0] mag_a = a[N-2:0];
wire [N-2:0] mag_b = b[N-2:0];

always @(*) begin
    if (sign_a == sign_b) begin
        wire [N-1:0] sum_mag = mag_a + mag_b;
        if (sum_mag >= (2 ** (N-1))) begin
            res = {1'b1, sum_mag[N-1:0]};
        end else begin
            res = {sign_a, sum_mag[N-1:0]};
        end
    end else begin
        if (mag_a > mag_b) begin
            res = {sign_a, mag_a - mag_b};
        end else if (mag_b > mag_a) begin
            res = {sign_b, mag_b - mag_a};
        end else begin
            res = {1'b0, {(N-2){1'b0}}};
        end
    end
end

assign c = res;

endmodule

