module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

    reg [2:0] counter;
    reg a_sign, b_sign, z_sign;
    reg [9:0] a_exponent, b_exponent, z_exponent;
    reg [23:0] a_mantissa, b_mantissa;
    reg [47:0] product;
    reg guard_bit, round_bit, sticky;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b0;
            z <= 32'd0;
        end else begin
            case (counter)
                3'd0: begin

                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= (|a[30:23]) ? {1'b1, a[22:0]} : {1'b0, a[22:0]};
                    b_mantissa <= (|b[30:23]) ? {1'b1, b[22:0]} : {1'b0, b[22:0]};
                    z_sign <= a_sign ^ b_sign;
                    counter <= 3'd1;
                end
                3'd1: begin

                    product <= a_mantissa * b_mantissa;
                    counter <= 3'd2;
                end
                3'd2: begin

                    if (product[47]) begin

                        z_mantissa <= {1'b1, product[46:23]};
                        z_exponent <= a_exponent + b_exponent - 9'd127 + 9'd1;
                        guard_bit <= product[22];
                        round_bit <= product[21];
                        sticky <= |product[20:0];
                    end else begin
                        z_mantissa <= {1'b0, product[46:24]};
                        z_exponent <= a_exponent + b_exponent - 9'd127;
                        guard_bit <= product[23];
                        round_bit <= product[22];
                        sticky <= |product[21:0];
                    end
                    counter <= 3'd3;
                end
                3'd3: begin

                    reg overflow;
                    if (guard_bit && (round_bit || sticky)) begin
                        z_mantissa[22:0] <= z_mantissa[22:0] + 1;
                        overflow = z_mantissa[23];
                    end else begin
                        overflow = 1'b0;
                    end
                    if (overflow) begin
                        z_exponent <= z_exponent + 9'd1;
                    end
                    counter <= 3'd4;
                end
                3'd4: begin

                    if (z_exponent >= 9'd255) begin
                        z <= {z_sign, 8'hff, 23'd0};
                    end else if (z_exponent == 9'd0) begin
                        z <= {z_sign, 31'd0};
                    end else begin
                        z <= {z_sign, z_exponent[7:0], z_mantissa[22:0]};
                    end
                    counter <= 3'd0;
                end
                default: counter <= 3'd0;
            endcase
        end
    end

endmodule

