module fsm (
    input IN,
    input CLK,
    input RST,
    output MATCH
);

    reg [2:0] state, next_state;

    parameter S0 = 3'b000,
              S1 = 3'b001,
              S2 = 3'b010,
              S3 = 3'b011,
              S4 = 3'b100;


    always @(posedge CLK, posedge RST) begin
        if (RST)
            state <= S0;
        else
            state <= next_state;
    end


    always @(*) begin
        case (state)
            S0: next_state = IN ? S1 : S0;
            S1: next_state = IN ? S1 : S2;
            S2: next_state = IN ? S1 : S3;
            S3: next_state = IN ? S4 : S0;
            S4: next_state = IN ? S1 : S0;
            default: next_state = S0;
        endcase
    end


    assign MATCH = (RST) ? 1'b0 : (state == S4 && IN) ? 1'b1 : 1'b0;

endmodule

