module alu(
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output reg [31:0] r,
    output zero,
    output reg carry,
    output reg negative,
    output reg overflow,
    output flag
);



always @(*) begin
    case (aluc)
        ADD: begin
            r = a + b;
            carry = (a + b) >> 32;
            overflow = (a[31] == b[31]) && (r[31] != a[31]);
        end
        ADDU: begin
            r = a + b;
            carry = (a + b) >> 32;
            overflow = 0;
        end
        SUB: begin
            r = a - b;
            carry = (a >= b);
            overflow = (a[31] != b[31]) && (r[31] != a[31]);
        end
        SUBU: begin
            r = a - b;
            carry = (a >= b);
            overflow = 0;
        end
        AND: begin
            r = a & b;
            carry = 0;
            overflow = 0;
        end
        OR: begin
            r = a | b;
            carry = 0;
            overflow = 0;
        end
        XOR: begin
            r = a ^ b;
            carry = 0;
            overflow = 0;
        end
        NOR: begin
            r = ~(a | b);
            carry = 0;
            overflow = 0;
        end
        SLT: begin
            r = ($signed(a) < $signed(b)) ? 1 : 0;
            carry = 0;
            overflow = 0;
        end
        SLTU: begin
            r = (a < b) ? 1 : 0;
            carry = 0;
            overflow = 0;
        end
        SLL: r = b << a[4:0];
        SRL: r = b >> a[4:0];
        SRA: r = $signed(b) >>> a[4:0];
        SLLV: r = b << a[4:0];
        SRLV: r = b >> a[4:0];
        SRAV: r = $signed(b) >>> a[4:0];
        LUI: r = {a[31:16], 16'b0};

        default: begin
            r = 32'bz;
            carry = 0;
            overflow = 0;
        end
    endcase
end

assign zero = (r == 32'b0);
assign negative = r[31];
assign flag = (aluc == SLT || aluc == SLTU) ? 1'b1 : 1'bz;

endmodule

