reg dividend_sign, divisor_sign;
reg [8:0] SR;

reg [3:0] cnt;

reg start_cnt;
reg [7:0] quotient;
reg [8:0] neg_divisor;

wire [8:0] sub_result;
wire carry_out;

assign sub_result = SR - neg_divisor;
assign carry_out = ~sub_result[8];


always @(posedge clk) begin
    if (rst) begin
        res_valid <= 1'b0;
        SR <= 9'b0;
        cnt <= 4'b0;
        start_cnt <= 1'b0;
        quotient <= 8'b0;
        abs_dividend <= 8'b0;
        abs_divisor <= 8'b0;
        dividend_sign <= 1'b0;
        divisor_sign <= 1'b0;
        neg_divisor <= 9'b0;
        result <= 16'b0;
    end else begin
        if (opn_valid && !res_valid) begin

            dividend_sign <= sign ? dividend[7] : 1'b0;
            divisor_sign <= sign ? divisor[7] : 1'b0;
            abs_dividend <= sign ? (dividend[7] ? (~dividend + 1) : dividend) : dividend;
            abs_divisor <= sign ? (divisor[7] ? (~divisor + 1) : divisor) : divisor;
            neg_divisor <= {1'b1, ~abs_divisor + 1};

            SR <= {abs_dividend, 1'b0};

            cnt <= 4'd1;
            start_cnt <= 1'b1;
            res_valid <= 1'b0;
        end else if (start_cnt && cnt <= 8) begin
            if (cnt == 4'd8) begin

                SR <= sub_result;
                quotient <= {quotient[6:0], carry_out};
                cnt <= 4'd0;
                start_cnt <= 1'b0;

                if (sign) begin
                    if (dividend_sign ^ divisor_sign) begin
                        quotient <= ~quotient + 1;
                    end
                    if (dividend_sign) begin
                        remainder <= ~SR[8:1] + 1;
                    end else begin
                        remainder <= SR[8:1];
                    end
                end else begin
                    remainder <= SR[8:1];
                end
                result <= {remainder, quotient};
                res_valid <= 1'b1;
            end else begin

                SR <= sub_result;
                quotient <= {quotient[6:0], carry_out};
                cnt <= cnt + 1;
            end
        end

        if (opn_valid && res_valid) begin
            res_valid <= 1'b0;
        end
    end
end

endmodule

