reg [7:0] b_reg;


always @* begin
    a_reg = A;
    b_reg = B;
end


always @* begin
    reg [15:0] q;
    reg [15:0] rem;
    integer i;

    rem = 16'b0;
    q = 16'b0;
    for (i = 15;
 i >= 0;
 i = i - 1) begin
        rem = {rem[14:0], a_reg[i]};

        if (rem >= b_reg) begin
            rem = rem - b_reg;

            q[i] = 1'b1;

        end else begin
            q[i] = 1'b0;

        end
    end

    result = q;

    odd = rem;

end

endmodule

