            if (i == 6'd0) begin
                areg <= ain;
                breg <= bin;
            end else if (i > 6'd0 && i < 6'd17) begin
                if (areg[i-1]) begin
                    yout_r <= yout_r + (breg << (i-1));
                end
            end
        end else begin
            i <= 6'd0;
        end

        if (next_i == 6'd16) begin
            done_r <= 1'b1;
        end else if (next_i == 6'd17) begin
            done_r <= 1'b0;
        end else begin
            done_r <= done_r;
