module cla_4bit (
    input [3:0] A,
    input [3:0] B,
    input C_in,
    output [3:0] S,
    output G,
    output P,
    output C_out
);
    wire [3:0] G_bits, P_bits;
    wire [3:0] C;

    assign G_bits = A & B;
    assign P_bits = A ^ B;

    assign C[0] = G_bits[0] | (P_bits[0] & C_in);
    assign C[1] = G_bits[1] | (P_bits[1] & C[0]);
    assign C[2] = G_bits[2] | (P_bits[2] & C[1]);
    assign C[3] = G_bits[3] | (P_bits[3] & C[2]);

    assign S = P_bits ^ {C[3], C[2], C[1], C[0]};

    assign G = G_bits[3] | (G_bits[2] & P_bits[3]) | 
               (G_bits[1] & P_bits[3] & P_bits[2]) | 
               (G_bits[0] & P_bits[3] & P_bits[2] & P_bits[1]);
    assign P = &P_bits;

    assign C_out = G | (P & C_in);
endmodule

