module fixed_point_adder #(
    parameter Q = 8,
    parameter N = 16
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);

wire sign_a = a[N-1];
wire sign_b = b[N-1];
wire same_sign = (sign_a == sign_b);

wire [N-1:0] a_abs = sign_a ? (~a + 1) : a;
wire [N-1:0] b_abs = sign_b ? (~b + 1) : b;

wire [N-1:0] sum_abs = a_abs + b_abs;
wire [N-1:0] diff_abs = (a_abs > b_abs) ? (a_abs - b_abs) : (b_abs - a_abs);
wire sign_diff = (a_abs > b_abs) ? 1'b0 : 1'b1;

assign c = same_sign ? sum_abs : {{(N-1){1'b0}}, diff_abs[N-2:0]};
assign c[N-1] = same_sign ? sign_a : sign_diff;

endmodule

