module fixed_point_subtractor #(parameter Q=16, N=32) (
    input [N-1:0] a, b,
    output reg [N-1:0] c
);

wire sign_a = a[N-1];
wire sign_b = b[N-1];
wire [N-2:0] mag_a = a[N-2:0];
wire [N-2:0] mag_b = b[N-2:0];

reg [N-1:0] res;

always @(*) begin
    res = 0;
    if (sign_a == sign_b) begin

        if (mag_a >= mag_b) begin
            res = {sign_a, mag_a - mag_b};
        end else begin
            res = {~sign_a, mag_b - mag_a};
        end
    end else begin
        if (sign_a) begin 

            if (mag_a > mag_b) begin
                res = {1'b1, mag_a + mag_b};
            end else begin
                res = {1'b0, mag_a + mag_b};
            end
        end else begin 

            if (mag_a > mag_b) begin
                res = {1'b1, mag_a - mag_b};
            end else begin
                res = {1'b0, mag_b - mag_a};
            end
        end
    end

    if (res == 0) begin
        res = {1'b0, {(N-1){1'b0}}};
    end
end

assign c = res;

endmodule

