module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

    reg [2:0] counter;
    reg a_sign, b_sign, z_sign;
    reg [7:0] a_exponent, b_exponent, z_exponent;
    reg [22:0] a_mantissa, b_mantissa;
    reg [47:0] product;
    reg guard, round, sticky;
    reg [8:0] z_exponent_reg;
    reg [23:0] a_mantissa_reg, b_mantissa_reg;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b0;
            z <= 32'd0;
            a_sign <= 1'b0;
            b_sign <= 1'b0;
            z_sign <= 1'b0;
            a_exponent <= 8'd0;
            b_exponent <= 8'd0;
            z_exponent <= 8'd0;
            a_mantissa <= 23'd0;
            b_mantissa <= 23'd0;
            product <= 48'd0;
            guard <= 1'b0;
            round <= 1'b0;
            sticky <= 1'b0;
            z_exponent_reg <= 9'd0;
            a_mantissa_reg <= 24'd0;
            b_mantissa_reg <= 24'd0;
        end else begin
            case (counter)
                3'b000: begin

                    a_sign <= a[31];
                    a_exponent <= a[30:23];
                    a_mantissa <= a[22:0];
                    b_sign <= b[31];
                    b_exponent <= b[30:23];
                    b_mantissa <= b[22:0];


                    if (a[30:23] == 8'hff) begin

                        if (a[22:0] != 0) begin
                            z <= 32'h7fc00000;

                        end else begin
                            if (b[30:23] == 8'hff) begin
                                if (b[22:0] != 0) begin
                                    z <= 32'h7fc00000;

                                end else begin
                                    z <= 32'h7fc00000;

                                end
                            end else begin
                                z_sign <= a_sign ^ b_sign;
                                z_exponent <= 8'hff;
                                z <= {z_sign, 8'hff, 23'd0};
                            end
                        end
                        counter <= 3'b001;
                    end else if (b[30:23] == 8'hff) begin

                        if (b[22:0] != 0) begin
                            z <= 32'h7fc00000;

                        end else begin
                            if (a[30:23] == 8'hff) begin
                                if (a[22:0] != 0) begin
                                    z <= 32'h7fc00000;

                                end else begin
                                    z <= 32'h7fc00000;

                                end
                            end else begin
                                z_sign <= a_sign ^ b_sign;
                                z_exponent <= 8'hff;
                                z <= {z_sign, 8'hff, 23'd0};
                            end
                        end
                        counter <= 3'b001;
                    end else begin

                        z_sign <= a_sign ^ b_sign;
                        a_mantissa_reg <= (a_exponent != 0) ? {1'b1, a_mantissa} : {1'b0, a_mantissa};
                        b_mantissa_reg <= (b_exponent != 0) ? {1'b1, b_mantissa} : {1'b0, b_mantissa};
                        z_exponent_reg <= {1'b0, a_exponent} + {1'b0, b_exponent} - 9'd127;
                        counter <= 3'b001;
                    end
                end

                3'b001: begin

                    product <= a_mantissa_reg * b_mantissa_reg;
                    counter <= 3'b010;
                end

                3'b010: begin

                    if (product[47]) begin
                        product <= product >> 1;
                        z_exponent_reg <= z_exponent_reg + 1;
                    end
                    guard <= product[22];
                    round <= product[21];
                    sticky <= |product[20:0];
                    counter <= 3'b011;
                end

                3'b011: begin

                    if (guard && (round || sticky || (product[23] && guard))) begin
                        product[47:24] <= product[47:24] + 1;
                    end
                    if (product[47:24] == 24'h1000000) begin
                        product[47:24] <= 24'h0;
                        z_exponent_reg <= z_exponent_reg + 1;
                    end
                    counter <= 3'b100;
                end

                3'b100: begin

                    if (z_exponent_reg >= 9'd255) begin
                        z <= {z_sign, 8'hff, 23'd0};
                    end else if (z_exponent_reg == 0) begin
                        z <= {z_sign, 31'd0};
                    end else begin
                        z <= {z_sign, z_exponent_reg[7:0], product[46:24]};
                    end
                    counter <= 3'b000;
                end

                default: counter <= 3'b000;
            endcase
        end
    end

endmodule

