module dual_port_RAM #(
    parameter DEPTH = 16,
    parameter WIDTH = 8
)(
    input wclk,
    input wenc,
    input [$clog2(DEPTH)-1:0] waddr,
    input [WIDTH-1:0] wdata,
    input rclk,
    input renc,
    input [$clog2(DEPTH)-1:0] raddr,
    output reg [WIDTH-1:0] rdata
);

    reg [WIDTH-1:0] RAM_MEM [0:DEPTH-1];

    always @(posedge wclk) begin
        if (wenc)
            RAM_MEM[waddr] <= wdata;
    end

    always @(posedge rclk) begin
        if (renc)
            rdata <= RAM_MEM[raddr];
    end

endmodule

module asyn_fifo #(
    parameter DEPTH = 16,
    parameter WIDTH = 8
)(
    input wclk,
    input wrstn,
    input winc,
    input [WIDTH-1:0] wdata,
    input rclk,
    input rrstn,
    input rinc,
    output wfull,
    output rempty,
    output [WIDTH-1:0] rdata
);

    wire [3:0] wptr_bin, rptr_bin;
    reg [3:0] wptr_bin_reg, rptr_bin_reg;

    wire [3:0] wptr_gray, rptr_gray;
    reg [3:0] rptr_gray_wsync1, rptr_gray_wsync2;
    reg [3:0] wptr_gray_rsync1, wptr_gray_rsync2;

    wire [3:0] rptr_syn_w = rptr_gray_wsync2;
    wire [3:0] wptr_syn_r = wptr_gray_rsync2;

    wire wen = winc && !wfull;
    wire ren = rinc && !rempty;


    dual_port_RAM #(
        .DEPTH(DEPTH),
        .WIDTH(WIDTH)
    ) ram (
        .wclk(wclk),
        .wenc(wen),
        .waddr(wptr_bin_reg),
        .wdata(wdata),
        .rclk(rclk),
        .renc(ren),
        .raddr(rptr_bin_reg),
        .rdata(rdata)
    );


    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn)
            wptr_bin_reg <= 0;
        else if (wen)
            wptr_bin_reg <= wptr_bin_reg + 1;
    end
    assign wptr_bin = wptr_bin_reg;


    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn)
            rptr_bin_reg <= 0;
        else if (ren)
            rptr_bin_reg <= rptr_bin_reg + 1;
    end
    assign rptr_bin = rptr_bin_reg;


    assign wptr_gray = (wptr_bin >> 1) ^ wptr_bin;
    assign rptr_gray = (rptr_bin >> 1) ^ rptr_bin;


    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            rptr_gray_wsync1 <= 0;
            rptr_gray_wsync2 <= 0;
        end else begin
            rptr_gray_wsync1 <= rptr_gray;
            rptr_gray_wsync2 <= rptr_gray_wsync1;
        end
    end


    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            wptr_gray_rsync1 <= 0;
            wptr_gray_rsync2 <= 0;
        end else begin
            wptr_gray_rsync1 <= wptr_gray;
            wptr_gray_rsync2 <= wptr_gray_rsync1;
        end
    end


    assign rempty = (rptr_gray == wptr_syn_r);
    assign wfull = ( (wptr_gray[3] != rptr_syn_w[3]) &&
                    (wptr_gray[2] != rptr_syn_w[2]) &&
                    (wptr_gray[1] == rptr_syn_w[1]) &&
                    (wptr_gray[0] == rptr_syn_w[0]) );

endmodule

