module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

    reg [1:0] current_state, next_state;
    localparam S0 = 2'b00;
    localparam S1 = 2'b01;
    localparam S2 = 2'b10;


    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            current_state <= S0;
        end else begin
            current_state <= next_state;
        end
    end


    always @(*) begin
        case (current_state)
            S0: next_state = (data_in == 1'b0) ? S1 : S0;
            S1: next_state = (data_in == 1'b1) ? S2 : S0;
            S2: begin
                next_state = (data_in == 1'b0) ? S0 : S1;
            end
            default: next_state = S0;
        endcase
    end


    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            data_out <= 1'b0;
        end else begin
            data_out <= (current_state == S2) && (data_in == 1'b0);
        end
    end

endmodule

