module alu (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output reg [31:0] r,
    output reg zero,
    output reg carry,
    output reg negative,
    output reg overflow,
    output reg flag
);

parameter ADD  = 6'b100000;
parameter ADDU = 6'b100001;
parameter SUB  = 6'b100010;
parameter SUBU = 6'b100011;
parameter AND  = 6'b100100;
parameter OR   = 6'b100101;
parameter XOR  = 6'b100110;
parameter NOR  = 6'b100111;
parameter SLT  = 6'b101010;
parameter SLTU = 6'b101011;
parameter SLL  = 6'b000000;
parameter SRL  = 6'b000010;
parameter SRA  = 6'b000011;
parameter SLLV = 6'b000100;
parameter SRLV = 6'b000110;
parameter SRAV = 6'b000111;
parameter LUI  = 6'b001111;

reg [32:0] res_33;
reg [31:0] res;
reg slt_flag;

always @(*) begin
    res = 32'b0;
    res_33 = 33'b0;
    carry = 1'b0;
    overflow = 1'b0;
    slt_flag = 1'b0;
    flag = 1'bz;

    case (aluc)
        ADD: begin
            res = a + b;
            res_33 = {1'b0, a} + {1'b0, b};
            carry = res_33[32];
            overflow = (a[31] == b[31]) && (res[31] != a[31]);
        end
        ADDU: begin
            res = a + b;
            res_33 = {1'b0, a} + {1'b0, b};
            carry = res_33[32];
            overflow = 1'b0;
        end
        SUB: begin
            res = a - b;
            res_33 = {1'b0, a} - {1'b0, b};
            carry = res_33[32];
            overflow = (a[31] != b[31]) && (res[31] != a[31]);
        end
        SUBU: begin
            res = a - b;
            res_33 = {1'b0, a} - {1'b0, b};
            carry = res_33[32];
            overflow = (a[31] != b[31]) && (res[31] != a[31]);
        end
        AND: res = a & b;
        OR:  res = a | b;
        XOR: res = a ^ b;
        NOR: res = ~(a | b);
        SLT: begin
            res = ($signed(a) < $signed(b)) ? 32'd1 : 32'd0;
            slt_flag = ($signed(a) < $signed(b)) ? 1'b1 : 1'b0;
        end
        SLTU: begin
            res = (a < b) ? 32'd1 : 32'd0;
            slt_flag = (a < b) ? 1'b1 : 1'b0;
        end
        SLL: res = b << a[4:0];
        SRL: res = b >> a[4:0];
        SRA: res = $signed(b) >>> a[4:0];
        SLLV: res = b << a[4:0];
        SRLV: res = b >> a[4:0];
        SRAV: res = $signed(b) >>> a[4:0];
        LUI: res = {a[31:16], 16'b0};
        default: res = 32'bz;
    endcase

    if (aluc == SLT || aluc == SLTU) flag = slt_flag;
    else flag = 1'bz;

    r = (aluc == ADDU || aluc == SUBU) ? res_33[31:0] : res;
    zero = (r == 32'b0);
    negative = r[31];
end

endmodule

