        if (!rst_n) begin
            cnt_rise <= 0;
            clk_rise <= 0;
        end else begin
            if (cnt_rise == NUM_DIV - 1) begin
                cnt_rise <= 0;
                clk_rise <= ~clk_rise;
            end else begin
                cnt_rise <= cnt_rise + 1;
            end
        end
    end


    always @(negedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt_fall <= 0;
            clk_fall <= 0;
        end else begin
            if (cnt_fall == NUM_DIV - 1) begin
                cnt_fall <= 0;
                clk_fall <= ~clk_fall;
            end else begin
                cnt_fall <= cnt_fall + 1;
            end
        end
    end

    assign clk_div = clk_rise | clk_fall;

