module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

reg [7:0] saved_dividend, saved_divisor;
reg [15:0] sr_reg;

reg [3:0] cnt;
reg start_cnt;
reg [7:0] neg_divisor;

always @(posedge clk) begin
    if (rst) begin
        saved_dividend <= 8'b0;
        saved_divisor <= 8'b0;
        sr_reg <= 16'b0;
        cnt <= 4'b0;
        start_cnt <= 1'b0;
        neg_divisor <= 8'b0;
        res_valid <= 1'b0;
        result <= 16'b0;
    end else begin
        if (opn_valid && !res_valid) begin

            saved_dividend <= sign ? (dividend[7] ? -dividend : dividend) : dividend;
            saved_divisor <= sign ? (divisor[7] ? -divisor : divisor) : divisor;

            neg_divisor <= -sign ? (divisor[7] ? -divisor : divisor) : divisor;

            sr_reg <= {saved_dividend, 1'b0};
            cnt <= 4'd1;
            start_cnt <= 1'b1;
            res_valid <= 1'b0;
        end

        if (start_cnt) begin
            if (cnt <= 4'd8) begin

                reg [8:0] sub_result = {1'b0, sr_reg[15:8]} - {1'b0, neg_divisor};
                reg [7:0] quo_bit = sub_result[9] ? 8'b0 : 8'b00000001;
                sr_reg <= {sub_result[8:0], sr_reg[7:1]} | quo_bit;
                cnt <= cnt + 1;
            end else begin

                res_valid <= 1'b1;
                result <= {sr_reg[15:8], sr_reg[7:0]};
                start_cnt <= 1'b0;
            end
        end

        if (res_valid && opn_valid) begin
            res_valid <= 1'b0;
        end
    end
end

endmodule

