module fixed_point_adder #(
    parameter Q = 2,
    parameter N = 4
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);

reg [N-1:0] res;

wire sign_a = a[N-1];
wire sign_b = b[N-1];
wire [N-2:0] a_mag = a[N-2:0];
wire [N-2:0] b_mag = b[N-2:0];

wire [N-1:0] sum_mag = a_mag + b_mag;
wire [N-1:0] diff_mag = a_mag - b_mag;

reg sign_result;
reg [N-2:0] mag_result;

always @(*) begin
    if (sign_a == sign_b) begin
        sign_result = sign_a;
        if (sum_mag[N-1]) begin
            mag_result = {1'b0, {(N-2){1'b1}}};

        end else begin
            mag_result = sum_mag[N-2:0];
        end
    end else begin
        if (a_mag > b_mag) begin
            mag_result = a_mag - b_mag;
            sign_result = sign_a;
        end else if (b_mag > a_mag) begin
            mag_result = b_mag - a_mag;
            sign_result = sign_b;
        end else begin
            mag_result = 0;
            sign_result = 0;
        end
    end
end

assign res = {sign_result, mag_result};
assign c = res;

endmodule

