module fixed_point_subtractor #(
    parameter Q = 3,
    parameter N = 8
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output wire [N-1:0] c
);

    reg [N-1:0] res;

    wire sign_a = a[N-1];
    wire sign_b = b[N-1];
    wire same_sign = (sign_a == sign_b);

    wire [N-2:0] integer_a = a[N-2:0];
    wire [Q-1:0] fractional_a = a[Q-1:0];
    wire [N-2:0] integer_b = b[N-2:0];
    wire [Q-1:0] fractional_b = b[Q-1:0];

    wire [N-2:0] integer_sub = integer_a - integer_b;
    wire [Q-1:0] fractional_sub = fractional_a - fractional_b;
    wire [N-1:0] res_same = {sign_a, integer_sub, fractional_sub};

    wire signed [N-1:0] a_signed = a;
    wire signed [N-1:0] b_signed = b;
    wire signed [N-1:0] absolute_a = (a_signed < 0) ? -a_signed : a_signed;
    wire signed [N-1:0] absolute_b = (b_signed < 0) ? -b_signed : b_signed;
    wire [N-1:0] sum = absolute_a + absolute_b;
    wire sign_res = (absolute_a > absolute_b) ? sign_a : sign_b;
    wire [N-1:0] res_diff = {sign_res, sum[N-1:Q], sum[Q-1:0]};

    always @(*) begin
        if (same_sign)
            res = res_same;
        else
            res = res_diff;
    end

    wire zero = (res == 0);
    assign c = zero ? {1'b0, res[N-2:0]} : res;

endmodule

