module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

reg [2:0] counter;
reg [31:0] a_reg, b_reg;
reg a_sign, b_sign;
reg [7:0] a_exponent, b_exponent;
reg [22:0] a_mantissa, b_mantissa;
reg [23:0] a_mantissa_processed, b_mantissa_processed;
reg [47:0] product;
reg guard, round, sticky;
reg [7:0] sum_exp;
reg [7:0] final_exponent;
reg final_sign;
reg [22:0] final_mantissa;

always @(posedge clk) begin
    if (rst) begin
        counter <= 3'b0;
        a_reg <= 0;
        b_reg <= 0;
        a_sign <= 0;
        b_sign <= 0;
        a_exponent <= 0;
        b_exponent <= 0;
        a_mantissa <= 0;
        b_mantissa <= 0;
        a_mantissa_processed <= 0;
        b_mantissa_processed <= 0;
        product <= 0;
        guard <= 0;
        round <= 0;
        sticky <= 0;
        sum_exp <= 0;
        final_exponent <= 0;
        final_sign <= 0;
        final_mantissa <= 0;
        z <= 0;
    end else begin
        case (counter)
            0: begin

                a_reg <= a;
                b_reg <= b;
                a_sign <= a[31];
                b_sign <= b[31];
                a_exponent <= a[30:23];
                b_exponent <= b[30:23];
                a_mantissa <= a[22:0];
                b_mantissa <= b[22:0];

                a_mantissa_processed <= (a_exponent == 0) ? {1'b0, a_mantissa} : {1'b1, a_mantissa};
                b_mantissa_processed <= (b_exponent == 0) ? {1'b0, b_mantissa} : {1'b1, b_mantissa};
                counter <= 1;
            end
            1: begin

                if ((a_exponent == 8'hFF && |a_mantissa) || (b_exponent == 8'hFF && |b_mantissa)) begin

                    z <= {1'b0, 8'hFF, 23'h1};
                end else if ((a_exponent == 8'hFF) || (b_exponent == 8'hFF)) begin

                    z <= {a_sign ^ b_sign, 8'hFF, 23'h0};
                end else if (a_exponent == 0 && b_exponent == 0) begin

                    z <= {a_sign ^ b_sign, 31'h0};
                end else begin

                    product <= a_mantissa_processed * b_mantissa_processed;
                    counter <= 2;
                end
            end
            2: begin

                if (product[47]) begin

                    product <= product >> 1;
                    sum_exp <= (a_exponent + b_exponent) - 9'd127;
                end else begin
                    sum_exp <= (a_exponent + b_exponent) - 9'd127;
                end
                counter <= 3;
            end
            3: begin

                guard <= product[22];
                round <= product[21];
                sticky <= |product[20:0];
                counter <= 4;
            end
            4: begin

                if (guard && (round || sticky)) begin
                    final_mantissa <= product[46:24] + 1;
                end else begin
                    final_mantissa <= product[46:24];
                end

                if (final_mantissa[23]) begin
                    final_mantissa <= final_mantissa >> 1;
                    sum_exp <= sum_exp + 1;
                end
                counter <= 5;
            end
            5: begin

                final_sign <= a_sign ^ b_sign;
                if (sum_exp >= 8'd255) begin
                    z <= {final_sign, 8'hFF, 23'h0};

                end else if (sum_exp == 0) begin
                    z <= {final_sign, 31'h0};

                end else begin
                    z <= {final_sign, sum_exp[7:0], final_mantissa};
                end
                counter <= 0;
            end
            default: counter <= 0;
        endcase
    end
end

