module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output [7:0] clock,
    output red,
    output yellow,
    output green
);

    parameter idle = 2'd0, s1_red = 2'd1, s2_yellow = 2'd2, s3_green = 2'd3;

    reg [1:0] state, next_state;
    reg [7:0] cnt;
    reg p_red, p_yellow, p_green;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            state <= idle;
        else
            state <= next_state;
    end


    always @(*) begin
        case (state)
            idle: next_state = s1_red;
            s1_red: next_state = (cnt == 8'd10) ? s3_green : s1_red;
            s3_green: next_state = (cnt == 8'd60) ? s2_yellow : s3_green;
            s2_yellow: next_state = (cnt == 8'd5) ? s1_red : s2_yellow;
            default: next_state = idle;
        endcase
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            cnt <= 8'd10;
        else if (pass_request && (state == s3_green) && (cnt > 8'd10))
            cnt <= 8'd10;
        else if (!green && p_green)
            cnt <= 8'd60;
        else if (!yellow && p_yellow)
            cnt <= 8'd5;
        else if (!red && p_red)
            cnt <= 8'd10;
        else
            cnt <= cnt - 1;
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            p_red <= 0;
            p_yellow <= 0;
            p_green <= 0;
        end else begin
            p_red <= red;
            p_yellow <= yellow;
            p_green <= green;
        end
    end


    reg r_red, r_yellow, r_green;

    assign red = r_red;
    assign yellow = r_yellow;
    assign green = r_green;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            r_red <= 0;
            r_yellow <= 0;
            r_green <= 0;
        end else begin
            case (state)
                idle: begin
                    r_red <= 0;
                    r_yellow <= 0;
                    r_green <= 0;
                end
                s1_red: begin
                    r_red <= 1;
                    r_yellow <= 0;
                    r_green <= 0;
                end
                s3_green: begin
                    r_red <= 0;
                    r_yellow <= 0;
                    r_green <= 1;
                end
                s2_yellow: begin
                    r_red <= 0;
                    r_yellow <= 1;
                    r_green <= 0;
                end
                default: begin
                    r_red <= 0;
                    r_yellow <= 0;
                    r_green <= 0;
                end
            endcase
        end
    end

    assign clock = cnt;

endmodule

