module alu (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output reg [31:0] r = 0,
    output zero,
    output reg carry = 0,
    output negative,
    output reg overflow = 0,
    output reg flag = 0
);

localparam ADD  = 6'b100000;
localparam ADDU = 6'b100001;
localparam SUB  = 6'b100010;
localparam SUBU = 6'b100011;
localparam AND  = 6'b100100;
localparam OR   = 6'b100101;
localparam XOR  = 6'b100110;
localparam NOR  = 6'b100111;
localparam SLT  = 6'b101010;
localparam SLTU = 6'b101011;
localparam SLL  = 6'b000000;
localparam SRL  = 6'b000010;
localparam SRA  = 6'b000011;
localparam SLLV = 6'b000100;
localparam SRLV = 6'b000110;
localparam SRAV = 6'b000111;
localparam LUI  = 6'b001111;

always @(*) begin
    case (aluc)
        ADD: begin
            r = a + b;
            overflow = (a[31] == b[31]) && (r[31] != a[31]);
            carry = 0;
            flag = 0;
        end
        ADDU: begin
            r = a + b;
            carry = (a + b) > 32'hFFFFFFFF ? 1'b1 : 1'b0;

            overflow = 0;
            flag = 0;
        end
        SUB: begin
            r = a - b;
            overflow = (a[31] != b[31]) && (r[31] != a[31]);
            carry = 0;
            flag = 0;
        end
        SUBU: begin
            r = a - b;
            carry = (a >= b) ? 1'b1 : 1'b0;

            overflow = 0;
            flag = 0;
        end
        AND: begin
            r = a & b;
            overflow = 0;
            carry = 0;
            flag = 0;
        end
        OR: begin
            r = a | b;
            overflow = 0;
            carry = 0;
            flag = 0;
        end
        XOR: begin
            r = a ^ b;
            overflow = 0;
            carry = 0;
            flag = 0;
        end
        NOR: begin
            r = ~(a | b);
            overflow = 0;
            carry = 0;
            flag = 0;
        end
        SLT: begin
            r = ($signed(a) < $signed(b)) ? 32'd1 : 32'd0;
            overflow = 0;
            carry = 0;
            flag = 1'b1;
        end
        SLTU: begin
            r = (a < b) ? 32'd1 : 32'd0;
            overflow = 0;
            carry = 0;
            flag = 1'b1;
        end
        SLL: begin
            r = b << a[4:0];
            overflow = 0;
            carry = 0;
            flag = 0;
        end
        SRL: begin
            r = b >> a[4:0];
            overflow = 0;
            carry = 0;
            flag = 0;
        end
        SRA: begin
            r = $signed(b) >>> a[4:0];
            overflow = 0;
            carry = 0;
            flag = 0;
        end
        SLLV: begin
            r = a << b[4:0];
            overflow = 0;
            carry = 0;
            flag = 0;
        end
        SRLV: begin
            r = a >> b[4:0];
            overflow = 0;
            carry = 0;
            flag = 0;
        end
        SRAV: begin
            r = $signed(a) >>> b[4:0];
            overflow = 0;
            carry = 0;
            flag = 0;
        end
        LUI: begin
            r = {a[15:0], 16'b0};
            overflow = 0;
            carry = 0;
            flag = 0;
        end
        default: begin
            r = 32'bz;
            overflow = 0;
            carry = 0;
            flag = 0;
        end
    endcase
end

assign zero = (r == 32'd0);
assign negative = r[31];
assign flag = (aluc == SLT || aluc == SLTU) ? flag_case : 1'b0;

endmodule

