wire [7:0] abs_dividend_tmp = sign ? (dividend[7] ? (~dividend + 1) : dividend) : dividend;
wire [7:0] abs_divisor_tmp = sign ? (divisor[7] ? (~divisor + 1) : divisor) : divisor;

always @(posedge clk) begin
    if (rst) begin
        SR <= 16'b0;
        cnt <= 4'b0;
        start_cnt <= 1'b0;
        res_valid <= 1'b0;
        dividend_sign <= 1'b0;
        divisor_sign <= 1'b0;
        abs_dividend <= 8'b0;
        abs_divisor <= 8'b0;
        NEG_DIVISOR <= 8'b0;
        result <= 16'b0;
    end else begin
        res_valid <= res_valid;
        if (opn_valid && !res_valid) begin
            dividend_sign <= sign ? dividend[7] : 1'b0;
            divisor_sign <= sign ? divisor[7] : 1'b0;
