                    reg [7:0] rem = dividend_sign ? -SR[15:8] : SR[15:8];
                    reg [7:0] quo = (dividend_sign ^ divisor_sign) ? -SR[7:0] : SR[7:0];
                    result <= {rem, quo};
                end else begin
                    result <= SR;
                end
                res_valid <= 1'b1;
