                reg [15:0] sub_result;
                reg carry_out;
                sub_result = SR - NEG_DIVISOR;
                carry_out = ~sub_result[15];
                SR <= {sub_result[14:0], carry_out};
                cnt <= cnt + 1;
            end
        end
        if (opn_valid && !res_valid) begin
            res_valid <= 1'b0;
        end
    end
