    parameter Q = 8,
    parameter N = 16
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output wire [N-1:0] c
);

reg [N-1:0] res;
wire sign_a = a[N-1];
wire sign_b = b[N-1];
wire [N-2:0] int_a = a[N-2:0];
wire [N-2:0] int_b = b[N-2:0];
wire [Q-1:0] frac_a = a[Q-1:0];
wire [Q-1:0] frac_b = b[Q-1:0];
wire [N-1:0] a_abs = sign_a ? (~a + 1) : a;
wire [N-1:0] b_abs = sign_b ? (~b + 1) : b;

always @* begin
    if (sign_a == sign_b) begin

        if (a_abs >= b_abs)
            res = {sign_a, (a_abs - b_abs)[N-2:0]};
        else
            res = {sign_a, (b_abs - a_abs)[N-2:0]};

        if (res == 0)
            res = 0;
    end else begin

        if (a_abs > b_abs)
            res = {sign_a, (a_abs + b_abs)[N-2:0]};
        else
            res = {sign_b, (b_abs + a_abs)[N-2:0]};
    end
end

assign c = res;

endmodule

