module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

reg [2:0] counter;
reg a_sign, b_sign, z_sign;
reg [9:0] a_exponent, b_exponent, z_exponent;
reg [23:0] a_mantissa, b_mantissa;
reg [47:0] product;
reg guard_bit, round_bit, sticky_bit;
reg [23:0] z_mantissa;
reg [9:0] exp_sum;

wire a_is_nan = (a_exponent == 8'hff) && (a_mantissa[22:0] != 0);
wire a_is_inf = (a_exponent == 8'hff) && (a_mantissa[22:0] == 0);
wire a_is_zero = (a_exponent == 0) && (a_mantissa[22:0] == 0);
wire b_is_nan = (b_exponent == 8'hff) && (b_mantissa[22:0] != 0);
wire b_is_inf = (b_exponent == 8'hff) && (b_mantissa[22:0] == 0);
wire b_is_zero = (b_exponent == 0) && (b_mantissa[22:0] == 0);
wire either_nan = a_is_nan || b_is_nan;
wire either_inf = a_is_inf || b_is_inf;
wire either_zero = a_is_zero || b_is_zero;

always @(posedge clk) begin
    if (rst) begin
        counter <= 3'b0;
        z <= 32'b0;
        a_sign <= 1'b0;
        b_sign <= 1'b0;
        z_sign <= 1'b0;
        a_exponent <= 9'b0;
        b_exponent <= 9'b0;
        z_exponent <= 9'b0;
        a_mantissa <= 24'b0;
        b_mantissa <= 24'b0;
        product <= 48'b0;
        guard_bit <= 1'b0;
        round_bit <= 1'b0;
        sticky_bit <= 1'b0;
        z_mantissa <= 24'b0;
        exp_sum <= 9'b0;
    end else begin
        case (counter)
            3'b000: begin 
                a_sign <= a[31];
                a_exponent <= {1'b0, a[30:23]};
                a_mantissa <= (a[30:23] == 8'h00) ? {1'b0, a[22:0]} : {1'b1, a[22:0]};
                b_sign <= b[31];
                b_exponent <= {1'b0, b[30:23]};
                b_mantissa <= (b[30:23] == 8'h00) ? {1'b0, b[22:0]} : {1'b1, b[22:0]};
                counter <= counter + 1;
            end
            3'b001: begin 
                if (either_nan) begin
                    z_exponent <= 9'h1ff;
                    z_mantissa <= 24'b0;
                    z_sign <= a_sign ^ b_sign;
                end else if (either_inf) begin
                    z_exponent <= 9'h1ff;
                    z_mantissa <= 24'b1;
                    z_sign <= a_sign ^ b_sign;
                end else if (either_zero) begin
                    z <= 32'b0;
                end else begin
                    exp_sum <= a_exponent + b_exponent - 9'd127;
                    product <= a_mantissa * b_mantissa;
                end
                counter <= counter + 1;
            end
            3'b010: begin 
                if (product[47]) begin
                    z_mantissa <= {product[46:23], 1'b0};
                    z_exponent <= exp_sum + 1;
                end else begin
                    z_mantissa <= {product[47:24], 1'b0};
                    z_exponent <= exp_sum;
                end
                guard_bit <= product[23];
                round_bit <= product[22];
                sticky_bit <= |product[21:0];
                counter <= counter + 1;
            end
            3'b011: begin 
                reg [23:0] rounded_mantissa;
                if (guard_bit && (round_bit || sticky_bit || (z_mantissa[0] && (guard_bit && !round_bit && !sticky_bit)))) begin
                    rounded_mantissa = z_mantissa + 24'b1;
                end else begin
                    rounded_mantissa = z_mantissa;
                end
                if (rounded_mantissa[23]) begin
                    z_mantissa <= rounded_mantissa >> 1;
                    z_exponent <= z_exponent + 1;
                end else begin
                    z_mantissa <= rounded_mantissa;
                end
                z_sign <= a_sign ^ b_sign;
                if (z_exponent >= 9'h1fe) begin 
                    z <= {z_sign, 8'hff, 23'b0};
                end else if (z_exponent <= 9'b0) begin 
                    z <= {z_sign, 8'b0, z_mantissa[22:0]};
                end else begin
                    z <= {z_sign, z_exponent[7:0], z_mantissa[22:0]};
                end
                counter <= 3'b000;
            end
        endcase
    end
end

endmodule

