        if (RW == 1'b0) begin 
            if (!FULL) begin
                stack_mem[SP - 1] <= dataIn;
                SP <= SP - 1;
            end
        end else begin 
            if (!EMPTY) begin
                dataOut_reg <= stack_mem[SP - 1];
                SP <= SP + 1;
            end
        end
    end
end

