module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

reg [1:0] state;

localparam IDLE  = 2'b00;
localparam S1    = 2'b01;
localparam S2    = 2'b10;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        data_out <= 1'b0;
    end else begin
        case (state)
            IDLE: begin
                data_out <= 1'b0;
                if (data_in) 
                    state <= IDLE;
                else 
                    state <= S1;
            end
            S1: begin
                data_out <= 1'b0;
                if (data_in) 
                    state <= S2;
                else 
                    state <= IDLE;
            end
            S2: begin
                data_out <= data_in ? 1'b0 : 1'b1;
                state <= data_in ? S1 : IDLE;
            end
            default: begin
                state <= IDLE;
                data_out <= 1'b0;
            end
        endcase
    end
end

endmodule

