module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output reg [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);

parameter idle = 2'b00;
parameter s1_red = 2'b01;
parameter s2_yellow = 2'b10;
parameter s3_green = 2'b11;

reg [1:0] state, next_state;
reg [7:0] cnt;
reg p_red, p_yellow, p_green;


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) state <= idle;
    else state <= next_state;
end


always @(*) begin
    case (state)
        idle: next_state = s1_red;
        s1_red: next_state = (cnt == 0) ? s3_green : s1_red;
        s2_yellow: next_state = (cnt == 0) ? s1_red : s2_yellow;
        s3_green: next_state = (cnt == 0) ? s2_yellow : s3_green;
        default: next_state = idle;
    endcase
end


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) cnt <= 8'd10;
    else begin
        if (pass_request && p_green) cnt <= 8'd10;
        else if ((state != s3_green) && p_green) cnt <= 8'd60;
        else if ((state != s2_yellow) && p_yellow) cnt <= 8'd5;
        else if ((state != s1_red) && p_red) cnt <= 8'd10;
        else if (cnt == 0) cnt <= 8'd0;
        else cnt <= cnt - 1;
    end
end


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) {red, yellow, green} <= 3'b000;
    else {red, yellow, green} <= {p_red, p_yellow, p_green};
end


always @(*) begin
    p_red = red;
    p_yellow = yellow;
    p_green = green;
end

assign clock = cnt;

endmodule

