module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

reg [7:0] saved_dividend_abs, saved_divisor_abs;
reg [8:0] SR;
reg [3:0] cnt;
reg start_cnt;
reg [8:0] NEG_DIVISOR;
reg [7:0] remainder;
reg [7:0] quotient;

always @(posedge clk) begin
    if (rst) begin
        res_valid <= 0;
        cnt <= 0;
        start_cnt <= 0;
        saved_dividend_abs <= 0;
        saved_divisor_abs <= 0;
        SR <= 0;
        NEG_DIVISOR <= 0;
        remainder <= 0;
        quotient <= 0;
        result <= 0;
    end else begin
        if (opn_valid && !res_valid) begin

            if (sign) begin
                saved_dividend_abs <= dividend[7] ? -dividend : dividend;
                saved_divisor_abs <= divisor[7] ? -divisor : divisor;
            end else begin
                saved_dividend_abs <= dividend;
                saved_divisor_abs <= divisor;
            end

            SR <= {saved_dividend_abs, 1'b0};
            NEG_DIVISOR <= -{1'b0, saved_divisor_abs};
            cnt <= 1;
            start_cnt <= 1;
            res_valid <= 0;
        end

        if (start_cnt) begin
            if (cnt == 8) begin

                remainder <= SR[8:1];
                quotient <= SR[0];

                if (sign && remainder[7]) begin
                    remainder <= remainder + saved_divisor_abs;
                end
                result <= {remainder, quotient};
                res_valid <= 1;
                start_cnt <= 0;
                cnt <= 0;
            end else begin

                reg [8:0] sub_result = SR - NEG_DIVISOR;
                reg carry_out = ~sub_result[8];
                SR <= {sub_result[7:0], carry_out};
                cnt <= cnt + 1;
            end
        end else begin
            res_valid <= 0;
        end
    end
end

endmodule

