module accu (
    input clk,
    input rst_n,
    input [7:0] data_in,
    input valid_in,
    output reg valid_out,
    output reg [9:0] data_out
);

reg [9:0] sum_reg;
reg [1:0] count;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        sum_reg <= 10'b0;
        count <= 2'b0;
        valid_out <= 1'b0;
        data_out <= 10'b0;
    end else begin
        valid_out <= 1'b0;
        if (valid_in) begin
            sum_reg <= sum_reg + data_in;
            count <= count + 1;
        end
        if (count == 2'b11 && valid_in) begin
            valid_out <= 1'b1;
            data_out <= sum_reg + data_in;
        end
    end
end

endmodule

