module fixed_point_adder #(
    parameter Q = 4,  
    parameter N = 8   
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);

reg [N-1:0] res;
wire a_sign = a[N-1];
wire b_sign = b[N-1];

wire [N-1:0] abs_a = a_sign ? (~a + 1) : a;
wire [N-1:0] abs_b = b_sign ? (~b + 1) : b;

always @(*) begin
    if (a_sign == b_sign) begin

        res = a + b;
    end else begin
        if (abs_a > abs_b) begin
            res = a - b;
        end else if (abs_b > abs_a) begin
            res = b - a;
        end else begin
            res = {1'b0, {(N-1){1'b0}}};

        end
    end
    c = res;
end

endmodule

