module fixed_point_subtractor #(
    parameter Q = 2,
    parameter N = 4
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output wire [N-1:0] c
);

    reg [N-1:0] res;
    wire same_sign = (a[N-1] == b[N-1]);

    wire [N-1:0] absolute_a = a[N-1] ? (~a + 1) : a;
    wire [N-1:0] absolute_b = b[N-1] ? (~b + 1) : b;

    wire [N-1:0] sum_abs = absolute_a + absolute_b;

    wire sign_res = (absolute_a > absolute_b) ? 1'b0 : 1'b1;

    always @(*) begin
        if (same_sign) begin
            res = a - b;
        end else begin
            res = {sign_res, sum_abs[N-1:0]};
        end


        if (res == 0) begin
            res[N-1] = 1'b0;
        end
    end

    assign c = res;

endmodule

