        case (counter)
            3'b0: begin
                a_sign <= a[31];
                b_sign <= b[31];
                a_exponent <= a[30:23];
                b_exponent <= b[30:23];
                a_mantissa <= (a_exponent != 8'd0) ? {1'b1, a[22:0]} : {1'b0, a[22:0]};
                b_mantissa <= (b_exponent != 8'd0) ? {1'b1, b[22:0]} : {1'b0, b[22:0]};
                counter <= counter + 1;
            end
            3'b1: begin
                if (a_nan || b_nan) begin
                    z <= {1'b0, 8'hff, 23'h400000};
                end else if (a_inf || b_inf) begin
                    if (a_zero || b_zero) begin
                        z <= {1'b0, 8'hff, 23'h400000};
                    end else begin
                        z <= {a_sign ^ b_sign, 8'hff, 23'd0};
                    end
                end else if (a_zero || b_zero) begin
                    z <= {a_sign ^ b_sign, 31'd0};
                end else begin
                    product <= a_mantissa * b_mantissa;
                    exp_sum <= a_exponent + b_exponent;
                    counter <= counter + 1;
                end
