            3'b3: begin

                guard_bit <= product[23];
                round_bit <= product[22];
                sticky <= |product[21:0];
                if (guard_bit && (round_bit || sticky)) begin
                    mantissa_sum <= mantissa_sum + 1;
                    if (mantissa_sum == 24'hffffff) begin
                        exp_sum <= exp_sum + 1;
                    end
                end
                counter <= counter + 1;
            end
            3'b4: begin

                z_exponent <= (exp_sum >= 255) ? 8'hff : exp_sum[7:0];
                z_mantissa <= (exp_sum <= 0) ? 23'd0 : mantissa_sum[22:0];
